INSERT INTO `career_paths` (`career_name`, `after_10th`, `after_12th`, `exams`, `course`, `college_type`, `duration`, `degree`) VALUES
('Doctor', 'Science stream with Biology (Physics, Chemistry, Biology - PCB)', '12th Science (Medical) with minimum 50% marks', 'NEET-UG (National Eligibility cum Entrance Test)', 'MBBS (Medicine) / BDS (Dental) / BAMS (Ayurveda) / BHMS (Homeopathy)', 'Government or Private Medical / Dental / AYUSH College', '5.5 Years (4.5 Years Academic + 1 Year Compulsory Internship)', 'Bachelor Degree (MBBS, BDS, or equivalent)'),
('Nurse', 'Science stream with Biology (Physics, Chemistry, Biology)', '12th Science (Medical / PCB Group) with English', ' NEET / AIIMS Nursing / State Nursing Entrance Exams', 'B.Sc. Nursing / GNM (General Nursing & Midwifery) / ANM (Auxiliary Nursing Midwifery)', 'Nursing College / Medical College', '2–4 years (ANM: 2 yrs, GNM: 3 yrs, B.Sc.: 4 yrs)', 'Bachelor of Science (B.Sc. Nursing) / Diploma (GNM/ANM)'),
('Physiotherapist', 'Science stream with Biology (Physics, Chemistry, Biology)', '12th Science (Medical / PCB Group) with minimum 50% marks', 'State Level CET / NEET (Accepted by some institutes) / IPU CET / University Entrance Exams', 'BPT (Bachelor of Physiotherapy)', 'Physiotherapy College / Medical College', '4.5 Years (4 Years Academic + 6 Months Compulsory Internship)', 'Bachelor of Physiotherapy (BPT)'),
('Lab Technician', 'Science stream with Biology (Physics, Chemistry, Biology)', '12th Science (Medical / PCB Group) with min. 50% marks', 'CUET-UG (for Central Universities), IPU CET, State Paramedical Exams (e.g., JENPAS, KEAM), or Direct Merit Admission', 'BMLT (Bachelor of Medical Lab Technology) OR DMLT (Diploma in Medical Lab Technology)', 'Paramedical College / Medical College / University', 'BMLT: 3.5 Years (3 Years Academic + 6 Months Internship) / DMLT: 2 Years (Diploma)', 'Bachelor Degree (BMLT / B.Sc MLT) or Diploma (DMLT)'),
('Radiology Technician', 'Science stream with Biology (Physics, Chemistry, Biology)', '12th Science (Medical / PCB Group) with min. 50% marks', 'CUET-UG (for Central Universities), IPU CET, State Paramedical Exams (e.g., JENPAS, KEAM), or Direct Merit Admission', 'B.Sc. in Radiology / Medical Imaging Technology (BMIT) OR Diploma in Radiology Technology (DRT)', 'Paramedical College / Medical College / University', 'B.Sc. Radiology: 3 to 4 Years (3 Years Academic + 1 Year Internship) / Diploma (DRT): 2 Years', 'Bachelor of Science (B.Sc. Radiology / BMIT) or Diploma (DRT)'),
('Operation Theatre Technician', 'Science stream with Biology (Physics, Chemistry, Biology)', '12th Science (Medical / PCB Group) with min. 50% marks', 'CUET-UG, IPU CET, State Paramedical Exams (e.g., JENPAS), or Direct Merit Admission', 'B.Sc. in Operation Theatre Technology (B.Sc. OTT) OR Diploma in Operation Theatre Technology (DOTT)', 'Paramedical College / Medical College / Hospital-affiliated Institute', 'B.Sc. OTT: 3 to 4 Years (3 Years Academic + 1 Year Internship) / Diploma (DOTT): 2 Years', 'Bachelor of Science (B.Sc. OTT) or Diploma (DOTT)'),
('Pharmacist', 'Science stream with Biology or Mathematics (Physics, Chemistry, Biology/Maths)', '12th Science (Medical or Non-Medical) with min. 50% marks', 'State CETs (e.g., MHT-CET, GUJCET, KCET), NEET (accepted by some), BITSAT, or University Exams (MET, NMIMS)', 'B.Pharm (Bachelor of Pharmacy) OR Pharm.D (Doctor of Pharmacy) OR D.Pharm (Diploma in Pharmacy)', 'Pharmacy College / University / Medical College', 'B.Pharm: 4 Years / Pharm.D: 6 Years (5 Years Academic + 1 Year Internship) / D.Pharm: 2 Years', 'Bachelor of Pharmacy (B.Pharm) / Doctor of Pharmacy (Pharm.D) / Diploma (D.Pharm)'),
('Medical Researcher', 'Science stream with Biology (Physics, Chemistry, Biology + English)', '12th Science (Medical / PCB Group) with min. 50-60% marks', 'NEET-UG (if via MBBS path) OR CUET-UG, IAT (IISER), NEST (NISER) for B.Sc/BS Research', 'B.Sc. (Biomedical Science / Biotechnology / Microbiology / Life Sciences) OR MBBS / B.Pharm', 'Research Institutes (IISERs, IISc) / Medical Colleges / Universities', 'B.Sc Path: 3 Years (B.Sc) + 2 Years (M.Sc) + 3-5 Years (PhD) / MBBS Path: 5.5 Years + 3 Years (MD) + Research Fellowship', 'Bachelor of Science (B.Sc) / MBBS (Note: A PhD is essential for core scientist roles)'),
('Geneticist', 'Science stream with Biology (Physics, Chemistry, Biology)', '12th Science (Medical / PCB Group) with min. 50-60% marks', 'CUET-UG (for Central Universities), NEST (for NISER), IAT (for IISERs), or University-Specific Exams (e.g., JET, DSAT)', 'B.Sc. (Genetics / Biotechnology / Microbiology / Life Sciences)', 'Science College / Research Institute / University', '3 Years (B.Sc.) + 2 Years (M.Sc.) + PhD (Essential for Research Scientist roles)', 'Bachelor of Science (B.Sc) -> Master of Science (M.Sc) -> PhD'),
('Psychologist', 'Any Stream (Science / Arts / Commerce) – Psychology subject preferred', '12th Board with min. 50% marks', 'CUET-UG (for BHU, DU, Ambedkar University), Christ University Entrance, Tata Institute (TISS-BAT)', 'B.A. / B.Sc. Psychology', 'Arts or Science College / University', '3 or 4 Years (Undergraduate) + 2 Years (Masters)', 'B.A./B.Sc. Psychology -> M.A./M.Sc. Psychology -> M.Phil / Psy.D (Mandatory for RCI License to practice as \"Clinical Psychologist\")'),
('Software Engineer', 'Science stream with Mathematics (Physics, Chemistry, Maths - PCM)', '12th Science (PCM Group) with min. 60–75% marks', 'JEE Mains & JEE Advanced (National), BITSAT, VITEEE, or State CETs (GUJCET, MHT-CET, KCET, WBJEE, AP EAMCET)', 'B.Tech (Bachelor of Technology) / B.E. (Bachelor of Engineering)', 'IITs / NITs / IIITs / State Govt Engineering Colleges (e.g., LD Engineering, COEP, Jadavpur) / Private Universities', '4 Years', 'Bachelor of Technology (B.Tech) / Bachelor of Engineering (B.E.)'),
('Data Scientist', 'Science stream with Mathematics (Physics, Chemistry, Maths - PCM)', '12th Science (PCM Group) with min. 60–75% marks', 'JEE Mains & JEE Advanced (National), BITSAT, VITEEE, or State CETs (GUJCET, MHT-CET, KCET, WBJEE, AP EAMCET)', 'B.Tech in Computer Science (CSE) with Specialization in Data Science / AI & ML OR B.Sc / BCA in Data Science (followed by M.Sc/MCA for top roles)', 'IITs / NITs / IIITs / State Govt Engineering Colleges (e.g., LD Engineering, COEP, Jadavpur) / Private Universities', '4 Years (B.Tech) or 3 Years (B.Sc/BCA)', 'Bachelor of Technology (B.Tech) / Bachelor of Science (B.Sc)'),
('Computer Engineer', 'Science stream with Mathematics (Physics, Chemistry, Maths - PCM)', '12th Science (PCM Group) with min. 60–75% marks', 'JEE Mains & JEE Advanced (National), BITSAT, VITEEE, or State CETs (GUJCET, MHT-CET, KCET, WBJEE, AP EAMCET)', 'B.Tech / B.E. in Computer Engineering (CE) or Computer Science & Engineering (CSE)', 'IITs / NITs / IIITs / State Govt Engineering Colleges (e.g., LD Engineering, COEP, Jadavpur) / Private Universities', '4 Years', 'Bachelor of Technology (B.Tech) / Bachelor of Engineering (B.E.)'),
('Mechanical Engineer', 'Science stream with Mathematics (Physics, Chemistry, Maths - PCM)', '12th Science (PCM Group) with min. 60–75% marks', 'JEE Mains & JEE Advanced (National), BITSAT, VITEEE, or State CETs (GUJCET, MHT-CET, KCET, WBJEE, AP EAMCET)', 'B.Tech / B.E. in Mechanical Engineering (ME) or B.Tech in Mechatronics / Automobile Engineering', 'IITs / NITs / IIITs / State Govt Engineering Colleges (e.g., LD Engineering, COEP, Jadavpur) / Private Universities', '4 Years', 'Bachelor of Technology (B.Tech) / Bachelor of Engineering (B.E.)'),
('Civil Engineer', 'Science stream with Mathematics (Physics, Chemistry, Maths - PCM)', '12th Science (PCM Group) with min. 60–75% marks', 'JEE Mains & JEE Advanced (National), BITSAT, VITEEE, or State CETs (GUJCET, MHT-CET, KCET, WBJEE, AP EAMCET)', 'B.Tech / B.E. in Civil Engineering (Optional: Specialization in Construction Technology / Infrastructure Engineering)', 'IITs / NITs / IIITs / State Govt Engineering Colleges (e.g., LD Engineering, COEP, Jadavpur) / Private Universities', '4 Years', 'Bachelor of Technology (B.Tech) / Bachelor of Engineering (B.E.)'),
('Electrical Engineer', 'Science stream with Mathematics (Physics, Chemistry, Maths - PCM)', '12th Science (PCM Group) with min. 60–75% marks', 'JEE Mains & JEE Advanced (National), BITSAT, VITEEE, or State CETs (GUJCET, MHT-CET, KCET, WBJEE, AP EAMCET)', 'B.Tech / B.E. in Electrical Engineering (EE) or Electrical & Electronics Engineering (EEE)', 'IITs / NITs / IIITs / State Govt Engineering Colleges (e.g., LD Engineering, COEP, Jadavpur) / Private Universities', '4 Years', 'Bachelor of Technology (B.Tech) / Bachelor of Engineering (B.E.)'),
('Electronics Engineer', 'Science stream with Mathematics (Physics, Chemistry, Maths - PCM)', '12th Science (PCM Group) with min. 60–75% marks', 'JEE Mains & JEE Advanced (National), BITSAT, VITEEE, or State CETs (GUJCET, MHT-CET, KCET, WBJEE, AP EAMCET)', 'B.Tech / B.E. in Electronics & Communication (ECE) or Electronics & Telecommunication (ENTC)', 'IITs / NITs / IIITs / State Govt Engineering Colleges (e.g., LD Engineering, COEP, Jadavpur) / Private Universities', '4 Years', 'Bachelor of Technology (B.Tech) / Bachelor of Engineering (B.E.)'),
('Chemical Engineer', 'Science stream with Mathematics (Physics, Chemistry, Maths - PCM)', '12th Science (PCM Group) with min. 60–75% marks', 'JEE Mains & JEE Advanced (National), BITSAT, VITEEE, or State CETs (GUJCET, MHT-CET, KCET, WBJEE, AP EAMCET)', 'B.Tech / B.E. in Chemical Engineering', 'IITs / NITs / IIITs / State Govt Engineering Colleges (e.g., LD Engineering, COEP, Jadavpur) / Private Universities', '4 Years', 'Bachelor of Technology (B.Tech) / Bachelor of Engineering (B.E.)'),
('Aerospace Engineer', 'Science stream with Mathematics (Physics, Chemistry, Maths - PCM)', '12th Science (PCM Group) with min. 60–75% marks', 'JEE Mains & JEE Advanced (National), BITSAT, VITEEE, or State CETs (GUJCET, MHT-CET, KCET, WBJEE, AP EAMCET) / IIST Specific: Admission to IIST (Indian Institute of Space Science and Technology) is via JEE Advanced Rank (This is the direct route to ISRO).', 'B.Tech / B.E. in Aerospace Engineering or Aeronautical Engineering or Avionics', 'IITs (Bombay, Madras, Kharagpur, Kanpur) / IIST Thiruvananthapuram / Top Private (Manipal, SRM) / State Govt Colleges (e.g., BMS Bangalore, MIT Chennai)', '4 Years', 'Bachelor of Technology (B.Tech) / Bachelor of Engineering (B.E.)'),
('Automobile Engineer', 'Science stream with Mathematics (Physics, Chemistry, Maths - PCM)', '12th Science (PCM Group) with min. 60–75% marks', 'JEE Mains & JEE Advanced (National), BITSAT, VITEEE, or State CETs (GUJCET, MHT-CET, KCET, WBJEE, AP EAMCET)', 'B.Tech / B.E. in Automobile Engineering or Mechanical Engineering (with Specialization in EV / Automotive)', 'IITs / NITs / IIITs / State Govt Engineering Colleges (e.g., LD Engineering, COEP, Jadavpur) / Private Universities', '4 Years', 'Bachelor of Technology (B.Tech) / Bachelor of Engineering (B.E.)'),
('IT Engineer', 'Science stream with Mathematics (Physics, Chemistry, Maths - PCM)', '12th Science (PCM Group) with min. 60–75% marks', 'JEE Mains & JEE Advanced (National), BITSAT, VITEEE, or State CETs (GUJCET, MHT-CET, KCET, WBJEE, AP EAMCET)', 'B.Tech (Bachelor of Technology) / B.E. (Bachelor of Engineering)', 'IITs / NITs / IIITs / State Govt Engineering Colleges (e.g., LD Engineering, COEP, Jadavpur) / Private Universities', '4 Years', 'Bachelor of Technology (B.Tech) / Bachelor of Engineering (B.E.)'),
('Research Scientist', 'Science stream with Mathematics and/or Biology (PCM / PCB / PCMB)', '12th Science with min. 60–75% marks', 'After 12th: IAT (IISER Aptitude Test), NEST (for NISER), JEE Advanced (for IISc Bangalore), CUET (Central Universities)  // After Bachelor\'s: GATE (Engineering/Science), JAM (Joint Admission Test for Masters), JEST', 'B.Sc + M.Sc (Dual Degree) or B.S. + M.S. (Research) or Integrated M.Sc-PhD', 'IISc (Indian Institute of Science) / IISERs (Indian Institutes of Science Education and Research) / NISER / IITs / TIFR', '9 to 10 Years (3-4 Yrs Bachelors + 2 Yrs Masters + 3-5 Yrs PhD) (Note: A PhD is almost mandatory for a core \"Scientist\" title)', 'Bachelor of Science (B.S./B.Sc) -> Master of Science (M.S./M.Sc) -> Doctor of Philosophy (PhD)'),
('Scientist', 'Science stream with Mathematics (Physics, Chemistry, Maths - PCM)', '12th Science (PCM Group) with min. 75% marks', 'For B.Tech Route (ISRO/DRDO): JEE Mains & JEE Advanced (for IIST/IITs)  OR For B.Sc/Research Route: IAT (IISERs), NEST (NISER), CUET', 'Option 1 (Engineering): B.Tech in Aerospace / Electronics / Mechanical / Computer Science OR Option 2 (Pure Science): B.S. / B.Sc + M.Sc (Physics / Chemistry / Maths)', 'IIST Thiruvananthapuram (Direct ISRO Absorption) / IITs / IISERs / NITs', 'Engineering Route: 4 Years (B.Tech)  // Science Route: 5 Years (Integrated B.S.-M.S.) // Research Route: ~8–10 Years (if pursuing PhD for higher Scientist roles)', 'Bachelor of Technology (B.Tech) OR Bachelor of Science - Master of Science (B.S.-M.S.)'),
('Research Officer', 'Science stream with Biology or Mathematics (Physics, Chemistry, Biology/Maths)', '12th Science (Medical or Non-Medical) with min. 60–75% marks', 'For Medical/Ayush Track: NEET-UG (for MBBS/BAMS), then AIAPGET (for MD/MS) OR For Pure Science Track: CSIR-UGC NET (for JRF), ICMR-JRF, GATE', 'Option 1 (Medical): MBBS / BAMS (Ayurveda) / BHMS -> MD/MS  OR Option 2 (Science): M.Sc (Microbiology / Biotechnology / Statistics) + PhD (Highly Preferred)', 'AIIMS / National Institutes (NIN, NARI) / Central Universities / Govt Ayurvedic Colleges', 'Medical Path: 5.5 Years (UG) + 3 Years (PG) = ~8.5 Years OR Science Path: 3 Years (B.Sc) + 2 Years (M.Sc) + 3-5 Years (PhD) = ~8–10 Years', 'MD / MS / PhD (Doctor of Philosophy)'),
('Professor', 'Any Stream (Science / Commerce / Arts) depending on your subject of interest.', 'Bachelor’s Degree (B.A. / B.Sc / B.Com / B.Tech) with min. 55% marks', 'For Lectureship (Colleges): UGC-NET (Humanities/Commerce) or CSIR-NET (Science) or SET (State Eligibility Test) OR For PhD Admission: GATE (Engineering) or NET (now valid for PhD admission too) OR For Engineering Professors: GATE + M.Tech is the minimum; PhD preferred.', 'Master’s Degree (M.A. / M.Sc / M.Tech / M.Com) in relevant subject -> PhD (Doctor of Philosophy)', 'Central Universities (DU, JNU, BHU) / IITs / NITs / State Universities / Private Colleges', 'Education: 3-4 Years (Bachelor) + 2 Years (Master) + 4-6 Years (PhD) = Total ~10-12 Years after 12th  OR Note: You can start teaching as an Assistant Professor after Master\'s + NET (approx. 6 years af', 'Master of Arts/Science (M.A./M.Sc) -> PhD (Mandatory for promotion to Senior Professor)'),
('Lecturer', 'Any Stream (Science / Commerce / Arts)', '12th in Any Stream with min. 50-60% marks', 'For Admission: CUET-UG (for Central Universities)  OR For Job Eligibility: UGC-NET (for Arts/Commerce), CSIR-NET (for Science), or SET (State Eligibility Test)', ' Bachelor’s Degree (3/4 Years) Master’s Degree (2 Years) in your subject\n(Critically Important: You must score min. 55% in Master’s to be eligible for NET)', 'Central Universities (DU, JNU, BHU) / State Universities / Private Colleges', '5 to 6 Years (3 yrs Bachelor + 2 yrs Master)', 'Master of Arts (M.A.) / Master of Science (M.Sc) / M.Com + NET Qualified'),
('Chartered Accountant', 'Commerce stream', '12th in Commerce with min 50%', 'CA Foundation (Entrance Exam held in June/September/January).', 'CA Foundation (4 Papers) OR  CA Intermediate (6 Papers in 2 Groups) OR  Articleship (Practical Training) OR CA Final (6 Papers in 2 Groups)', 'The course is conducted by ICAI (Institute of Chartered Accountants of India). You do not need a college, but many students pursue B.Com simultaneously via distance (IGNOU) or regular college.', 'Approx. 4.5 to 5 Years (if cleared in first attempts)', 'Member of ICAI (Designated as Chartered Accountant)'),
('Company Secretary', 'Commerce stream (preferred) or any stream (Science/Arts).', '12th in Any Stream (except Fine Arts). Note: You can register for the entrance exam while appearing ', 'CSEET (CS Executive Entrance Test). (Direct Entry Route: Graduates with min. 50% marks can skip CSEET and directly join the Executive Level).', ' CSEET (Entrance Exam - 4 Papers) OR CS Executive Programme (7 Papers in 2 Groups) OR CS Professional Programme (7 Papers + Electives) ORPractical Training (21 Months mandatory training in a firm/company)', 'The course is conducted by ICSI (Institute of Company Secretaries of India). It is a distance-learning course, so you do not need a regular college.', 'Approx. 3 to 4 Years (if cleared in first attempts).', 'Associate Member of ICSI (ACS).'),
('Cost & Management Accountant', 'Commerce stream', '12th in Commerce with min 50%', 'CMA Foundation (Entrance Exam held in June/December). (Direct Entry Route: Graduates with min. 50% marks can skip Foundation and enter directly at Intermediate Level).', ' CMA Foundation (4 Papers) OR CMA Intermediate (8 Papers in 2 Groups) OR Practical Training (15 Months mandatory training in a firm/company) OR CMA Final (8 Papers in 2 Groups)', 'The course is conducted by ICMAI (Institute of Cost Accountants of India). Like CA, this is a distance-learning course, often pursued alongside B.Com.', 'Approx. 3 to 4 Years (if cleared in first attempts).', 'Member of ICMAI (Designated as ACMA / FCMA).'),
('Accountant', 'Commerce stream', '12th in Commerce with min. 50–60% marks.', 'University Admission: CUET-UG (for Central Universities like DU, BHU), State University Entrance Exams. OR Job Recruitment: SSC CGL (for Divisional Accountant/Auditor), State PSC Exams (e.g., Rajasthan/UP Junior Accountant).', 'B.Com (Bachelor of Commerce) or B.Com (Hons). (Highly Recommended: Add a certification in Tally Prime, SAP FICO, or Advanced Excel during graduation).', 'Central Universities / State Govt Colleges / Private Colleges.', '3 Years (Standard B.Com) or 4 Years (B.Com Hons with Research under NEP).', 'Bachelor of Commerce (B.Com).'),
('Financial Analyst', 'Commerce stream with Mathematics', '12th Commerce / Science with min. 60–75% marks.', 'CUET-UG (for Central Universities), NMIMS-NPAT, IPMAT (for IIMs Integrated Course).', 'B.Com (Hons) / BBA (Finance) / B.Sc Finance. (Highly Recommended: Start CFA (Chartered Financial Analyst) or FRM (Financial Risk Manager) alongside graduation).', 'Top Commerce Colleges (SRCC, Loyola, St. Xaviers) / IIMs (Integrated MBA) / Private Universities (NMIMS, Symbiosis).', '3 Years (Bachelor’s) + 2-3 Years (CFA/MBA) = ~5 to 6 Years for a stable career start.', 'Bachelor’s Degree + CFA Charter (Gold Standard) or MBA in Finance.'),
('Business Analyst', 'Commerce or Science stream (Mathematics is highly recommended for data logic)', '12th in Any Stream (Science/Commerce preferred) with min. 60% marks.', 'For MBA Route: CAT, MAT, XAT, NMAT (for admission to MBA Business Analytics).', 'Option 1 (Degree): B.Tech / B.Com / BBA $\\rightarrow$ MBA in Business Analytics. OR Option 2 (Direct): Any Graduate $\\rightarrow$ ECBA Certification (Global Standard) + Skills (SQL/PowerBI).', 'IIMs (for MBA) / Private B-Schools (Symbiosis, NMIMS) / IIBA (International Institute of Business Analysis) for certifications.', 'MBA Route: 3 Years (Bachelor) + 2 Years (MBA) = 5 Years.', 'MBA (Business Analytics) or Certified Business Analysis Professional (CBAP - for experienced).'),
('Marketing Manager', 'Any Stream', '12th in Any Stream with min. 50-60% marks', 'For BBA Admission: CUET-UG (Central Univs), IPMAT (IIMs), NPAT (NMIMS), SET (Symbiosis). OR For MBA Admission: CAT (IIMs), XAT (XLRI), SNAP, NMAT, MAT.', 'Undergraduate: BBA (Marketing) / B.Com / B.Tech (Engineers often shift to Marketing). OR Postgraduate (The Main Route): MBA in Marketing / PGDM in Marketing Management.', 'IIMs (Ahmedabad, Bangalore, Calcutta) / XLRI / SP Jain / FMS Delhi / NMIMS / Symbiosis.', 'BBA Path: 3 Years (BBA) + 2 Years (MBA) = 5 Years. OR Engineering Path: 4 Years (B.Tech) + 2 Years (MBA) = 6 Years.', 'Master of Business Administration (MBA) / Post Graduate Diploma in Management (PGDM).'),
('Human Resource Manager', 'Any Stream', '12th in Any Stream with min. 50–60% marks.', 'For MBA (Top B-Schools): CAT (IIMs), XAT (XLRI - The Best for HR), SNAP (Symbiosis), NMAT. OR For TISS (The \"HR Holy Grail\"): CUET-PG (Tata Institute of Social Sciences has scrapped TISSNET and now accepts CUET-PG scores).', 'Route 1 (MBA): MBA in Human Resource Management (HRM). OR Route 2 (TISS): M.A. in HRM & Labour Relations (considered equivalent to an MBA but focuses more on laws and psychology).', 'XLRI Jamshedpur (Rank #1 for HR in India) / TISS Mumbai / MDI Gurgaon / SCMHRD Pune / IIM Ranchi.', '3 Years (Bachelor’s) + 2 Years (MBA/M.A.) = 5 Years.', 'MBA (HR) / M.A. (HRM & LR).'),
('Supply Chain Manager', 'Any Stream', '12th in Any Stream with min. 50–60% marks.', 'For BBA/B.Tech: CUET-UG (Central Univs), IPMAT (IIM Indore/Rohtak), JEE Mains (for Industrial Engineering).', 'Route 1 (Technical): B.Tech in Mechanical / Production / Industrial Engineering $\\rightarrow$ MBA in Operations/SCM. OR Route 2 (Management): BBA (Logistics & SCM)  MBA in Supply Chain Management.', 'Tier 1 (The \"Mecca\"): IIM Mumbai (formerly NITIE) - The best college for SCM in India. OR Others: IITs (DOMS), SP Jain (Mumbai), SIOM (Nashik), IIFT (Delhi/Kolkata).', '4 Years (B.Tech) + 2 Years (MBA) = 6 Years.', 'MBA (Operations & Supply Chain Management) / PGDIE (Post Graduate Diploma in Industrial Engineering).'),
('Export Import Manager', 'Any Stream ', '12th in Any Stream (Commerce preferred) with min. 50–60% marks.', 'For Master\'s (The Main Route): CAT (for IIFT & IIMs), NMAT, SNAP (Symbiosis), CUET-PG (for BHU/Foreign Trade specialized colleges). OR Note on IIFT: The Indian Institute of Foreign Trade (IIFT), India\'s premier college for this field, now largely accepts CAT Scores for its flagship MBA (IB) instead of its separate entrance exam (check latest notification).', 'Route 1 (Degree): BBA (Foreign Trade / International Business)  MBA in International Business (IB). OR Route 2 (Diploma): Graduate $\\rightarrow$ PG Diploma in Export Import Management (from institutes like IIFT, Welingkar, or Foreign Trade Development Centre).', 'Tier 1: IIFT (New Delhi/Kolkata/Kakinada) - The Gold Standard. OR Others: Symbiosis Institute of International Business (SIIB), MDI Gurgaon, AMITY (for specialized IB courses).', '3 Years (BBA) + 2 Years (MBA) = 5 Years. (Diploma courses can be 6 months to 1 year).', 'MBA (International Business) / Masters in International Business (MIB) / PG Diploma in Foreign Trade'),
('Banking Officer', 'Commerce stream (preferred for financial base) or Science (for strong Maths/Analytical skills).', '12th in Any Stream (Commerce/Science/Arts) with min. 60% marks.', 'For Public Sector Banks: IBPS PO (Institute of Banking Personnel Selection), SBI PO (State Bank of India - Separate Exam). OR For Regional Rural Banks: IBPS RRB PO (Officer Scale I). OR For Regulatory Bodies: RBI Grade B (The most prestigious banking exam), NABARD Grade A.', 'There is no specific \"Banking\" degree required, but B.Com or B.Sc (Maths) helps in the interview.', 'Any UGC-recognized University (Open University degrees like IGNOU are also valid).', '3 Years (Graduation) + 6-12 Months (Exam Preparation).', 'Bachelor’s Degree + Bank Exam Qualification.'),
('Lawyer', 'Any Stream ', '12th in Any Stream with min. 45% marks (General) or 40% (SC/ST).', 'National: CLAT (Common Law Admission Test) for NLUs, AILET (NLU Delhi). OR Private/Other: SLAT (Symbiosis), LSAT-India, MHCET Law (Maharashtra).For License (Mandatory): AIBE (All India Bar Examination) after graduation to practice in courts.', 'Route 1 (After 12th): 5-Year Integrated LLB (B.A. LL.B. / B.B.A. LL.B. / B.Com. LL.B.). OR Route 2 (After Graduation): 3-Year LL.B. (if you already have a Bachelor\'s degree).', 'National Law Universities (NLUs) - The IITs of Law / Faculty of Law (DU) / Symbiosis / Jindal Global Law School.', '5 Years (Integrated) or 3 Years (after Graduation)', 'Bachelor of Laws (LL.B.) / B.A. LL.B. (Hons).'),
('Legal Officer', 'Any Stream', '12th in Any Stream with min. 45% marks.', 'For College Admission: CLAT (for NLUs), AILET, MH-CET Law', ' Route 1: 5-Year Integrated LLB (B.A. LL.B / B.B.A. LL.B). OR Route 2: Any Graduation $\\rightarrow$ 3-Year LL.B.', 'National Law Universities (NLUs) / Faculty of Law (DU) / Top Private Law Colleges (Symbiosis, Jindal).', '5 Years (Integrated LLB) or 3 Years (Grad) + 3 Years (LLB) = 6 Years. (Note: For IBPS SO, you usually need to be enrolled as an Advocate with the Bar Council, which takes ~1-2 months after graduation)', 'Bachelor of Laws (LL.B) + Bar Council Enrollment (Mandatory for Banks).'),
('Public Policy Analyst', 'Any Stream (Humanities/Arts preferred for Political Science/Sociology base, but Science/Commerce are', '12th in Any Stream with min. 60% marks.', 'For Masters (The Primary Route): CUET-PG (for TISS, JNU), CAT / XAT / GMAT (for IIMs and ISB Public Policy courses).', 'Undergraduate: B.A. (Hons) in Political Science / Economics / Sociology or B.Tech (for Technology Policy). OR Postgraduate (Mandatory for Analysts): Master of Public Policy (MPP) or M.A. in Public Policy & Governance.', 'Tier 1: TISS (Mumbai/Hyderabad), NLSIU (Bengaluru - MPP), IIM Bangalore (CPP), ISB (Bharti Institute), Jindal School of Government (JSGP). OR International: Harvard Kennedy School, LSE (common for Indian analysts to go abroad after 2-3 years of work).', '3-4 Years (Bachelor’s) + 2 Years (Masters) = ~5 to 6 Years.', 'Master of Public Policy (MPP) / M.A. Development Studies.'),
('Criminologist', 'Any Stream (Arts/Humanities is most common for Criminology; Science is preferred if you want to ente', '12th in Any Stream with min. 50–60% marks.', 'CUET-UG (for Central Universities like Delhi University), AIFSET (for Forensic Science), or University-specific exams (e.g., Karunya, NFSU).', 'Route 1 (Degree): B.A. / B.Sc in Criminology & Police Administration $\\rightarrow$ M.A. / M.Sc in Criminology. OR Route 2 (Psychology Base): B.A. Psychology $\\rightarrow$ M.Sc in Criminal Psychology / Forensic Psychology. OR Route 3 (Law Base): LL.B $\\rightarrow$ LL.M in Criminology (for legal criminology roles).', 'Tier 1: National Forensic Sciences University (NFSU) (Gandhinagar/Delhi) - The Gold Standard. OR Others: TISS (Mumbai), University of Madras, Tata Institute of Social Sciences, Guru Gobind Singh Indraprastha University (GGSIPU).', '3 Years (Bachelor\'s) + 2 Years (Master\'s) = 5 Years. ', 'M.Sc / M.A. in Criminology / Forensic Psychology.'),
('Graphic Designer', 'Any Stream', '12th in Any Stream with min 50%', 'NID DAT (National Institute of Design), UCEED (IITs), NIFT (Fashion Communication), SEED (Symbiosis). OR If you are Fain then Also Join Some Classes and Learn From Youtube', 'B.Des (Bachelor of Design) or BFA (Bachelor of Fine Arts).', 'NIDs / IITs (IDC) / NIFT / Government Art Colleges.', '4 Years (Professional Degree).', 'Bachelor of Design (B.Des) / BFA.'),
('UI/UX Designer', 'Any Stream', '12th in Any Stream with min 50%', 'National: UCEED (for IITs - Hardest), NID DAT (National Institute of Design - Most Creative). OR  Private/Other: SEED (Symbiosis), MIT-DAT (Pune), Srishti Manipal Entrance.  OR  If you are Fain then Also Join Some Classes and Learn From Youtube', 'B.Des (Bachelor of Design) in Interaction Design / UX Design / Visual Communication.', 'IIT Bombay (IDC) / IIT Guwahati / NID (Ahmedabad/Bengaluru) / IIIT Delhi / Srishti Manipal.IIT Bombay (IDC) / IIT Guwahati / NID (Ahmedabad/Bengaluru) / IIIT Delhi / Srishti Manipal.', '4 Years (Professional Degree).', 'Bachelor of Design (B.Des) / M.Des (if pursuing Masters).'),
('Product Designer', 'Any Stream', '12th in Any Stream with min 50%', ' National: UCEED (IITs), NID DAT (National Institute of Design), CEED (for M.Des). OR  Private: SEED (Symbiosis), MIT-DAT (Pune), Srishti Manipal Entrance.', 'B.Des (Bachelor of Design) in Product Design / Interaction Design.', ' Tier 1: IIT Bombay (IDC), IIT Guwahati, NID Ahmedabad, IIIT Delhi. OR Tier 2: Symbiosis (SID), MIT Pune, Srishti Manipal.', '4 Years (Professional Degree).', 'Bachelor of Design (B.Des).'),
('Fashion Designer', 'Any Stream', '12th in Any Stream with min. 50% marks.', 'National: NIFT Entrance Exam (GAT + CAT) – The \"IIT-JEE\" of Fashion, NID DAT (National Institute of Design). OR Private/Other: Pearl Academy Entrance, SEED (Symbiosis), IIAD (Indian Institute of Art and Design).', 'Design Route: B.Des (Bachelor of Design) in Fashion Design / Textile Design / Knitwear Design. OR Tech Route: B.F.Tech (Bachelor of Fashion Technology) – Only for Science (PCM) students; focuses on manufacturing & machinery.', 'Tier 1: NIFT (Delhi/Mumbai/Bengaluru), NID (Ahmedabad), Pearl Academy (Delhi/Mumbai). OR Tier 2: Symbiosis Institute of Design (Pune), Amity School of Fashion.', '4 Years (Professional Degree).', 'Bachelor of Design (B.Des) / Bachelor of Fashion Technology (B.F.Tech).'),
('Interior Designer', 'Any Stream', '12th in Any Stream with min. 50% marks.', 'National: NID DAT (National Institute of Design), UCEED (IITs - for B.Des), AIEED (Arch College of Design). OR Specific: NATA (Council of Architecture) – Only required if you want to do B.Arch and then specialize in Interiors.OR Private: SEED (Symbiosis), Pearl Academy Entrance, CEPT Entrance (Ahmedabad).', 'Design Degree: B.Des (Interior Design) – 4 Years (Focus on Space, Furniture, Aesthetics). OR Science Degree: B.Sc (Interior Design) – 3 Years (Focus on technical aspects). OR Architecture Route: B.Arch M.Des (Interior Design).', 'Tier 1: NID (Ahmedabad), CEPT University (The best for Interior Architecture), JJ School of Arts (Mumbai). OR Tier 2: Pearl Academy, Symbiosis (SID), Manipal University.', '4 Years (B.Des) or 3 Years (B.Sc).', 'Bachelor of Design (B.Des) / B.Sc Interior Design'),
('Animator', 'Any Stream', '12th in Any Stream with min. 50% marks.', 'National: NID DAT (National Institute of Design), UCEED (for IIT Bombay IDC), NIFT (for Communication Design). OR Private/Other: Pearl Academy Entrance, WWI Entrance (Whistling Woods), SEED (Symbiosis).OR You can join clasees or Learn from Youtube For Free', 'Degree: B.Des (Animation Film Design) or B.Sc (Animation & VFX). OR Advanced: M.Des (Animation) – Highly respected at IDC IIT Bombay & NID.', 'Tier 1: NID (Ahmedabad/Bengaluru), IDC IIT Bombay, Whistling Woods International (Mumbai). OR Tier 2: MIT Institute of Design (Pune), Srishti Manipal, Satyajit Ray Film & Television Institute (SRFTI).', '4 Years (B.Des) or 3 Years (B.Sc).', 'Bachelor of Design (B.Des) / B.Sc in Animation.'),
('Video Editor', 'Any Stream', '12th in Any Stream with min. 50% marks.', 'National: FTII JET (Joint Entrance Test for Film & Television Institute of India), SRFTI Entrance (Satyajit Ray Film & TV Institute). OR Private/Other: WWI Entrance (Whistling Woods), XIC OET (Xavier Institute of Communications). OR You Can Learn from youtube for free', 'Degree: B.A. / B.Sc in Filmmaking / Mass Communication / Visual Communication. OR Diploma: PG Diploma in Film Editing (Highly respected if from FTII/SRFTI).', 'Tier 1 (The \"IITs of Film\"): FTII (Pune), SRFTI (Kolkata) OR Tier 2: Whistling Woods (Mumbai), Asian Academy of Film & Television (AAFT), Symbiosis Centre for Media & Communication (SCMC).', '3 Years (Degree) or 1-2 Years (PG Diploma).', 'B.A. in Film & Media / Diploma in Video Editing.'),
('Photographer', 'Any Stream', '12th in Any Stream with min. 50% marks.', 'National: NID DAT (National Institute of Design - Photography Design), CUET-PG (for AJK MCRC Jamia), FTII JET. OR Private/Other: WWI Entrance (Whistling Woods), Symbiosis Entrance (SET). OR You can also learn from yourself If you love Photography With Basic Things  ', 'Degree: B.A. in Visual Arts (Photography) / B.Des in Photography Design / BFA (Applied Arts). OR Diploma: PG Diploma in Still Photography (AJK MCRC Jamia is the most prestigious for this).', 'Tier 1: NID (Gandhinagar), AJK MCRC (Jamia Millia Islamia, Delhi), Sir JJ Institute of Applied Art (Mumbai). OR Tier 2: Symbiosis School of Photography (Pune), Light & Life Academy (Ooty), Pearl Academy. ', '3-4 Years (Degree) or 1 Year (PG Diploma)', 'Bachelor of Fine Arts (BFA) / B.Des / Diploma.'),
('Content Creator', 'Any Stream', '12th in Any Stream. OR You can do without study also', 'University Level: CUET-UG (for Mass Media/Journalism courses in Central Universities). OR Private: SET (Symbiosis), MET (Manipal), IIDE Entrance (Digital Marketing).', 'Degree: BMM (Bachelor of Mass Media) / B.A. in Digital Marketing / B.A. Journalism. OR Certification: Google Digital Garage / Meta Social Media Marketing Professional Certificate', 'Tier 1: Symbiosis Centre for Media & Communication (SCMC), Xavier Institute of Communications (XIC), MICA (Ahmedabad). OR Tier 2: Whistling Woods International (Mumbai), IIDE (Indian Institute of Digital Education).', '3 Years (Degree).', 'B.A. Mass Communication / B.B.A Digital Marketing'),
('Digital Marketer', 'Any Stream', '12th in Any Stream with min. 50% marks.', 'National: CAT, XAT, NMAT (for MBA Marketing). OR University: CUET-UG (for BBA/B.Com Marketing).', 'Degree: BBA (Digital Marketing) / BBA (Marketing)  MBA in Marketing OR  ', 'Tier 1: IIMs (Ahmedabad, Bangalore), MICA (The \"Mecca of Marketing\"), SP Jain (Mumbai), NMIMS. OR Tier 2: Symbiosis (SCMHRD/SIBM), IMT Ghaziabad, private universities offering BBA in Digital Marketing (e.g., UPES, Chitkara)', '3 Years (BBA) + 2 Years (MBA) = 5 Years', 'MBA (Marketing) / BBA (Digital Marketing).'),
('Social Media Manager', 'Any Stream', '12th in Any Stream with min. 50% marks.', 'National: CUET-UG (for Mass Communication), XAT / NMAT (for MBA Marketing). OR Private: SET (Symbiosis), MET (Manipal), MICA GE-PI (MICA Ahmedabad - The best for this field).', 'Degree: BMM (Bachelor of Mass Media) / B.A. in Digital Marketing / BBA (Marketing). OR Masters: MBA in Digital Communication Management (MICA) or MBA in Marketing.', 'Tier 1: MICA (Ahmedabad), Symbiosis Centre for Media & Communication (SCMC), Xavier Institute of Communications (XIC). OR Tier 2: IIDE, Pearl Academy, Amity University.', '3 Years (Bachelor\'s) + 2 Years (MBA) = 5 Years.', 'BMM / MBA (Communication).'),
('Electrician', '10th Pass', 'Not Mendatory', 'State ITI Entrance: (e.g., Delhi CET, UP ITI, Maharashtra ITI) – Merit-based in many states OR Polytechnic Entrance: (e.g., JEECUP, POLYCET) – For Diploma Engineering.', 'Route 1 (Trade Certificate): ITI Electrician (2 Years). Focuses on practical wiring, motor winding, and repair. OR Route 2 (Engineering): Diploma in Electrical Engineering (3 Years). Focuses on circuits, power grids, and industrial supervision.', 'Government ITIs: Low fees (~₹2,000/year), high value for Govt jobs OR Polytechnics: Government or Private (e.g., Pusa Polytechnic, VJTI Mumbai). ', '2 Years (ITI) or 3 Years (Diploma)', 'NCVT Trade Certificate (for ITI) / Diploma in Electrical Engineering'),
('Plumber', '10th Pass', 'Not Mendatory', 'State ITI Entrance: (e.g., Delhi CET, Maharashtra ITI Admission) – Merit-based on 10th marks. OR Apprenticeship Exams: AITT (All India Trade Test) after completing training.', 'Certificate: ITI Plumber (1 Year). OR Apprenticeship: National Apprenticeship Certificate (NAC) – Apply via the NAPS portal to work in companies while learning.', 'Government ITIs: Very low fees (~₹2,000/year). OR Private ITIs: Better equipment but higher fees.', '1 Year (Course) + 1 Year (Apprenticeship)', 'NCVT Trade Certificate'),
('AC Technician', '10th Pass', 'Not Mendatory', 'State ITI Entrance: Merit-based admission in most states. OR Polytechnic Entrance: For Diploma in Mechanical Engineering (specialization in RAC).', 'Route 1 (Technician): ITI in Refrigeration & Air Conditioning (RAC) – 2 Years. Covers everything from Window ACs to Commercial Chillers OR Route 2 (Supervisor): Diploma in Mechanical Engineering – 3 Years. Focuses on HVAC design, drafting, and site supervision.', 'Government ITIs: Best for \"Trade Certificate\" (NCVT) at low cost (₹2,000/year) OR Advanced Training Institutes (ATI): For specialized HVAC courses after ITI', '2 Years (ITI) or 3 Years (Diploma).', 'NCVT Trade Certificate (RAC) / Diploma.'),
('CCTV Technician', '10th Pass', 'Not Mendatory', 'State ITI Entrance: Merit-based admission. OR NSQF Assessments: National Skills Qualifications Framework exams for certified technician roles', 'Route 1 (Technician): ITI in Electronics Mechanic or Wireman (2 Years) + Short CCTV Certificate Course OR Route 2 (Networking): Diploma in Electronics & Communication (3 Years). Focuses on signals, transmission, and IP networking. OR Certification: CCTV Installation Technician (Level 4) under NSDC (National Skill Development Corporation).', 'Government ITIs: Low fees (~₹2,000/year). OR Private Technical Institutes: Institutes like Jetking or local skill centers offering 3-6 month \"CCTV & Security Systems\" diplomas.', '6 Months (Certificate) to 2 Years (ITI)', 'NCVT Trade Certificate / NSDC Certificate.'),
('Solar Panel Technician', '10th Pass', 'Not Mendatory', 'State ITI Entrance: For admission into Electrician/Wireman trade. OR Suryamitra Entrance: Conducted by NISE (National Institute of Solar Energy) for specific solar training.', 'Step 1 (Base): ITI in Electrician or Wireman (2 Years) – Mandatory for understanding basic wiring safety OR Step 2 (Specialization): \"Suryamitra\" Skill Development Program (600 Hours / 3 Months). This is a government-funded course specifically for solar installation.', 'Government ITIs: For the base Electrician course. OR NISE Centers: Specialized centers across India that offer the Suryamitra certificate.', '2 Years (ITI) + 3 Months (Suryamitra).', 'NCVT Trade Certificate + Suryamitra Certificate (Skill Council for Green Jobs)'),
('Automobile Mechanic', '10th Pass', 'Not Mendatory', 'State ITI Entrance: Merit-based admission. OR Polytechnic Entrance: For Diploma in Automobile Engineering.', 'Route 1 (Technician): ITI in Motor Mechanic Vehicle (MMV) (2 Years) or Diesel Mechanic (1 Year). OR Route 2 (Engineering): Diploma in Automobile Engineering (3 Years). Focuses on vehicle design basics, thermal engineering, and workshop management.', 'Government ITIs: Very low fees (~₹2,000/year). Best for getting Apprenticeships in Railways/Army. OR Private Technical Institutes: Often have better partnership with car brands (e.g., Maruti Suzuki Training Centers) ', '1-2 Years (ITI) or 3 Years (Diploma).', 'NCVT Trade Certificate (MMV) / Diploma.'),
('Professional Athlete', 'No Mendatory But Starting age is 8 years ', 'No Mendatory', 'No any Exams You can start From District Level OR From School Tam', 'State Level: Perform well in inter-district tournaments to get picked for the State Team', 'Cricket: Ranji Trophy - IPL Auction - Team India OR Football: Youth Leagues (I-League 2nd Div) - ISL Clubs OR Badminton: National Championships - International BWF Ranking.', 'There IS no Durartion depends on your skill and patient', 'NO Any college needed'),
('Sports Coach', '10th Pass', '12th in Any Stream', 'NSNIS Entrance Test: Conducted by the Netaji Subhas National Institute of Sports (NSNIS), Patiala. This is the \"Gold Standard\" for coaches in India. OR  Physical Fitness Test: You must pass a rigorous fitness test to get admitted.', 'Diploma in Sports Coaching: 1 Year Program at NSNIS Patiala / Bangalore / Kolkata. OR M.Sc in Sports Coaching: 2 Years (For advanced research).', 'The Only Authority: NSNIS Patiala (The \"Mecca\" of Indian Coaching) OR Others: LNIPE Gwalior, IGIPESS (Delhi)', '1 Year (Diploma) after Graduation.', 'NIS Diploma in Sports Coaching.'),
('Fitness Trainer', '10th Pass', '12th in Any Stream', 'CUET-UG: For admission into Central Universities offering B.Sc in Sports Science. OR Physical Efficiency Tests: Conducted by colleges like LNIPE (Gwalior) or IGIPESS (Delhi). OR If you don\'t have any Qualification Then also you can Become Fitness Trainer By Enough knowledge of Fitness and skill for Gym.', 'B.P.Ed (Bachelor of Physical Education) OR B.Sc in Exercise & Sports Science', 'Tier 1: Lakshmibai National Institute of Physical Education (LNIPE) (Gwalior), Netaji Subhas National Institute of Sports (NSNIS) (Patiala). OR Tier 2: Amity University (Sports Science), Symbiosis School of Sports Sciences.', '3 - 4 Years.', 'B.P.Ed / B.Sc Sports Science.'),
('Sports Referee', '10th Pass', '12th in Any Stream', 'State Level Exam: Conducted by local associations (e.g., DDCA, MCA, TNCA). OR BCCI Level 1: For top state umpires to get into the \"BCCI Panel\" (Junior Domestic). OR BCCI Level 2: The \"Elite\" exam to officiate Ranji Trophy and IPL', 'Any Course ', 'Based on your course', 'Depends Which course', 'According to your course'),
('Sports Content Creator', '10th Pass', '12th in Any Stream', 'Media Entrances: IIMC Entrance (Indian Institute of Mass Comm), XIC OET (Xavier’s), ACJ Entrance (Asian College of Journalism).', 'Degree: B.A. in Journalism & Mass Communication (BJMC). OR Masters: PG Diploma in Sports Management or Sports Journalism (IISM Mumbai offers this)', 'Tier 1: IIMC (Delhi), ACJ (Chennai), Jamia Millia Islamia (AJK MCRC), IISM (Mumbai). OR Tier 2: Amity School of Communication, Symbiosis (SCMC).', '3 Years (Degree) or 1 Year (PG Diploma).', 'B.A. Journalism / Diploma in Sports Management'),
('IAS Officer', 'Any Stream (Humanities is preferred for History/Polity foundation, but Science/Commerce students are', '12th in Any Stream with passing marks.', 'UPSC CSE (Civil Services Examination) Stage 1: Prelims (GS + CSAT) Stage 2: Mains (9 Papers) Stage 3: Physical Standard Test (PST): Specific height/chest/vision requirements are checked after the Interview Stage 4: Interview (Personality Test)', 'Bachelor’s Degree (B.A., B.Sc, B.Tech, MBBS, etc.) from any recognized university OR you must meet physical medical standards (No Color Blindness, Minimum Height: Men 165cm / Women 150cm)', 'IAS Have No Any College But According To Your Course Because IAS Need Graduation In Any Stream', '3 Years (Graduation) + ~1-2 Years (Preparation & Exam Cycle) + 2 Years (Training)', 'Bachelor\'s Degree in any discipline'),
('IPS Officer', 'Any Stream (Humanities is preferred for History/Polity foundation, but Science/Commerce students are', '12th in Any Stream with passing marks.', 'UPSC CSE (Civil Services Examination) Stage 1: Prelims (GS + CSAT) Stage 2: Mains (9 Papers) Stage 3: Physical Standard Test (PST): Specific height/chest/vision requirements are checked after the Interview Stage 4: Interview (Personality Test)', 'Bachelor’s Degree (B.A., B.Sc, B.Tech, MBBS, etc.) from any recognized university', 'IPS Have No Any College But According To Your Course Because IPS Need Graduation In Any Stream', '3 Years (Graduation) + ~1-2 Years (Preparation & Exam Cycle) + 2 Years (Training)', 'Bachelor\'s Degree in any discipline'),
('IFS Officer', 'Any Stream (Humanities is preferred for History/Polity foundation, but Science/Commerce students are', '', 'UPSC CSE (Civil Services Examination) Stage 1: Prelims (GS + CSAT) Stage 2: Mains (9 Papers) Stage 3: Physical Standard Test (PST): Specific height/chest/vision requirements are checked after the Interview Stage 4: Interview (Personality Test)', 'Bachelor’s Degree (B.A., B.Sc, B.Tech, MBBS, etc.) from any recognized university', 'IFS Have No Any College But According To Your Course Because IFS Need Graduation In Any Stream', '3 Years (Graduation) + ~1-2 Years (Preparation & Exam Cycle) + 2 Years (Training)', 'Bachelor\'s Degree in any discipline'),
('IRS Officer', 'Any Stream (Humanities is preferred for History/Polity foundation, but Science/Commerce students are', '', 'UPSC CSE (Civil Services Examination) Stage 1: Prelims (GS + CSAT) Stage 2: Mains (9 Papers) Stage 3: Physical Standard Test (PST): Specific height/chest/vision requirements are checked after the Interview Stage 4: Interview (Personality Test)', 'Bachelor’s Degree (B.A., B.Sc, B.Tech, MBBS, etc.) from any recognized university', 'IRS Have No Any College But According To Your Course Because IRS Need Graduation In Any Stream', '3 Years (Graduation) + ~1-2 Years (Preparation & Exam Cycle) + 2 Years (Training)', 'Bachelor\'s Degree in any discipline'),
('Police Officer', 'Any Stream', '12th in Any Stream', 'State Police Constable Exam: Conducted by state boards OR SSC GD Constable: A massive national exam to join Paramilitary forces (BSF, CRPF, CISF) as a Constable (General Duty).', 'Any Course ', 'According To your Course ', 'Depends Which course', 'According to your course'),
('Sub Inspector', 'Any Stream', '12th in Any Stream', 'SSC CPO (Central Police Organization): Conducted by the Staff Selection Commission.PET/PST: Physical Endurance & Standard Test. Tier 1: Written Exam (Maths, Reasoning, GK, English)  Tier 2: English Language & Comprehension (200 Marks)Medical: Detailed medical examination', 'Any Course ', 'According To your Course ', 'Depends Which course', 'According to your course'),
('Army Officer', 'Any Stream', '12th in Any Stream', 'NDA Exam (UPSC): Conducted twice a year (NDA-I and NDA-II). It has Maths and GAT (General Ability Test). OR TES (Technical Entry Scheme): Direct entry for 10+2 PCM students.Requirement: You must have appeared for JEE Mains. The Army shortlists candidates for SSB based on their PCM % and JEE Rank.', 'Any Course ', 'According To your Course ', 'Depends Which course', 'According to your course + Training Year'),
('Navy Officer', 'Any Stream', '12th in Any Stream', 'NDA Exam (UPSC): Join the National Defence Academy (Pune). OR Training: 3 Years at NDA + 1 Year at Indian Naval Academy (INA), Ezhimala OR 10+2 B.Tech Cadet Entry Scheme: Direct entry for engineers.Requirement: You MUST appear for JEE Mains. The Navy shortlists candidates for SSB Interview based on their JEE All India Rank (AIR).Training: 4 Years B.Tech at INA Ezhimala.', 'Any Course ', 'According To your Course ', 'Depends Which course', 'According to your course + Training Year'),
('Air Force Officer', 'Any Stream', '12th in Any Stream', 'NDA Exam (UPSC): Join the National Defence Academy (Pune). OR Training: 3 Years at NDA + 1 Year at Indian Naval Academy (INA), Ezhimala OR 10+2 B.Tech Cadet Entry Scheme: Direct entry for engineers.Requirement: You MUST appear for JEE Mains. The Navy shortlists candidates for SSB Interview based on their JEE All India Rank (AIR).Training: 4 Years B.Tech at INA Ezhimala.', '', 'According To your Course ', 'Depends Which course', 'According to your course + Training Year'),
('Fire & Emergency Officer', 'Any Stream', '12th in Science Stream (Physics, Chemistry, Maths) is mandatory for the top officer courses.', 'NFSC Entrance Exam: Conducted by the National Fire Service College (NFSC), Nagpur (Ministry of Home Affairs). This is the \"IIT of Fire Engineering.\" OR State PSC Exams: State Public Service Commissions (e.g., MPSC, KPSC, TNPSC) conduct exams for Station Officer (SO) or Assistant Divisional Fire Officer (ADFO).', 'B.E. (Fire Engineering): 4 Years at NFSC Nagpur. Admission is often via JEE Mains rank. OR Sub-Officer Course: A specialized 6-month course at NFSC for graduates/diploma holders to become subordinate officers', 'Tier 1: NFSC Nagpur (The only college that guarantees a Class-1 Officer career). OR Tier 2: CUSAT (Cochin University), UPES (Dehradun) – for Fire & Safety Engineering degrees.', '4 Years (B.E.) or 6 Months (Sub-Officer Course after Graduation). ', 'B.E. Fire Engineering / Divisional Officer Certification.'),
('Bank Clerk', 'Any Stream', 'Graduation in Any Stream (B.A., B.Com, B.Sc, B.Tech). Percentage does not matter, just passing is en', 'SBI Clerk (Junior Associate): Conducted by State Bank of India. The most prestigious clerical job OR IBPS Clerk: A common exam for 11 Public Sector Banks (PNB, Bank of Baroda, Canara Bank, etc.). OR  IBPS RRB Clerk: For Regional Rural Banks (Gramin Banks). Best if you want to stay in your home district.', 'According Which You Choose ', 'According To your Course ', 'Depends Which course', 'According to your course'),
('Government Teacher', 'Any Stream', '12th Pass with min. 50% marks (Any Stream).', 'Diploma in Elementary Education (D.El.Ed): A 2-year diploma. Note: As per Supreme Court\'s 2023 ruling, B.Ed graduates are NOT eligible for PRT; only D.El.Ed/BTC holders are eligible. OR B.El.Ed: 4-year integrated course (Bachelor of Elementary Education)', 'Eligibility Test: Pass CTET Paper-1 (Central) or State TET Paper-1 (e.g., UPTET, REET) OR ', 'According To your Course ', 'Depends Which course', 'According to your course'),
('Government Doctor', 'Science stream with Biology (Physics, Chemistry, Biology)', '12th in Science (PCB) with high marks.', 'NEET-UG: To get into an MBBS college. AND UPSC CMS (Combined Medical Services): The most prestigious exam for doctors. OR State PSC Exams: Conducted by respective states', 'MBBS: 5.5 Years (including 1 year internship).', 'Government or Private Medical / Dental / AYUSH College', '5.5 Years (4.5 Years Academic + 1 Year Compulsory Internship)', 'Bachelor Degree (MBBS, BDS, or equivalent)');
