INSERT INTO `exams` (`exam_name`, `detail`) VALUES
('Civil Services Examination (CSE)', 'Exam Name: Civil Services Examination (CSE)\nConducting Body: Union Public Service Commission (UPSC) – Central Government\nTarget Posts: IAS, IPS, IFS, IRS, and other Group A & B services\nEligibility (Education): Graduate (Bachelor\'s Degree) in any stream\nEligibility (Age): 21–32 years (General Category)\nTarget Stream: Any Stream (Arts, Science, Commerce, Engineering, Medical)\nFrequency: Once a year (Notification in February, Prelims in May/June)\nPurpose: Recruitment for central administration, law & order, and foreign policy roles\nSelection Process: 3 Stages – Prelims, Mains, Interview\nStage 1: Prelims Format: Objective Type (Multiple Choice Questions)\nPrelims Paper 1 (General Studies): 100 Questions, 200 Marks (used for merit ranking)\nPrelims Paper 2 (CSAT): 80 Questions, 200 Marks (qualifying only, 33% required)\nPrelims Cutoff: General category usually needs 85–95 marks in Paper 1\nStage 2: Mains Format: Descriptive Written Examination\nMains Structure: 9 Papers Total (2 Qualifying + 7 counted for merit)\nMains Qualifying Papers: English + One Indian Language (marks not counted in rank)\nMains Merit Papers: 1 Essay, 4 General Studies papers, 2 Optional Subject papers\nMains Total Marks: 1750\nMains Passing Target: Approx. 730–750 marks required for Interview call\nStage 3: Interview: Personality Test (face-to-face panel)\nInterview Marks: 275\nGrand Total Marks: 2025 (Mains + Interview)\nFinal Selection Target: Usually 950+ marks (around 47%) required for final merit list'),
('Indian Forest Service (IFoS)', 'Type of Exam:Central (Conducted by the Union Public Service Commission - UPSC)\nExam Name:Indian Forest Service Examination (IFoS)\nFor Which Posts:Class I forest officers such as Assistant Conservator of Forests, Divisional Forest Officer (DFO), and Deputy Conservator of Forests\nFor Whom:Indian citizens with a Bachelor’s degree in a specific scientific or technical field; Age limit 21–32 years (General category)\nFor Which Stream:Science or Engineering only; Eligible degrees include Animal Husbandry, Botany, Chemistry, Geology, Mathematics, Physics, Statistics, Zoology, Agriculture, Forestry, and Engineering; Arts and Commerce graduates are not eligible\nWhen:Conducted once a year; Preliminary exam held with Civil Services Prelims (May/June); Mains exam conducted separately (usually November)\nWhy:Recruitment of officers responsible for management of forests, wildlife, natural resources, and environmental policies\nSelection Process:3 Stages – Prelims, Mains, Interview\nStage 1:Preliminary Examination Format:Objectiv e Type (Multiple Choice Questions)\nPrelims Paper 1 (General Studies):100 Questions, 200 Marks (Counted for cutoff)\nPrelims Paper 2 (CSAT):80 Questions, 200 Marks (Qualifying only)\nPrelims Passing Requirement Paper 2:Minimum 33% (66 Marks) required\nPrelims Cutoff Paper 1:Must clear IFoS-specific cutoff, usually higher than Civil Services (often 100+ for General category)\nStage 2:Mains Examination Format:Descriptive Written Examination\nTotal Papers:6 Papers (All marks counted for merit ranking)\nPaper 1:General English – 300 Marks\nPaper 2:General Knowledge – 300 Marks\nOptional Subject 1 Paper 1:200 Marks\nOptional Subject 1 Paper 2:200 Marks\nOptional Subject 2 Paper 1:200 Marks\nOptional Subject 2 Paper 2:200 Marks\nMains Total Marks:1400 Marks\nOptional Subjects Rule:Two optional subjects must be chosen from the approved Science/Engineering list\nStage 3:Interview:Personality Test assessing leadership, decision-making, and suitability for forest service field life\nI'),
('Engineering Services Examination (ESE/IES)', 'Type of Exam:Central (Conducted by the Union Public Service Commission - UPSC)\nExam Name:Engineering Services Examination (ESE/IES)\nFor Which Posts:Group A and Group B technical officers managing national technical infrastructure in departments like Indian Railways (IRMS), CPWD, BRO, Central Water Commission, and Military Engineer Services\nLatest Update:Indian Railways recruitment is conducted through ESE under IRMS cadre (as per latest update)\nFor Whom:Indian citizens with a Degree in Engineering (B.E./B.Tech); Age limit 21–30 years (General category)\nFor Which Stream:Only Civil Engineering, Mechanical Engineering, Electrical Engineering, and Electronics & Telecommunication Engineering are eligible; Other branches like Computer Science or Chemical Engineering are not eligible unless degree is in one of the four core branches\nWhen:Conducted once a year\nCurrent Status:For 2025 cycle, Prelims scheduled in June 2025 and Mains in August 2025 due to Railway vacancies; Normally Prelims held in February\nWhy:To recruit technical officers responsible for infrastructure such as bridges, railways, power systems, and defense engineering projects\nSelection Process:3 Stages – Prelims, Mains, Interview\nStage 1:Preliminary Examination Format:Objective Type (Multiple Choice Questions)\nPaper 1 (GS & Engineering Aptitude):100 Questions, 200 Marks covering General Studies, Engineering Mathematics, Reasoning, and Ethics\nPaper 2 (Technical):150 Questions, 300 Marks based on candidate’s engineering branch\nTotal Prelims Marks:500 Marks\nPrelims Passing Requirement:Combined cutoff of both papers must be cleared; General category cutoff usually around 200–240 out of 500\nStage 2:Mains Examination Format:Descriptive Written Examination\nPaper 1 (Technical):300 Marks\nPaper 2 (Technical):300 Marks\nTotal Mains Marks:600 Marks\nMains Requirement:High aggregate score required to qualify for Interview stage\nStage 3:Interview:Personality Test assessing technical knowledge, leadership, and suitability fo'),
('Combined Defence Services (CDS)', 'Type of Exam:Central (Conducted by the Union Public Service Commission - UPSC)\nExam Name:Combined Defence Services Examination (CDS)\nFor Which Posts:Commissioned Officers in Indian Armed Forces through Indian Military Academy (IMA) – Army Permanent Commission, Indian Naval Academy (INA) – Navy Permanent Commission, Air Force Academy (AFA) – Air Force Permanent Commission, Officers’ Training Academy (OTA) – Army Short Service Commission\nFor Whom:Unmarried Indian citizens (some exceptions applicable for OTA)\nFor Which Stream:IMA & OTA require Degree in any stream; INA requires Engineering degree (B.E./B.Tech); AFA requires Degree in any stream with Physics & Maths at 10+2 level or Engineering degree\nAge Limit:IMA 19–24 years; INA 19–24 years; AFA 20–24 years; OTA 19–25 years\nWhen:Conducted twice a year (usually April and September); Notifications released in December and May\nWhy:To recruit officers for Indian Army, Navy, and Air Force as Lieutenant, Sub-Lieutenant, or Flying Officer\nSelection Process:Written Exam, SSB Interview, Medical Examination\nStage 1:Written Examination Format:Objective Type (Multiple Choice Questions)\nIMA/INA/AFA Paper 1 English:100 Marks, 2 Hours\nIMA/INA/AFA Paper 2 General Knowledge:100 Marks, 2 Hours\nIMA/INA/AFA Paper 3 Elementary Mathematics:100 Marks, 2 Hours\nIMA/INA/AFA Total Written Marks:300 Marks\nIMA/INA/AFA Written Cutoff:Approximately 140–150 Marks required for SSB call\nOTA Paper 1 English:100 Marks, 2 Hours\nOTA Paper 2 General Knowledge:100 Marks, 2 Hours\nOTA Total Written Marks:200 Marks\nOTA Written Cutoff:Approximately 100–110 Marks required for SSB call\nStage 2:SSB Interview Format:5-day process including Screening, Psychological Tests, Group Testing Officer Tasks, and Personal Interview\nSSB Marks IMA/INA/AFA:300 Marks\nSSB Marks OTA:200 Marks\nMedical Examination:Comprehensive physical and medical fitness test after SSB qualification\nGrand Total Marks IMA/INA/AFA:600 Marks (300 Written + 300 SSB)\nGrand Total Marks OTA:400 Marks (2'),
('National Defence Academy & Naval Academy (NDA & NA)', 'Type of Exam:Central (Conducted by the Union Public Service Commission - UPSC)\nExam Name:National Defence Academy & Naval Academy Examination (NDA & NA)\nFor Which Posts:Admission to Army Wing, Air Force Wing, and Naval Wing of National Defence Academy Pune and Indian Naval Academy Ezhimala for commissioned officer training\nFor Whom:Unmarried Male and Female Indian citizens\nAge Limit:16.5–19.5 years; Candidates are usually 15.5–18.5 years at time of application to meet age criteria at course commencement\nFor Which Stream:Army Wing requires 12th pass in any stream; Air Force, Navy and Naval Academy require 12th pass with Physics, Chemistry and Mathematics; Students appearing in Class 12 are also eligible\nWhen:Conducted twice a year usually in April and September; Notifications released in December and May\nWhy:To select young candidates after school and train them to become future officers of Indian Armed Forces\nSelection Process:Written Exam, SSB Interview, Medical Examination\nStage 1:Written Examination Format:OMR Based Objective Type (Multiple Choice Questions)\nPaper 1 Mathematics:300 Marks, 2.5 Hours covering 11th and 12th standard Mathematics topics like Algebra, Trigonometry, Calculus and Matrices; Negative marking applicable\nPaper 2 General Ability Test:600 Marks, 2.5 Hours\nGAT Part A English:200 Marks covering Grammar and Vocabulary\nGAT Part B General Knowledge:400 Marks covering Physics, Chemistry, General Science, History, Geography and Current Events\nTotal Written Marks:900 Marks\nWritten Passing Requirement Sectional Cutoff:Minimum 25% marks required in both Mathematics and GAT separately\nWritten Overall Cutoff:Generally 350–370 marks out of 900 required to qualify for SSB\nStage 2:SSB Interview Format:5-day process including psychological tests, group tasks and personal interview\nSSB Marks:900 Marks\nMedical Examination:Comprehensive physical and medical fitness assessment after SSB qualification\nGrand Total Marks:1800 Marks (900 Written + 900 SSB)\nFinal Sele'),
('Central Armed Police Forces (CAPF AC)', 'Type of Exam:Central (Conducted by the Union Public Service Commission - UPSC)\nExam Name:Central Armed Police Forces Examination (CAPF AC)\nFor Which Posts:Assistant Commandant (Group A Officer) in BSF, CRPF, CISF, ITBP, and SSB\nFor Whom:Indian citizens (Male and Female)\nFor Which Stream:Any stream with a Bachelor’s degree from a recognized university\nAge Limit:20–25 years (General Category)\nAge Relaxation:OBC +3 years, SC/ST +5 years\nWhen:Conducted once a year (Notification usually in April, Exam in August)\nWhy:To recruit officers responsible for internal security, border management, and disaster response\nSelection Process:Written Exam, Physical Efficiency Test, Medical Examination, Interview\nStage 1:Written Examination (Same Day)\nPaper 1 General Ability & Intelligence Format:Objectiv e Type (MCQ) covering Mental Ability, Science, Current Events, Indian Polity, History, and Geography\nPaper 1 Marks:250 Marks (125 Questions) with negative marking of one-third deduction\nPaper 2 General Studies, Essay & Comprehension Format:Descriptive written exam including Essay, Precis, Comprehension, and Argument writing\nPaper 2 Marks:200 Marks\nTotal Written Marks:450 Marks\nWritten Cutoff:Approximately 200–215 marks required for Physical Test call\nStage 2:Physical Efficiency Test (Qualifying Only)\n100m Race:Men 16 seconds, Women 18 seconds\n800m Race:Men 3 minutes 45 seconds, Women 4 minutes 45 seconds\nLong Jump:Men 3.5 meters, Women 3.0 meters (3 chances)\nShot Put (7.26kg):Men 4.5 meters, Women Not Applicable\nStage 3:Interview:Personality Test conducted at UPSC Bhawan Delhi\nInterview Marks:150 Marks\nGrand Total Marks:600 Marks (450 Written + 150 Interview)\nFinal Selection Target:Generally 320–330 marks required for final merit list'),
('Combined Medical Services (CMS)', 'Type of Exam:Central (Conducted by the Union Public Service Commission - UPSC)\nFor Which Posts:Medical Officers (Class I & II) including Assistant Divisional Medical Officer in Railways, Assistant Medical Officer in Indian Ordnance Factories, and General Duty Medical Officer in Central Health Service, NDMC, and Delhi Municipal Corporations\nFor Whom:Indian citizens who have passed written and practical parts of final MBBS examination; Final year MBBS students eligible if they pass before interview\nAge Limit:Up to 32 years (General Category); For General Duty Medical Officers in Central Health Service often up to 35 years\nFor Which Stream:Medical Stream Only (MBBS)\nWhen:Conducted once a year (Notification usually in March, Exam in July/August)\nWhy:To recruit doctors for Indian Railways and Central Government health services\nSelection Process:Computer Based Test and Interview\nStage 1:Computer Based Test Format:Objectiv e Type Multiple Choice Questions conducted on same day\nPaper 1 General Medicine and Paediatrics:General Medicine 96 Questions, Paediatrics 24 Questions; Total 120 Questions, 250 Marks, 2 Hours\nPaper 2 Surgery, Gynaecology & Obstetrics and Preventive & Social Medicine:Surgery 40 Questions, Gynaecology & Obstetrics 40 Questions, Preventive & Social Medicine 40 Questions; Total 120 Questions, 250 Marks, 2 Hours\nTotal Written Marks:500 Marks\nNegative Marking:One-third deduction for wrong answers\nWritten Cutoff:Approximately 200–250 aggregate marks required for interview call\nStage 2:Interview:Personality Test assessing general knowledge and medical aptitude\nInterview Marks:100 Marks\nGrand Total Marks:600 Marks (500 Written + 100 Interview)\nFinal Selection Target:Generally 310–330 marks required for final merit list'),
('EPFO EO/AO & APFC Exam', 'Type of Exam:Central (Conducted by the Union Public Service Commission - UPSC)\nFor Which Posts:Enforcement Officer/Accounts Officer (Group B Non-Gazetted) responsible for enforcing EPF Act, recovery of dues and claim settlement; Assistant Provident Fund Commissioner (Group A Gazetted) senior managerial post with higher administrative authority\nFor Whom:Indian citizens with a Bachelor’s Degree in any stream\nExperience Note:No experience required for EO/AO; Experience desirable but not mandatory for APFC\nAge Limit EO/AO:Up to 30 years\nAge Limit APFC:Up to 35 years\nFor Which Stream:Any stream including Arts, Commerce, Science and Engineering\nWhen:Not conducted annually; Exam held only when vacancies arise, usually with a gap of 2–3 years\nWhy:To manage and regulate provident fund and social security schemes for employees in organized private sector\nSelection Process:Recruitment Test and Interview\nFinal Merit Weightage:75% Written Score + 25% Interview Score\nStage 1:Recruitment Test Format:Offline OMR Based Objective Type Examination\nDuration:2 Hours\nTotal Questions:120 Questions\nTotal Marks:300 Marks\nNegative Marking:One-third deduction for wrong answers\nEO/AO Syllabus:General English, Indian Freedom Struggle, Current Events, Indian Polity and Economy, General Accounting Principles, Industrial Relations and Labour Laws, General Science and Computer Knowledge, Mental Ability and Social Security in India\nAPFC Syllabus:Includes all EO/AO topics plus Audit, Insurance, Statistics, Population, Development, Globalization and Indian Culture and Heritage\nStage 2:Interview Format:Personality Test to assess suitability for enforcement and public dealing roles\nInterview Marks:100 Marks\nMinimum Interview Marks General:50 Marks\nMinimum Interview Marks OBC:45 Marks\nMinimum Interview Marks SC/ST:40 Marks\nFinal Selection Target:High written score around 180–200 out of 300 significantly improves chances due to 75% weightage'),
('SSC CGL', 'Type of Exam:Central (Conducted by the Staff Selection Commission)\nFor Which Posts:Group B and C officers in Ministries, Departments and Organizations of Government of India including Inspector (Income Tax, GST/Excise, Preventive Officer), Assistant Section Officer in CSS, MEA, Railways and IB, Sub-Inspector in CBI, Assistant Enforcement Officer in ED, Auditor/Accountant in CAG, and Tax Assistant in CBDT/CBIC\nFor Whom:Indian citizens with a Bachelor’s Degree; Final year students eligible if degree completed before prescribed cutoff date\nAge Limit:Varies by post; Most Group B posts 20–30 years, Junior Statistical Officer up to 32 years, Group C posts 18–27 years\nFor Which Stream:Any stream including Arts, Science, Commerce and Engineering; For Junior Statistical Officer, Mathematics in 12th with 60% marks or Statistics as a subject in Graduation required\nWhen:Conducted once a year; Notification released mid-year and Tier 1 held about 3–4 months later\nWhy:To recruit staff for central government administrative and field roles; Often called “Mini-IAS” due to authority and prestige of top posts\nSelection Process:Tier 1 Computer Based Test, Tier 2 Computer Based Test and Skill Tests; No interview stage\nStage 1:Tier 1 Examination Format:Computer Based Objective Type Test (Qualifying Only)\nTier 1 Sections:Reasoning 25 Questions 50 Marks; General Awareness 25 Questions 50 Marks; Quantitative Aptitude 25 Questions 50 Marks; English Comprehension 25 Questions 50 Marks\nTier 1 Total Marks:200 Marks (100 Questions)\nTier 1 Cutoff:Generally 130–150+ marks required for General category to qualify for Tier 2\nStage 2:Tier 2 Examination Format:Computer Based Objective Test (Merit Deciding)\nPaper 1 Duration:2 Hours 15 Minutes\nSection 1 Maths and Reasoning:Maths 30 Questions plus Reasoning 30 Questions Total 180 Marks\nSection 2 English and General Awareness:English 45 Questions plus General Awareness 25 Questions Total 210 Marks\nSection 3 Computer Knowledge and Data Entry:Computer Knowle'),
('SSC CHSL', 'Type of Exam:Central (Conducted by the Staff Selection Commission)\nFor Which Posts:Group C clerical and data entry posts including Lower Division Clerk/Junior Secretariat Assistant and Data Entry Operator in Central Government Ministries and Departments\nFor Whom:Indian citizens who have passed Class 12th (Intermediate)\nFor Which Stream:LDC/JSA and DEO (General) require any stream; DEO in C&AG and Ministry of Consumer Affairs requires Science stream with Mathematics in Class 12\nAge Limit:18–27 years (General Category)\nWhen:Conducted once a year with notification usually mid-year and Tier 1 exam 3–4 months later\nWhy:To recruit clerical and support staff for smooth functioning of government offices\nSelection Process:Tier 1 Computer Based Test and Tier 2 Computer Based Test plus Skill Test\nStage 1:Tier 1 Examination Format:Computer Based Objective Test (Qualifying Only)\nTier 1 Sections:English Language 25 Questions 50 Marks; General Intelligence 25 Questions 50 Marks; Quantitative Aptitude 25 Questions 50 Marks; General Awareness 25 Questions 50 Marks\nTier 1 Total Marks:200 Marks (100 Questions)\nTier 1 Cutoff:Generally 140–150+ marks required to qualify for Tier 2\nStage 2:Tier 2 Examination Format:Computer Based Objective Test (Merit Deciding)\nSession I Section 1 Maths and Reasoning:Maths 30 Questions plus Reasoning 30 Questions Total 180 Marks\nSession I Section 2 English and General Awareness:English 40 Questions plus General Awareness 20 Questions Total 180 Marks\nSession I Section 3 Computer Knowledge:15 Questions 45 Marks (Qualifying)\nSession II Skill Test:Typing Test mandatory for all candidates\nTyping Speed Requirement:LDC/JSA require 35 words per minute in English or 30 words per minute in Hindi; DEO requires 15000 key depressions per hour\nMarking Scheme:+3 marks for correct answer and -1 mark for wrong answer\nTier 2 Marks for Merit:360 Marks (Section 1 and Section 2 only)\nGrand Total Marks:360 Marks (Only Tier 2 counted for final merit)\nFinal Selection Target:Gen'),
('SSC MTS', 'Type of Exam:Central (Conducted by the Staff Selection Commission)\nExam Name:SSC MTS & Havaldar Examination\nFor Which Posts:Multi-Tasking Staff Group C Non-Gazetted Non-Ministerial posts such as Peon, Daftary, Jamadar, Safaiwala and Mali in Central Government Ministries; Havaldar posts in CBIC and CBN\nFor Whom:Indian citizens who have passed Matriculation (10th Pass) from a recognized board\nFor Which Stream:Any stream since eligibility is based on 10th qualification\nAge Limit:18–25 years for MTS and Havaldar in CBN; 18–27 years for Havaldar in CBIC and certain MTS posts\nWhen:Conducted once a year with notification usually released mid-year\nWhy:Entry-level recruitment for central government jobs for candidates with 10th qualification\nSelection Process:Computer Based Examination and Physical Test for Havaldar posts\nStage 1:Computer Based Examination Format:Two sessions held on same day and both mandatory\nSession 1 Subjects:Numerical and Mathematical Ability 20 Questions 60 Marks; Reasoning Ability and Problem Solving 20 Questions 60 Marks\nSession 1 Total:40 Questions 120 Marks 45 Minutes\nSession 1 Negative Marking:No negative marking\nSession 1 Role:Qualifying only and marks not counted in final merit but minimum standard must be achieved\nSession 2 Subjects:General Awareness 25 Questions 75 Marks; English Language and Comprehension 25 Questions 75 Marks\nSession 2 Total:50 Questions 150 Marks 45 Minutes\nSession 2 Negative Marking:One mark deducted for each wrong answer\nSession 2 Role:Marks from this session decide final merit ranking\nStage 2:Physical Efficiency and Standard Test for Havaldar posts only\nWalking Test Male:1600 meters in 15 minutes\nWalking Test Female:1 kilometer in 20 minutes\nHeight Requirement Male:157.5 centimeters\nHeight Requirement Female:152 centimeters\nGrand Total Marks:150 Marks (Session 2 only counted for merit)\nFinal Selection Target:Generally 120–135+ marks required in Session 2 for final merit list'),
('SSC GD Constable', 'Type of Exam:Central (Conducted by the Staff Selection Commission)\nExam Name:SSC GD Constable Examination\nFor Which Posts:Constable General Duty in CAPFs and Sepoy in NCB deployed in BSF, CISF, CRPF, ITBP, SSB, SSF and Assam Rifles\nFor Whom:Indian citizens who have passed Class 10th (Matriculation) from a recognized board\nAge Limit:18–23 years (General Category)\nAge Relaxation:OBC +3 years, SC/ST +5 years\nFor Which Stream:Any stream since eligibility is based on 10th qualification\nWhen:Conducted once a year with notification usually released late in the year and exam held in January or February of the following year\nWhy:To recruit personnel for internal security and border guarding forces of India\nSelection Process:Computer Based Examination, Physical Efficiency Test and Standard Test, Medical Examination\nStage 1:Computer Based Examination Format:Online Objective Type Test 60 Minutes\nSubjects:General Intelligence and Reasoning 20 Questions 40 Marks; General Knowledge and Awareness 20 Questions 40 Marks; Elementary Mathematics 20 Questions 40 Marks; English or Hindi 20 Questions 40 Marks\nTotal Marks:160 Marks (80 Questions)\nNegative Marking:0.25 marks deducted for each wrong answer\nWritten Cutoff:Generally 100–120+ marks required for Physical Test call depending on state and force\nStage 2:Physical Efficiency Test and Physical Standard Test (Qualifying Only)\nRunning Male:5 kilometers in 24 minutes\nRunning Female:1.6 kilometers in 8.5 minutes\nRunning Ladakh Male:1.6 kilometers in 7 minutes\nRunning Ladakh Female:800 meters in 5 minutes\nHeight Requirement Male:170 centimeters\nHeight Requirement Female:157 centimeters\nChest Requirement Male Only:80 centimeters unexpanded with minimum 5 centimeters expansion\nStage 3:Medical Examination:Detailed medical fitness test as per CAPF standards\nGrand Total Marks:160 Marks (Only Computer Based Exam counted for merit)\nFinal Selection Target:Cutoff varies by state and force; SSF and CISF generally require 135–145+ marks while BSF and'),
('SSC JE', 'Type of Exam:Central (Conducted by the Staff Selection Commission)\nExam Name:SSC Junior Engineer (JE) Examination\nFor Which Posts:Junior Engineer Group B Non-Gazetted in CPWD, CWC, BRO, MES, Farakka Barrage Project, NTH and other Central Government technical departments\nFor Whom:Indian citizens with Degree in Engineering (B.E./B.Tech) eligible for most departments without experience; Diploma holders eligible but some departments like MES and BRO require 2 years work experience after diploma\nAge Limit:Up to 32 years for CPWD and CWC; Up to 30 years for MES and BRO (General Category)\nFor Which Stream:Civil Engineering, Electrical Engineering, Mechanical Engineering only\nWhen:Conducted once a year with notification usually mid-year and exam in October or November\nWhy:To recruit technical supervisors for central government engineering projects; Popular exam for diploma and degree engineers\nSelection Process:Paper 1 Computer Based Test and Paper 2 Computer Based Test\nStage 1:Paper 1 Format:Computer Based Objective Test 2 Hours\nSubjects Paper 1:General Intelligence and Reasoning 50 Questions 50 Marks; General Awareness 50 Questions 50 Marks; General Engineering 100 Questions 100 Marks\nPaper 1 Total:200 Questions 200 Marks\nPaper 1 Negative Marking:0.25 marks deducted for each wrong answer\nPaper 1 Cutoff:Approximately 130–145 marks for Civil and 145–155 marks for Electrical or Mechanical to qualify for Paper 2\nStage 2:Paper 2 Format:Computer Based Objective Test 2 Hours\nPaper 2 Subjects:Engineering questions from candidate’s specific branch only\nPaper 2 Questions:100 Questions\nMarks per Question:3 Marks\nPaper 2 Total Marks:300 Marks\nPaper 2 Negative Marking:1 mark deducted for each wrong answer\nGrand Total Marks:500 Marks (200 Paper 1 + 300 Paper 2)\nFinal Selection Target:Civil candidates generally need 320–340 marks; Electrical and Mechanical candidates generally need 360–380+ marks'),
('SSC CPO', 'Type of Exam:Central (Conducted by the Staff Selection Commission)\nExam Name:SSC CPO Sub-Inspector Examination\nFor Which Posts:Sub-Inspector Group B Non-Gazetted in Delhi Police and CAPFs including BSF, CRPF, CISF, ITBP and SSB\nFor Whom:Indian citizens with a Bachelor’s Degree in any stream\nSpecial Requirement Delhi Police Male:Valid Driving License for LMV (Car and Motorcycle) required on date of Physical Test; Without license eligible only for CAPF posts\nAge Limit:20–25 years (General Category)\nAge Relaxation:OBC +3 years, SC/ST +5 years\nFor Which Stream:Any stream including Arts, Science, Commerce and Engineering\nWhen:Conducted once a year with notification usually mid-year and Paper 1 in October or November\nWhy:To recruit graduates as uniformed police officers in Delhi Police and CAPFs\nSelection Process:Paper 1 Computer Based Test, Physical Standard and Endurance Test, Paper 2 Computer Based Test, Medical Examination\nStage 1:Paper 1 Format:Computer Based Objective Test 2 Hours\nSubjects Paper 1:General Intelligence and Reasoning 50 Questions 50 Marks; General Knowledge and Awareness 50 Questions 50 Marks; Quantitative Aptitude 50 Questions 50 Marks; English Comprehension 50 Questions 50 Marks\nPaper 1 Total:200 Questions 200 Marks\nPaper 1 Negative Marking:0.25 marks deducted for each wrong answer\nPaper 1 Cutoff Delhi Police:Generally 140–150+ marks for males and 130+ for females\nPaper 1 Cutoff CAPFs:Generally 115–125+ marks\nStage 2:Physical Endurance and Standard Test Qualifying Only\nPET Male:100 meters in 16 seconds; 1.6 kilometers in 6.5 minutes; Long Jump 3.65 meters; High Jump 1.2 meters; Shot Put 4.5 meters\nPET Female:100 meters in 18 seconds; 800 meters in 4 minutes; Long Jump 2.7 meters; High Jump 0.9 meters\nPST Height Male:170 centimeters\nPST Height Female:157 centimeters\nPST Chest Male Only:80 centimeters unexpanded and 85 centimeters expanded with minimum 5 centimeter expansion\nStage 3:Paper 2 Format:Computer Based Objective Test 2 Hours\nPaper 2 Subject:'),
('SSC Stenographer Grade C & D', 'Type of Exam:Central (Conducted by the Staff Selection Commission)\nExam Name:SSC Stenographer Grade C and D Examination\nFor Which Posts:Stenographer Grade C Group B Non-Gazetted in ministries like MEA, Defence and CVC; Stenographer Grade D Group C in various Central Government departments such as Income Tax and CAG\nFor Whom:Indian citizens who have passed Class 12th (Intermediate) from a recognized board\nFor Which Stream:Any stream including Arts, Science and Commerce; No Mathematics in exam\nAge Limit Grade C:18–30 years (General Category)\nAge Limit Grade D:18–27 years (General Category)\nWhen:Conducted once a year with notification usually mid-year and exam in October or November\nWhy:To recruit stenographers who assist officers by taking dictation and maintaining official records\nSelection Process:Computer Based Examination and Skill Test in Stenography\nStage 1:Computer Based Examination Format:Online Objective Test 2 Hours\nSubjects:General Intelligence and Reasoning 50 Questions 50 Marks; General Awareness 50 Questions 50 Marks; English Language and Comprehension 100 Questions 100 Marks\nTotal Marks:200 Marks (200 Questions)\nNegative Marking:0.25 marks deducted for each wrong answer\nWritten Cutoff Grade C:Generally 140–150+ marks\nWritten Cutoff Grade D:Generally 130–140 marks\nStage 2:Skill Test Format:Dictation in shorthand followed by transcription on computer\nSkill Test Grade D Dictation Speed:80 words per minute for 10 minutes\nSkill Test Grade D Transcription Time:English 50 minutes; Hindi 65 minutes\nSkill Test Grade C Dictation Speed:100 words per minute for 10 minutes\nSkill Test Grade C Transcription Time:English 40 minutes; Hindi 55 minutes\nSkill Test Nature:Qualifying only and marks not added to merit; Excessive errors can lead to disqualification\nGrand Total Marks:200 Marks (Only Computer Based Exam counted for merit)\nFinal Selection Target:Grade C generally requires 155–160+ marks; Grade D generally requires 145–150+ marks'),
('SSC Selection Post', 'Type of Exam:Central (Conducted by the Staff Selection Commission)\nExam Name:SSC Selection Post Examination (Phase)\nFor Which Posts:Various isolated posts across Central Government departments including Girl Cadet Instructor, Research Assistant, Store Keeper, Canteen Attendant, Laboratory Assistant, Technical Operator and many others\nFor Whom:Eligibility depends on Post Code with three levels Matriculation Level for 10th Pass, Higher Secondary Level for 12th Pass and Graduate Level for Bachelor’s Degree holders\nSpecial Qualification Note:Many posts require specific qualifications such as Degree in Library Science, Diploma in Textiles or specialized experience; Competition is lower for such posts\nAge Limit:Varies by post generally 18–30 years with some posts limited to 25 or 27 years\nFor Which Stream:Any stream including Arts, Science and Commerce; Science graduates often eligible for more technical posts\nWhen:Conducted once a year under titles like Phase-XII or Phase-XIII with notification released early or mid-year\nWhy:To fill specialized vacancies in central departments where seats are very limited; Often called a hidden opportunity due to low competition for niche posts\nSelection Process:Computer Based Examination followed by Document Verification and Skill Test for specific posts\nStage 1:Computer Based Examination Format:Online Objective Test 60 Minutes\nExam Level:Candidates take exam according to their applied level Matriculation, Higher Secondary or Graduate; Separate exam conducted for each level\nSubjects:General Intelligence 25 Questions 50 Marks; General Awareness 25 Questions 50 Marks; Quantitative Aptitude 25 Questions 50 Marks; English Language 25 Questions 50 Marks\nTotal Marks:200 Marks (100 Questions)\nNegative Marking:0.50 marks deducted for each wrong answer\nStage 2:Document Scrutiny and Skill Test\nDocument Scrutiny:Candidates must submit documents proving eligibility for specific post code; Mismatch leads to rejection\nSkill Test:Required only for cer'),
('SSC JHT (Junior Hindi Translator)', 'Type of Exam:Central (Conducted by the Staff Selection Commission)\nExam Name:SSC Junior Hindi Translator and Senior Hindi Translator Examination\nFor Which Posts:Junior Translation Officer in Central Secretariat Official Language Service and Armed Forces Headquarters, Junior Hindi Translator and Junior Translator in various Ministries and Departments, Senior Hindi Translator and Senior Translator in Central Government offices\nFor Whom:Indian citizens with Master’s Degree in Hindi or English with the other language as compulsory or elective subject at degree level\nAdditional Qualification Note:Diploma or Certificate in Translation or 2–3 years translation experience required if degree subject combination does not strictly meet Hindi and English rule\nAge Limit:18–30 years (General Category)\nAge Relaxation:OBC +3 years, SC/ST +5 years\nFor Which Stream:Arts and Humanities stream with specialization in Hindi or English language at postgraduate level\nWhen:Conducted once a year with notification usually mid-year and Paper 1 in October or November\nWhy:To recruit officials responsible for translation and implementation of Official Language policy in government offices\nSelection Process:Paper 1 Computer Based Test, Paper 2 Descriptive Test, Document Verification\nStage 1:Paper 1 Format:Computer Based Objective Test 2 Hours\nSubjects Paper 1:General Hindi 100 Questions 100 Marks; General English 100 Questions 100 Marks\nPaper 1 Total:200 Questions 200 Marks\nPaper 1 Negative Marking:0.25 marks deducted for each wrong answer\nPaper 1 Cutoff:Generally 135–145+ marks required to qualify for Paper 2\nStage 2:Paper 2 Format:Descriptive Written Examination 2 Hours\nPaper 2 Content:One passage Hindi to English translation, One passage English to Hindi translation, One essay in Hindi, One essay in English\nPaper 2 Total Marks:200 Marks\nPaper 2 Nature:Marks counted for final merit ranking\nGrand Total Marks:400 Marks (200 Paper 1 + 200 Paper 2)\nFinal Selection Target:Junior Translator posts gene'),
('Delhi Police Constable (SSC)', 'Type of Exam:Central (Conducted by the Staff Selection Commission)\nExam Name:Delhi Police Constable (Executive) Examination\nFor Which Posts:Constable Executive Group C in Delhi Police responsible for law and order duties in National Capital Territory\nFor Whom:Indian citizens who have passed Class 12th (Senior Secondary) from a recognized board\nCritical Requirement Male Only:Valid Driving License for LMV (Motorcycle or Car) required at time of Physical Test; Learner’s License not accepted\nAge Limit:18–25 years (General Category)\nAge Relaxation:OBC +3 years, SC/ST +5 years, Sports persons +5 or 10 years as applicable\nFor Which Stream:Any stream including Arts, Science and Commerce\nWhen:Conducted once a year with notification usually in September and exam in November or December\nWhy:Recruitment for Delhi Police under Ministry of Home Affairs with better pay, facilities and metropolitan posting\nSelection Process:Computer Based Examination, Physical Endurance and Measurement Test, Medical Examination\nStage 1:Computer Based Examination Format:Online Objective Test 90 Minutes\nSubjects:General Knowledge and Current Affairs 50 Questions 50 Marks; Reasoning 25 Questions 25 Marks; Numerical Ability 15 Questions 15 Marks; Computer Fundamentals 10 Questions 10 Marks\nTotal Marks:100 Marks (100 Questions)\nNegative Marking:0.25 marks deducted for each wrong answer\nWritten Cutoff Male:Generally 70–75+ marks for General category\nWritten Cutoff Female:Generally 60–65+ marks for General category\nStage 2:Physical Endurance and Measurement Test Qualifying Only\nPhysical Endurance Male:1600 meters in 6 minutes; Long Jump 14 feet; High Jump 3 feet 9 inches\nPhysical Endurance Female:1600 meters in 8 minutes; Long Jump 10 feet; High Jump 3 feet\nPhysical Standard Height Male:170 centimeters with relaxation for certain categories\nPhysical Standard Height Female:157 centimeters with relaxation for certain categories\nChest Requirement Male Only:81 to 85 centimeters with minimum 4 centimeter expan'),
('RRB NTPC', 'Type of Exam:Central (Conducted by the Railway Recruitment Board)\nExam Name:RRB NTPC (Non-Technical Popular Categories) Examination\nFor Which Posts:Non-Technical Group C posts in Indian Railways including Junior Clerk cum Typist, Accounts Clerk cum Typist, Junior Time Keeper, Trains Clerk, Commercial cum Ticket Clerk, Traffic Assistant, Goods Guard, Senior Commercial cum Ticket Clerk, Senior Clerk cum Typist, Junior Account Assistant cum Typist, Senior Time Keeper, Commercial Apprentice and Station Master\nFor Whom:12th Pass candidates eligible for Level 2 and 3 posts; Graduates eligible for all levels 2, 3, 4, 5 and 6 posts\nAge Limit 12th Level:18–30 years (General Category)\nAge Limit Graduate Level:18–33 years (General Category)\nAge Relaxation:OBC +3 years, SC/ST +5 years\nFor Which Stream:Any stream including Arts, Science, Commerce and Engineering\nWhen:Conducted irregularly depending on vacancies and not held annually\nWhy:To recruit staff for railway station operations, ticketing and goods management; Station Master is considered one of the most prestigious posts\nSelection Process:CBT-1, CBT-2, CBAT for specific posts, Typing Skill Test for clerical posts, Document Verification and Medical Examination\nStage 1:CBT-1 Format:Computer Based Test 90 Minutes\nSubjects CBT-1:General Awareness 40 Questions 40 Marks; Mathematics 30 Questions 30 Marks; General Intelligence and Reasoning 30 Questions 30 Marks\nCBT-1 Total:100 Questions 100 Marks\nCBT-1 Negative Marking:One-third mark deducted for each wrong answer\nCBT-1 Cutoff:Generally 70–80+ marks required to qualify for CBT-2\nStage 2:CBT-2 Format:Computer Based Test 90 Minutes\nSubjects CBT-2:General Awareness 50 Questions 50 Marks; Mathematics 35 Questions 35 Marks; General Intelligence and Reasoning 35 Questions 35 Marks\nCBT-2 Total:120 Questions 120 Marks\nCBT-2 Negative Marking:One-third mark deducted for each wrong answer\nStage 3:CBAT and Typing Skill Test\nCBAT:Computer Based Aptitude Test mandatory for Station Master and'),
('RRB Group D', 'Type of Exam:Central (Conducted by Railway Recruitment Cells on behalf of RRBs)\nExam Name:RRB Group D Level 1 Examination\nFor Which Posts:Track Maintainer Grade IV, Assistant or Helper in Electrical Mechanical and Signal departments, Assistant Pointsman and Hospital Assistant in Railway departments\nFor Whom:Indian citizens who have passed Class 10th (Matriculation) or ITI from NCVT or SCVT\nImportant Qualification Note:Future recruitments may require ITI or National Apprenticeship Certificate for technical posts while 10th pass remains valid for certain non-technical posts; Always check official notification\nAge Limit:18–33 years (General Category)\nAge Relaxation:OBC +3 years, SC/ST +5 years\nFor Which Stream:Any stream since eligibility is based on 10th or ITI qualification\nWhen:Conducted irregularly depending on vacancies and not held annually\nWhy:To recruit field-level workforce responsible for maintenance and safe operation of railway infrastructure\nSelection Process:Computer Based Test, Physical Efficiency Test, Document Verification and Medical Examination\nStage 1:Computer Based Test Format:Online Objective Test 90 Minutes\nSubjects:General Science 25 Questions 25 Marks; Mathematics 25 Questions 25 Marks; General Intelligence and Reasoning 30 Questions 30 Marks; General Awareness and Current Affairs 20 Questions 20 Marks\nTotal Marks:100 Marks (100 Questions)\nNegative Marking:One-third mark deducted for each wrong answer\nWritten Cutoff:Generally 70–75+ marks required for General category depending on RRC zone\nStage 2:Physical Efficiency Test Qualifying Only\nPET Male Weight Carrying:35 kilograms for 100 meters in 2 minutes without putting weight down\nPET Male Running:1000 meters in 4 minutes 15 seconds\nPET Female Weight Carrying:20 kilograms for 100 meters in 2 minutes without putting weight down\nPET Female Running:1000 meters in 5 minutes 40 seconds\nGrand Total Marks:100 Marks (Only CBT score counted for merit)\nFinal Selection Target:General category candidates ge'),
('RRB ALP', 'Type of Exam:Central (Conducted by the Railway Recruitment Board)\nExam Name:RRB Assistant Loco Pilot (ALP) Examination\nFor Which Posts:Assistant Loco Pilot responsible for assisting in driving goods and passenger trains; Same recruitment may also include Technician Grade III posts with slightly different eligibility\nFor Whom:Indian citizens with Matriculation plus ITI in relevant trades or Diploma or Degree in Engineering in Mechanical, Electrical, Electronics or Automobile streams\nAge Limit:18–30 years (General Category)\nRecent Age Relaxation Note:Additional 3-year relaxation often provided in recent notifications making upper age 33 years\nFor Which Stream:Technical stream only; ITI, Diploma or B.Tech in specified engineering trades; General graduation not eligible\nWhen:Conducted irregularly depending on vacancies and not held annually\nWhy:To recruit technical crew responsible for safe train operations; High responsibility job with good salary and allowances\nSelection Process:CBT-1, CBT-2, Computer Based Aptitude Test, Medical Examination\nStage 1:CBT-1 Format:Computer Based Objective Test 60 Minutes\nSubjects CBT-1:Mathematics 20 Questions 20 Marks; General Intelligence and Reasoning 25 Questions 25 Marks; General Science 20 Questions 20 Marks; General Awareness 10 Questions 10 Marks\nCBT-1 Total:75 Questions 75 Marks\nCBT-1 Negative Marking:One-third mark deducted for each wrong answer\nCBT-1 Cutoff:Generally 45–55+ marks required to qualify for CBT-2\nStage 2:CBT-2 Format:Computer Based Objective Test with two parts\nCBT-2 Part A Subjects:Mathematics, Reasoning, Basic Science and Engineering, General Awareness\nCBT-2 Part A Questions:100 Questions 90 Minutes\nCBT-2 Part A Role:Marks counted for final merit ranking\nCBT-2 Part B Trade Test:Questions from candidate’s specific ITI or Diploma trade\nCBT-2 Part B Questions:75 Questions 60 Minutes\nCBT-2 Part B Requirement:Minimum 35% marks required to qualify; Failure leads to disqualification\nStage 3:Computer Based Aptitude Tes'),
('RRB Technician', 'Type of Exam:Central (Conducted by the Railway Recruitment Board)\nExam Name:RRB Technician Examination\nFor Which Posts:Technical staff responsible for maintenance and repair of railway signal, telecommunication, electrical and mechanical systems; Includes Technician Grade 1 Signal (Level 5) and Technician Grade 3 (Level 2)\nFor Whom Technician Grade 1 Signal:Candidates with B.Sc in Physics, Electronics, Computer Science or IT OR Diploma or B.E./B.Tech in relevant engineering streams\nFor Whom Technician Grade 3:Candidates with Matriculation plus ITI in relevant trade OR 10+2 with Physics and Mathematics for certain Signal and Telecommunication posts\nAge Limit Grade 1 Signal:18–36 years (General Category)\nAge Limit Grade 3:18–33 years (General Category)\nAge Relaxation:OBC +3 years, SC/ST +5 years\nFor Which Stream:Science and Technical streams only; Arts and Commerce not eligible\nWhen:Conducted irregularly depending on vacancies; Recent separate notification released specifically for Technician posts\nWhy:To recruit skilled technical workforce ensuring operational safety of trains and signaling systems; Grade 1 Signal is a higher responsibility post with better salary\nSelection Process:Single Computer Based Test, Document Verification and Medical Examination\nMajor Pattern Change:No second stage CBT and no Psycho Test for Technician exam in latest pattern\nStage 1:Technician Grade 1 Signal CBT Format:Computer Based Objective Test 90 Minutes\nSubjects Grade 1 Signal:General Awareness 10 Questions 10 Marks; General Intelligence and Reasoning 15 Questions 15 Marks; Basics of Computers and Applications 20 Questions 20 Marks; Mathematics 20 Questions 20 Marks; Basic Science and Engineering 35 Questions 35 Marks\nGrade 1 Signal Total:100 Questions 100 Marks\nGrade 1 Signal Negative Marking:One-third mark deducted for each wrong answer\nGrade 1 Signal Cutoff Target:Generally 75–80+ marks required\nStage 1:Technician Grade 3 CBT Format:Computer Based Objective Test 90 Minutes\nSubjects '),
('RRB JE', 'Type of Exam:Central (Conducted by the Railway Recruitment Board)\nExam Name:RRB Junior Engineer (JE), Depot Material Superintendent (DMS) and Chemical & Metallurgical Assistant (CMA) Examination\nFor Which Posts:Junior Engineer in Civil, Electrical, Mechanical, Signal and Telecom departments; Depot Material Superintendent for material and store management; Chemical and Metallurgical Assistant in Railway production units\nFor Whom:JE and DMS require Diploma or Degree in Engineering; CMA requires B.Sc Degree with Physics and Chemistry and minimum 45% marks\nFor Which Stream:Science and Engineering streams only; Arts and Commerce graduates not eligible\nAge Limit:18–33 years (General Category)\nRecent Age Relaxation Note:Additional 3-year relaxation often provided making upper age 36 years in some notifications\nWhen:Conducted irregularly depending on vacancy notifications and not held annually\nWhy:To recruit technical supervisors in Indian Railways offering stable career growth and supervisory responsibilities\nSelection Process:CBT-1 Screening Test, CBT-2 Merit Test, Document Verification and Medical Examination\nStage 1:CBT-1 Format:Computer Based Objective Test 90 Minutes\nSubjects CBT-1:Mathematics 30 Questions 30 Marks; General Intelligence and Reasoning 25 Questions 25 Marks; General Awareness 15 Questions 15 Marks; General Science 30 Questions 30 Marks\nCBT-1 Total:100 Questions 100 Marks\nCBT-1 Negative Marking:One-third mark deducted for each wrong answer\nCBT-1 Role:Qualifying only and marks not counted in final merit\nCBT-1 Cutoff:Generally 60–75 marks required to qualify for CBT-2 depending on zone and category\nStage 2:CBT-2 Format:Computer Based Objective Test 120 Minutes\nSubjects CBT-2:General Awareness 15 Questions 15 Marks; Physics and Chemistry 15 Questions 15 Marks; Basics of Computers 10 Questions 10 Marks; Environment and Pollution Control 10 Questions 10 Marks; Technical Abilities 100 Questions 100 Marks\nCBT-2 Total:150 Questions 150 Marks\nCBT-2 Feature:Virtua'),
('RRB Paramedical', 'Type of Exam:Central (Conducted by the Railway Recruitment Board)\nExam Name:RRB Paramedical Categories Examination\nFor Which Posts:Staff Nurse, Health and Malaria Inspector, Pharmacist, Radiographer, Lab Superintendent, Lab Assistant, ECG Technician, Dietician, Optometrist and other paramedical staff in Railway hospitals and health units\nFor Whom:Indian citizens with post-specific medical or paramedical qualifications\nQualification Staff Nurse:Three-year GNM course or B.Sc Nursing\nQualification Pharmacist:10+2 Science plus Diploma or Degree in Pharmacy with registration in Pharmacy Council\nQualification Health and Malaria Inspector:B.Sc Chemistry plus Diploma in Health or Sanitary Inspector course\nQualification Lab Assistant:12th Science plus Diploma in Medical Lab Technology\nQualification Radiographer:10+2 Physics and Chemistry plus Diploma in Radiography or X-Ray Technology\nAge Limit Staff Nurse:20–40 years\nAge Limit Other Posts:Generally 18–33 or 18–35 years depending on post\nAge Relaxation:OBC +3 years, SC/ST +5 years\nFor Which Stream:Medical and Science streams only\nWhen:Conducted irregularly based on vacancy notifications and not held annually\nWhy:To recruit paramedical workforce providing healthcare services to railway employees and families\nSelection Process:Single Computer Based Test, Document Verification and Medical Examination\nStage 1:Computer Based Test Format:Online Objective Test 90 Minutes\nSubjects Professional Ability:70 Questions 70 Marks based on specific discipline such as Nursing or Pharmacy\nSubjects General Awareness:10 Questions 10 Marks\nSubjects General Arithmetic and Reasoning:10 Questions 10 Marks\nSubjects General Science:10 Questions 10 Marks\nTotal Marks:100 Marks (100 Questions)\nNegative Marking:One-third mark deducted for each wrong answer\nWritten Cutoff:Generally 65–75+ marks required for General category depending on post\nGrand Total Marks:100 Marks (Only CBT score counted for merit)\nFinal Selection Focus:Strong command over profession');
INSERT INTO `exams` (`exam_name`, `detail`) VALUES
('RRB Ministerial & Isolated Categories', 'Type of Exam:Central (Conducted by the Railway Recruitment Board)\nExam Name:RRB Ministerial and Isolated Categories Examination\nFor Which Posts:Specialized posts including Junior Stenographer Hindi or English, Junior Translator Hindi, Staff and Welfare Inspector, Chief Law Assistant, Teachers PGT TGT PRT, Lab Assistant, Head Cook, Cook, Publicity Inspector, Photographer, Finger Print Examiner and other isolated categories\nFor Whom:Indian citizens with post-specific professional qualifications such as 12th pass with shorthand for Stenographer, Master’s Degree in Hindi or English with Translation Diploma for Translator, Law Degree with experience for Law Assistant, 10th plus cookery course for Cook, and B.Ed with CTET or TET for Teachers\nAge Limit Stenographer:18–30 years\nAge Limit Translator and Law Assistant:Generally 18–33 or up to 40 years depending on post\nAge Limit Teachers:Often up to 45 or 48 years depending on post\nFor Which Stream:Specialized streams such as Law, Languages, Education, Music, Catering and other professional fields\nWhen:Conducted irregularly when vacancies arise and not held annually\nWhy:To recruit specialized professionals for supporting services within the Railway system\nSelection Process:Single Stage Computer Based Test, Skill or Performance Test depending on post, Document Verification and Medical Examination\nStage 1:Computer Based Test Format:Online Objective Test 90 Minutes\nSubjects Professional Ability:50 Questions 50 Marks based on post-specific subject\nSubjects General Awareness:15 Questions 15 Marks\nSubjects General Intelligence and Reasoning:15 Questions 15 Marks\nSubjects Mathematics:10 Questions 10 Marks\nSubjects General Science:10 Questions 10 Marks\nException for Stenographer:Paper consists of General Awareness 50 Questions and Hindi or English Language 50 Questions without Mathematics or Science\nTotal Marks:100 Marks (100 Questions)\nNegative Marking:One-third mark deducted for each wrong answer\nWritten Cutoff:Generally 75–85+ mar'),
('IBPS PO', 'Type of Exam:Central (Conducted by the Institute of Banking Personnel Selection)\nExam Name:IBPS Probationary Officer (PO) Examination\nFor Which Posts:Probationary Officer Scale I Assistant Manager in participating Public Sector Banks other than SBI\nFor Whom:Indian citizens with a Bachelor’s Degree in any stream from a recognized university\nAge Limit:20–30 years (General Category)\nAge Relaxation:OBC +3 years, SC/ST +5 years\nFor Which Stream:Any stream including Arts, Science, Commerce and Engineering\nWhen:Conducted once a year with notification usually in August and Prelims in September or October\nWhy:To recruit entry-level managers in public sector banks with career progression to senior management roles\nSelection Process:Preliminary Exam, Main Exam and Interview\nStage 1:Preliminary Examination Format:Online Objective Test 60 Minutes with sectional timing\nSubjects English Language:30 Questions 30 Marks 20 Minutes\nSubjects Quantitative Aptitude:35 Questions 35 Marks 20 Minutes\nSubjects Reasoning Ability:35 Questions 35 Marks 20 Minutes\nPrelims Total:100 Questions 100 Marks\nNegative Marking:0.25 marks deducted for each wrong answer\nPrelims Requirement:Must clear sectional cutoff in each subject and overall cutoff\nStage 2:Main Examination Format:Object ive Test plus Descriptive Test conducted on same day\nMains Objective Section Reasoning and Computer Aptitude:45 Questions 60 Marks 60 Minutes\nMains Objective Section General Economy and Banking Awareness:40 Questions 40 Marks 35 Minutes\nMains Objective Section English Language:35 Questions 40 Marks 40 Minutes\nMains Objective Section Data Analysis and Interpretation:35 Questions 60 Marks 45 Minutes\nMains Objective Total:155 Questions 200 Marks\nMains Descriptive Test:Letter and Essay writing 25 Marks 30 Minutes\nMains Total Marks:225 Marks\nNegative Marking:0.25 marks deducted for each wrong answer in objective section\nStage 3:Interview Format:Face-to-face personality test\nInterview Marks:100 Marks\nMinimum Interview Qualifyi'),
('IBPS Clerk', 'Type of Exam:Central (Conducted by the Institute of Banking Personnel Selection)\nExam Name:IBPS Clerk (Customer Service Associate) Examination\nFor Which Posts:Clerical cadre posts such as Clerk or Junior Associate in participating Public Sector Banks other than SBI\nFor Whom:Indian citizens with a Bachelor’s Degree in any stream from a recognized university\nLanguage Requirement:Candidate must be proficient in the official language of the state or union territory applied for including reading, writing and speaking\nAge Limit:20–28 years (General Category)\nAge Relaxation:OBC +3 years, SC/ST +5 years\nFor Which Stream:Any stream including Arts, Science, Commerce and Engineering\nWhen:Conducted once a year with notification usually in June or July and Prelims in August or September\nWhy:To recruit front-line banking staff who handle customer transactions and branch operations\nSelection Process:Preliminary Examination and Main Examination; No Interview stage\nStage 1:Preliminary Examination Format:Online Objective Test 60 Minutes with sectional timing\nSubjects English Language:30 Questions 30 Marks 20 Minutes\nSubjects Numerical Ability:35 Questions 35 Marks 20 Minutes\nSubjects Reasoning Ability:35 Questions 35 Marks 20 Minutes\nPrelims Total:100 Questions 100 Marks\nNegative Marking:0.25 marks deducted for each wrong answer\nPrelims Requirement:Must clear sectional cutoff in each subject and overall state cutoff\nStage 2:Main Examination Format:Online Objective Test 160 Minutes\nSubjects General and Financial Awareness:50 Questions 50 Marks 35 Minutes\nSubjects General English:40 Questions 40 Marks 35 Minutes\nSubjects Reasoning Ability and Computer Aptitude:50 Questions 60 Marks 45 Minutes\nSubjects Quantitative Aptitude:50 Questions 50 Marks 45 Minutes\nMains Total:190 Questions 200 Marks\nNegative Marking:0.25 marks deducted for each wrong answer\nLanguage Proficiency Test:Candidates who have not studied the local language in 10th or 12th must pass LPT before appointment\nGrand Total M'),
('IBPS SO', 'Type of Exam:Central (Conducted by the Institute of Banking Personnel Selection)\nExam Name:IBPS Specialist Officer (SO) Examination\nFor Which Posts:Scale I Specialist Officers including IT Officer, Agricultural Field Officer, Rajbhasha Adhikari, Law Officer, HR or Personnel Officer and Marketing Officer in participating Public Sector Banks\nFor Whom:Indian citizens with professional degree relevant to the applied post\nQualification IT Officer:B.E. or B.Tech in Computer Science, IT, Electronics or MCA\nQualification Agricultural Field Officer:Four-year degree in Agriculture, Horticulture, Veterinary Science or related fields\nQualification Rajbhasha Adhikari:Postgraduate degree in Hindi or Sanskrit with English as a subject at degree level\nQualification Law Officer:LLB degree and enrolled as an advocate\nQualification HR Officer:MBA or PGDBM in HR or Personnel Management\nQualification Marketing Officer:MBA or PGDBM in Marketing\nAge Limit:20–30 years (General Category)\nAge Relaxation:OBC +3 years, SC/ST +5 years\nFor Which Stream:Specialized professional streams only; General graduates not eligible\nWhen:Conducted once a year with notification usually in November and Prelims in December\nWhy:To recruit domain experts in banking sector for specialized functional roles\nSelection Process:Preliminary Examination, Main Examination and Interview\nStage 1:Preliminary Examination Format:Online Objective Test Qualifying Only\nPrelims Pattern Law and Rajbhasha Officers:English Language 50 Questions 25 Marks; Reasoning 50 Questions 50 Marks; General Awareness with Banking focus 50 Questions 50 Marks\nPrelims Pattern IT Agriculture HR and Marketing Officers:English Language 50 Questions 25 Marks; Reasoning 50 Questions 50 Marks; Quantitative Aptitude 50 Questions 50 Marks\nPrelims Total:150 Questions 125 Marks\nPrelims Requirement:Must clear sectional cutoff in each subject\nStage 2:Main Examination Format:Online Objective Test 45 Minutes\nMains Subject:Professional Knowledge based on candidat'),
('IBPS RRB Officer Scale I, II, III', 'Type of Exam:Central (Conducted by IBPS for Regional Rural Banks)\nExam Name:IBPS RRB Officer Scale I II and III Examination\nFor Which Posts:Officer Scale I Assistant Manager, Officer Scale II Manager including General Banking Officer and Specialist Officers, Officer Scale III Senior Manager\nFor Whom Scale I:Bachelor’s Degree in any stream and freshers eligible\nFor Whom Scale II:Bachelor’s Degree plus 2 years experience for General Banking Officer or 1 year experience for Specialist Officers\nFor Whom Scale III:Bachelor’s Degree plus minimum 5 years experience in banking or finance sector\nLanguage Requirement:Candidate must be proficient in local language of the state applied for\nAge Limit Scale I:18–30 years\nAge Limit Scale II:21–32 years\nAge Limit Scale III:21–40 years\nAge Relaxation:OBC +3 years, SC/ST +5 years\nFor Which Stream:Any stream including Arts, Science, Commerce and Agriculture; Agriculture background often preferred\nWhen:Conducted once a year with notification usually in June and Prelims in August\nWhy:To recruit officers for Regional Rural Banks serving rural and semi-urban areas\nSelection Process Scale I:Preliminary Examination, Main Examination and Interview\nSelection Process Scale II and III:Single Level Written Exam followed by Interview\nStage 1 Scale I Preliminary Exam Format:Online Objective Test 45 Minutes Composite Time\nSubjects Scale I Prelims:Reasoning 40 Questions 40 Marks; Quantitative Aptitude 40 Questions 40 Marks\nPrelims Total Scale I:80 Questions 80 Marks\nUnique Feature:No English section in Scale I Prelims\nPrelims Cutoff:Generally 50–60+ marks depending on state\nStage 2 Scale I Mains Exam Format:Online Objective Test 2 Hours\nSubjects Scale I Mains:Reasoning 40 Questions 50 Marks; Quantitative Aptitude 40 Questions 50 Marks; General Awareness 40 Questions 40 Marks; Computer Knowledge 40 Questions 20 Marks; English or Hindi Language 40 Questions 40 Marks\nMains Total Scale I:200 Questions 200 Marks\nNegative Marking:0.25 marks deducted for e'),
('IBPS RRB Office Assistant', 'Type of Exam:Central (Conducted by IBPS for Regional Rural Banks)\nExam Name:IBPS RRB Office Assistant (Multipurpose) Examination\nFor Which Posts:Office Assistant Multipurpose clerical cadre handling customer service, cash transactions and account operations in rural bank branches\nFor Whom:Indian citizens with a Bachelor’s Degree in any stream from a recognized university\nLanguage Requirement:Candidate must be proficient in the local language of the state applied for including reading, writing and speaking\nExperience Requirement:No prior experience required and freshers eligible\nAge Limit:18–28 years (General Category)\nAge Relaxation:OBC +3 years, SC/ST +5 years\nFor Which Stream:Any stream including Arts, Science and Commerce\nWhen:Conducted once a year with notification usually in June and Prelims in August\nWhy:Popular entry-level banking job in rural banks with comparatively easier syllabus but very high cutoffs\nSelection Process:Preliminary Examination and Main Examination followed by Language Proficiency Test if required\nStage 1:Preliminary Examination Format:Online Objective Test 45 Minutes Composite Time\nSubjects Preliminary:Reasoning 40 Questions 40 Marks; Numerical Ability 40 Questions 40 Marks\nPrelims Total:80 Questions 80 Marks\nUnique Feature:No English section in Preliminary exam\nPrelims Cutoff:Generally very high often 70–75+ marks depending on state\nStage 2:Main Examination Format:Online Objective Test 2 Hours\nSubjects Mains Reasoning:40 Questions 50 Marks\nSubjects Mains Numerical Ability:40 Questions 50 Marks\nSubjects Mains General Awareness:40 Questions 40 Marks\nSubjects Mains Computer Knowledge:40 Questions 20 Marks\nSubjects Mains Language English or Hindi:40 Questions 40 Marks\nMains Total:200 Questions 200 Marks\nNegative Marking:0.25 marks deducted for each wrong answer\nLanguage Proficiency Test:Candidates not having studied local language in school must pass LPT before appointment\nGrand Total Marks:200 Marks (Only Mains score counted for final merit)'),
('SBI PO', 'Type of Exam:Central (Conducted by the State Bank of India)\nExam Name:SBI Probationary Officer (PO) Examination\nFor Which Posts:Probationary Officer Scale I in State Bank of India\nFor Whom:Indian citizens with a Bachelor’s Degree in any stream from a recognized university; Final year students may apply provisionally\nAge Limit:21–30 years (General Category)\nAge Relaxation:OBC +3 years, SC/ST +5 years\nAttempt Limit:General 4 attempts, EWS 7 attempts, OBC 7 attempts, SC/ST no limit\nFor Which Stream:Any stream including Arts, Science, Commerce and Engineering\nWhen:Conducted once a year with notification usually in September or October\nWhy:To recruit officers for India’s largest public sector bank offering high salary, faster promotions and better allowances\nSelection Process:Preliminary Examination, Main Examination, Psychometric Test, Group Exercise and Interview\nStage 1:Preliminary Examination Format:Online Objective Test 60 Minutes with sectional timing\nSubjects English Language:30 Questions 30 Marks 20 Minutes\nSubjects Quantitative Aptitude:35 Questions 35 Marks 20 Minutes\nSubjects Reasoning Ability:35 Questions 35 Marks 20 Minutes\nPrelims Total:100 Questions 100 Marks\nNegative Marking:0.25 marks deducted for each wrong answer\nUnique Feature:No sectional cutoff, only overall cutoff considered\nPrelims Cutoff:Generally around 59–65 marks for General category\nStage 2:Main Examination Format:Objective Test plus Descriptive Test conducted on same day\nMains Objective Section Reasoning and Computer Aptitude:40 Questions 50 Marks 50 Minutes\nMains Objective Section Data Analysis and Interpretation:30 Questions 50 Marks 45 Minutes\nMains Objective Section General Economy and Banking Awareness:50 Questions 60 Marks 45 Minutes\nMains Objective Section English Language:35 Questions 40 Marks 40 Minutes\nMains Objective Total:155 Questions 200 Marks\nMains Descriptive Test:Letter Writing and Essay Writing 50 Marks 30 Minutes\nMains Total Marks:250 Marks\nUnique Feature:No sectional cuto'),
('SBI Clerk', 'Type of Exam:Central (Conducted by the State Bank of India)\nExam Name:SBI Junior Associate (Customer Support and Sales) Examination\nFor Which Posts:Clerical cadre post handling customer service, cash transactions, account opening and sales of banking products\nFor Whom:Indian citizens with a Bachelor’s Degree in any stream from a recognized university\nLanguage Requirement:Candidate must be proficient in the local language of the state applied for\nAge Limit:20–28 years (General Category)\nAge Relaxation:OBC +3 years, SC/ST +5 years\nFor Which Stream:Any stream including Arts, Science and Commerce\nWhen:Conducted once a year with notification usually in April or May\nWhy:Entry-level job in India’s largest public sector bank with good promotion opportunities to officer cadre\nSelection Process:Preliminary Examination, Main Examination and Language Proficiency Test if required\nStage 1:Preliminary Examination Format:Online Objective Test 60 Minutes with sectional timing\nSubjects English Language:30 Questions 30 Marks 20 Minutes\nSubjects Quantitative Aptitude:35 Questions 35 Marks 20 Minutes\nSubjects Reasoning Ability:35 Questions 35 Marks 20 Minutes\nPrelims Total:100 Questions 100 Marks\nNegative Marking:0.25 marks deducted for each wrong answer\nUnique Feature:No sectional cutoff, only overall cutoff considered\nPrelims Cutoff:Generally 65–75+ marks depending on state\nStage 2:Main Examination Format:Online Objective Test 2 Hours 40 Minutes\nSubjects General and Financial Awareness:50 Questions 50 Marks 35 Minutes\nSubjects General English:40 Questions 40 Marks 35 Minutes\nSubjects Quantitative Aptitude:50 Questions 50 Marks 45 Minutes\nSubjects Reasoning Ability and Computer Aptitude:50 Questions 60 Marks 45 Minutes\nMains Total:190 Questions 200 Marks\nNegative Marking:0.25 marks deducted for each wrong answer\nUnique Feature:No sectional cutoff in Mains\nLanguage Proficiency Test:Candidates not having studied local language in school must pass LPT before appointment\nGrand Total Marks:'),
('SBI SO', 'Type of Exam:Central (Conducted by the State Bank of India)\nExam Name:SBI Specialist Cadre Officer (SCO) Recruitment\nFor Which Posts:Specialist roles such as Assistant Manager Systems, Deputy Manager Law, Relationship Manager Wealth, Credit Officer and Engineers Civil or Electrical\nFor Whom:Indian citizens with professional qualifications relevant to the specific post\nQualification Systems IT:B.E. or B.Tech in Computer Science, IT or Electronics or MCA or M.Sc IT\nQualification Law:LLB degree with enrollment as advocate and often prior experience\nQualification Wealth or Credit:MBA or PGDM with relevant work experience\nAge Limit Systems:21–30 years\nAge Limit Law:25–35 years\nAge Limit Wealth or Credit:Usually 23–35 years or higher depending on role\nFor Which Stream:Specialized streams such as Engineering, Law and Management\nWhen:Recruitment is irregular with separate notifications released for different specialist roles throughout the year\nWhy:To recruit domain experts for specialized functions in India’s largest public sector bank including IT systems, legal affairs and wealth management\nSelection Process Regular Posts:Online Written Test followed by Interview\nSelection Process Contractual or Lateral Posts:Shortlisting based on experience and Interview only without written test\nStage 1:Online Written Test for Systems and Law Posts\nPaper 1 General Aptitude Qualifying Only:English Language 35 Questions 35 Marks; Reasoning Ability 50 Questions 50 Marks; Quantitative Aptitude 35 Questions 35 Marks\nPaper 2 Professional Knowledge Systems:75 Questions 150 Marks duration around 70 minutes\nPaper 2 Professional Knowledge Law:50 Questions 100 Marks duration around 45 minutes\nProfessional Knowledge Role:Marks from this section determine merit ranking\nStage 2:Interview\nInterview Marks:Usually 25 or sometimes 50 depending on notification\nFinal Merit Weightage:Professional Knowledge written test around 70 percent and Interview around 30 percent\nFinal Selection Focus IT Officers:Stro'),
('RBI Grade B', 'Type of Exam:Central (Conducted by the Reserve Bank of India)\nExam Name:RBI Grade B Officer Examination\nFor Which Posts:Grade B Officer Manager responsible for monetary policy, currency management, banking supervision and financial stability\nStreams:General Direct Recruitment, DEPR for Economics postgraduates, DSIM for Statistics postgraduates\nFor Whom:Indian citizens with a Bachelor’s Degree in any stream\nMinimum Marks Requirement:At least 60 percent in Graduation and 60 percent in 10th and 12th for General category; 50 percent for SC, ST and PwBD\nAge Limit:21–30 years (General Category)\nAge Relaxation:MPhil and PhD holders eligible for upper age relaxation up to 32 or 34 years depending on qualification\nAttempt Limit:General and EWS limited to 6 attempts; No limit for SC, ST and OBC\nWhen:Conducted once a year with notification usually mid-year and Phase 1 in July or August\nWhy:High-paying central bank officer job with prestigious role in financial governance\nSelection Process:Phase 1 Objective Test, Phase 2 Objective plus Descriptive Test and Interview\nStage 1:Phase 1 Format:Online Objective Test 120 Minutes\nSubjects General Awareness:80 Questions 80 Marks\nSubjects Reasoning Ability:60 Questions 60 Marks\nSubjects English Language:30 Questions 30 Marks\nSubjects Quantitative Aptitude:30 Questions 30 Marks\nPhase 1 Total:200 Questions 200 Marks\nNegative Marking:0.25 marks deducted for each wrong answer\nPhase 1 Requirement:Must clear sectional cutoffs and overall cutoff; Marks not counted in final merit\nStage 2:Phase 2 Format:Objective plus Descriptive Tests conducted online with typing answers\nPaper 1 Economic and Social Issues:Objective and Descriptive combined 100 Marks\nPaper 2 English Writing Skills:Descriptive Essay, Précis and Comprehension 100 Marks\nPaper 3 Finance and Management:Objective and Descriptive combined 100 Marks\nPhase 2 Total Marks:300 Marks\nDescriptive Mode:Answers must be typed on computer\nStage 3:Interview Marks:75 Marks\nPsychometric Test:Conducte'),
('RBI Assistant', 'Type of Exam:Central (Conducted by the Reserve Bank of India)\nExam Name:RBI Assistant Examination\nFor Which Posts:Assistant Clerical Cadre in RBI handling file work data entry document verification and support tasks in banking and currency departments\nFor Whom:Indian citizens with a Bachelor’s Degree in any stream\nMinimum Marks Requirement:Minimum 50 percent in Graduation Pass class for SC ST PwBD\nLanguage Requirement:Proficiency in the official language of the state or region applied for is mandatory\nAge Limit:20–28 years General Category\nAge Relaxation:OBC plus 3 years SC ST plus 5 years\nFor Which Stream:Any Stream Arts Science Commerce\nWhen:Irregular conducted only when vacancies arise\nWhy:Clerical job in RBI with strong salary benefits and lighter workload compared to officer roles\nSelection Process:Prelims Objective Test Mains Objective Test and Language Proficiency Test No Interview\nStage 1:Preliminary Exam Format Online Objective Test 60 Minutes with sectional timing\nEnglish Language:30 Questions 30 Marks 20 Minutes\nNumerical Ability:35 Questions 35 Marks 20 Minutes\nReasoning Ability:35 Questions 35 Marks 20 Minutes\nPrelims Total:100 Questions 100 Marks\nNegative Marking:0.25 marks deducted for each wrong answer\nPrelims Nature:Qualifying only marks not added to merit\nStage 2:Mains Exam Format Online Objective Test 135 Minutes\nReasoning:40 Questions 40 Marks 30 Minutes\nEnglish Language:40 Questions 40 Marks 30 Minutes\nNumerical Ability:40 Questions 40 Marks 30 Minutes\nGeneral Awareness:40 Questions 40 Marks 25 Minutes\nComputer Knowledge:40 Questions 40 Marks 20 Minutes\nMains Total:200 Questions 200 Marks\nNegative Marking:0.25 marks deducted for each wrong answer\nSectional Cutoff:Must pass each section individually\nStage 3:Language Proficiency Test Nature Reading Writing and Speaking test in local language\nLPT Rule:Mandatory failure leads to disqualification\nFinal Merit:Mains score out of 200 determines final selection'),
('NABARD Grade A & B', 'Type of Exam:Central Conducted by National Bank for Agriculture and Rural Development\nFor Which Posts:Grade A Assistant Manager entry level officer for rural policy and credit implementation Grade B Manager mid level officer supervising Grade A and handling policy decisions\nFor Whom:Grade A Bachelor Degree in any stream with 60 percent 55 percent for SC ST PwBD Grade B Master Degree with 60 percent OR Bachelor Degree with 60 percent sometimes experience required\nAge Limit:Grade A 21–30 years Grade B 25–32 years\nAge Relaxation:OBC plus 3 years SC ST plus 5 years\nFor Which Stream:Any Stream General OR Specialized Streams Agriculture IT Finance Forestry etc\nWhen:Once a Year Notification usually July or August\nWhy:Officer job in India’s apex rural development bank with high salary and policy level work\nSelection Process:Phase 1 Objective Test Phase 2 Objective plus Descriptive Test Interview\nStage 1:Phase 1 Online Objective Exam 120 Minutes\nReasoning:20 Questions 20 Marks\nEnglish Language:30 Questions 30 Marks\nComputer Knowledge:20 Questions 20 Marks\nQuantitative Aptitude:20 Questions 20 Marks\nDecision Making:10 Questions 10 Marks\nGeneral Awareness:20 Questions 20 Marks\nEconomic and Social Issues ESI:40 Questions 40 Marks\nAgriculture and Rural Development ARD:40 Questions 40 Marks\nPhase 1 Rule:Math Reasoning English Computer Decision Making are qualifying only GA ESI ARD decide merit for Phase 2 total merit marks considered 100\nStage 2:Phase 2 Mixed Objective plus Descriptive Typing Exam\nPaper 1 General English Descriptive:Essay Letter Report Precis Typing 100 Marks 90 Minutes\nPaper 2 ESI and ARD:Objectives 30 Questions 50 Marks 30 Minutes Descriptive 6 Questions attempt 4 for 50 Marks 90 Minutes Total 100 Marks\nPaper 3 Only for Grade B Development Economics Statistics Finance and Management Objective plus Descriptive Total 100 Marks\nStage 3:Interview Grade A 50 Marks Grade B 75 Marks\nFinal Merit:Grade A Total 250 Marks Phase 2 200 plus Interview 50 Grade B Total 375 Ma'),
('SEBI Grade A', 'Type of Exam:Central Conducted by Securities and Exchange Board of India\nFor Which Posts:Assistant Manager Grade A Officer in securities market regulation\nStreams:General Stream Administration and Management Legal Stream Law Graduates IT Stream Engineers MCA Research and Official Language Specialized Roles\nFor Whom:General Stream Masters Degree in any discipline OR Bachelor Degree in Law Engineering OR CA CFA CS Cost Accountant IT Stream BE BTech Any Branch OR MCA OR Masters in Computers IT Legal Stream LLB Degree\nAge Limit:Maximum 30 Years General Category\nAge Relaxation:OBC plus 3 Years SC ST plus 5 Years\nWhen:Once a Year Notification usually April or May\nWhy:High paying regulatory job strong work life balance postings mainly Mumbai financial sector exposure\nSelection Process:Phase 1 Online Screening Phase 2 Online Merit Exam Interview\nStage 1:Phase 1 Screening Exam Qualifying Only\nPaper 1 All Streams:General Awareness Financial Focus English Quant Reasoning 100 Marks 60 Minutes Minimum 30 Percent Required\nPaper 2 Stream Specific:General Stream Commerce Accountancy Management Finance Costing Companies Act Economics IT Legal Stream Subject Related Questions 100 Marks 40 Minutes Minimum 40 Percent Required\nOverall Phase 1 Rule:Aggregate 40 Percent Required Total 80 Marks out of 200\nNegative Marking:0.25 Marks Deducted\nStage 2:Phase 2 Merit Exam\nPaper 1 English Descriptive:Essay Precis Comprehension Typing 100 Marks 60 Minutes Weightage One Third\nPaper 2 Stream Specific Objective:Same Subjects as Phase 1 Higher Difficulty MCQs IT Stream includes Coding Test 100 Marks 40 Minutes Higher Duration for IT Weightage Two Third\nStage 3:Interview Weightage 15 Percent of Final Score\nFinal Merit:Based on Phase 2 Score plus Interview Phase 1 Marks Not Counted\nPreparation Focus:Strong command over core professional subjects more important than Quant Reasoning for final selection'),
('SIDBI Grade A & B', 'Type of Exam:Central Conducted by Small Industries Development Bank of India\nFor Which Posts:Assistant Manager Grade A entry level officer Manager Grade B mid level officer in MSME finance and development\nFor Whom:Grade A General Stream Bachelor or Master Degree in Commerce Economics Management Mathematics Statistics Engineering with 60 Percent 50 Percent SC ST OR Professional Qualification CA CS CFA CMA Grade B Same qualification with 2 to 5 Years relevant experience\nAge Limit:Grade A 21–30 Years Grade B 25–33 Years\nAge Relaxation:OBC plus 3 Years SC ST plus 5 Years\nWhen:Once a Year Notification usually mid or late year depending on cycle\nWhy:Specialized development bank job high salary urban postings strong exposure to MSME and finance sector\nSelection Process:Phase 1 Online Objective Screening Phase 2 Objective plus Descriptive Merit Interview\nStage 1:Phase 1 Screening Exam Qualifying Only\nEnglish Language:30 Questions 30 Marks\nReasoning Aptitude:25 Questions 25 Marks\nQuantitative Aptitude:25 Questions 25 Marks\nComputer Knowledge:20 Questions 20 Marks\nGeneral Awareness Banking Financial Social:20 Questions 20 Marks\nMSME and Finance Awareness:30 Questions 30 Marks\nStream Specific Test:50 Questions 50 Marks\nTotal Phase 1:200 Questions 200 Marks\nNegative Marking:0.25 Marks Deducted\nStage 2:Phase 2 Merit Exam\nPaper 1 English Descriptive:Essay Precis Comprehension Correspondence Typing 75 Marks 75 Minutes\nPaper 2 Professional Knowledge Objective:MSME Finance Regulations Banking Laws 50 Questions 75 Marks 60 Minutes\nPaper 2 Professional Knowledge Descriptive:Technical MSME Finance Questions 50 Marks 75 Minutes\nTotal Phase 2 Marks:200 Marks\nStage 3:Interview 100 Marks\nFinal Merit:Phase 2 Score plus Interview Total 300 Marks\nPreparation Focus:Strong understanding of MSME sector finance and banking regulations plus fast typing for descriptive answers'),
('LIC AAO', 'Type of Exam:Central Conducted by Life Insurance Corporation of India\nFor Which Posts:Assistant Administrative Officer Class I Officer Generalist and Specialist Streams\nStreams:Generalist Administration and Management Specialist IT Chartered Accountant Actuarial Legal Rajbhasha\nFor Whom:Generalist Bachelor Degree in any stream Specialist Specific professional or technical degree depending on post\nAge Limit:21–30 Years General Category\nAge Relaxation:OBC plus 3 Years SC ST plus 5 Years\nWhen:Irregular Recruitment based on vacancy cycles\nWhy:High paying officer job strong work life balance limited public dealing compared to bank jobs\nSelection Process:Prelims Objective Screening Mains Objective plus Descriptive Interview Medical Exam\nStage 1:Preliminary Exam Qualifying Only\nReasoning Ability:35 Questions 35 Marks 20 Minutes\nQuantitative Aptitude:35 Questions 35 Marks 20 Minutes\nEnglish Language:30 Questions 30 Marks 20 Minutes\nEnglish Rule:English marks not counted for merit only qualifying\nEffective Prelims Merit:Reasoning plus Quant 70 Marks\nNegative Marking:0.25 Marks Deducted\nStage 2:Mains Exam Merit Decider\nPart A Objective Test Total 300 Marks\nReasoning Ability:30 Questions 90 Marks 40 Minutes\nGeneral Knowledge and Current Affairs:30 Questions 60 Marks 20 Minutes\nData Analysis and Interpretation:30 Questions 90 Marks 40 Minutes\nInsurance and Financial Market Awareness:30 Questions 60 Marks 20 Minutes\nPart B Descriptive Test Letter and Essay Typing 25 Marks Qualifying Only\nSectional Cutoff:Must pass each section individually\nStage 3:Interview 60 Marks\nFinal Merit:Mains Objective 300 Marks plus Interview 60 Marks Total 360 Marks\nPreparation Focus:Strong command over insurance awareness and data interpretation speed important for mains'),
('LIC ADO', 'Type of Exam:Central Conducted by Life Insurance Corporation of India\nFor Which Posts:Apprentice Development Officer Sales and Marketing Management Role\nJob Nature:Recruit Train and Manage LIC Agents Field Work Performance Target Based\nJob Security:Subject to meeting premium targets during probation\nFor Whom:Open Market Fresh Graduates Agents Category Existing LIC Agents with 5 Years Experience Employee Category LIC Class III Employees with 3 Years Service\nAge Limit:21–30 Years General Category\nAge Relaxation:OBC plus 3 Years SC ST plus 5 Years\nFor Which Stream:Any Stream Arts Science Commerce\nWhen:Irregular Based on Zonal Office Requirements\nWhy:High Salary Career in Insurance Sales Management with Incentives\nSelection Process:Prelims Open Market Only Mains All Categories Interview Medical Exam\nStage 1:Preliminary Exam Qualifying Only Open Market Category\nReasoning Ability:35 Questions 35 Marks 20 Minutes\nNumerical Ability:35 Questions 35 Marks 20 Minutes\nEnglish Language:30 Questions 30 Marks 20 Minutes Qualifying Only\nEffective Prelims Merit:Reasoning plus Numerical 70 Marks\nStage 2:Mains Exam Merit Decider\nReasoning and Numerical Ability:50 Questions 50 Marks\nGeneral Knowledge Current Affairs and English:50 Questions 50 Marks\nInsurance and Financial Marketing Awareness:60 Questions 60 Marks\nTotal Mains Marks:160 Marks\nStage 3:Interview 40 Marks\nFinal Merit:Mains 160 Marks plus Interview 40 Marks Total 200 Marks\nPreparation Focus:Strong understanding of Insurance Products Sales Techniques Marketing Strategies and Financial Awareness Confidence and Communication Skills Critical'),
('LIC Assistant', 'Type of Exam:Central Conducted by Life Insurance Corporation of India\nFor Which Posts:Assistant Clerical Level Employee\nWork Profile:Cash Counter Work Single Window Operations Policy File Processing Customer Service\nPosting:Divisional or Branch Offices Transfers Mostly Within Division\nFor Whom:Indian Citizens with Bachelor Degree in any Stream\nAge Limit:18–30 Years General Category\nAge Relaxation:OBC plus 3 Years SC ST plus 5 Years\nWhen:Irregular Recruitment Based on Vacancy\nWhy:Stable Government Job High Salary for Clerical Post Strong Work Life Balance\nSelection Process:Prelims Screening Mains Merit Language Proficiency Test No Interview\nStage 1:Preliminary Exam Qualifying Only\nEnglish or Hindi Language:30 Questions 30 Marks 20 Minutes Qualifying Only\nNumerical Ability:35 Questions 35 Marks 20 Minutes\nReasoning Ability:35 Questions 35 Marks 20 Minutes\nEffective Prelims Merit:Numerical plus Reasoning 70 Marks\nNegative Marking:0.25 Marks Deducted\nStage 2:Mains Exam Merit Decider\nGeneral Financial Awareness:40 Questions 40 Marks\nGeneral English:40 Questions 40 Marks\nQuantitative Aptitude:40 Questions 40 Marks\nReasoning and Computer Aptitude:40 Questions 40 Marks\nHindi Language:40 Questions 40 Marks Hindi Zones Only\nTotal Mains Marks:200 Marks\nSectional Cutoff:Must Pass Each Section\nStage 3:Language Proficiency Test Mandatory\nFinal Merit:Mains Score Only 200 Marks\nPreparation Focus:Strong Accuracy in Quant and Reasoning Awareness of Insurance and Banking Terms Hindi Grammar Important for Hindi Speaking Zones'),
('NICL AO', 'Type of Exam:Central Conducted by National Insurance Company Ltd Government of India Undertaking\nFor Which Posts:Administrative Officer Scale I Generalist and Specialist\nStreams:Generalist Administration Claims Underwriting Specialist Doctors Legal Finance Actuarial IT Automobile Engineering\nFor Whom:Generalist Graduate or Postgraduate with 60 Percent Marks 55 Percent SC ST Specialist Relevant Professional Degree with 60 Percent Marks 55 Percent SC ST\nAge Limit:21–30 Years General Category\nAge Relaxation:OBC plus 3 Years SC ST plus 5 Years\nWhen:Irregular Based on Vacancies\nWhy:High Paying Public Sector Insurance Officer Job Strong Salary and Perks\nSelection Process:Phase I Prelims Screening Phase II Mains Objective plus Descriptive Phase III Interview\nStage 1:Preliminary Exam Qualifying Only\nEnglish Language:30 Questions 30 Marks 20 Minutes\nReasoning Ability:35 Questions 35 Marks 20 Minutes\nQuantitative Aptitude:35 Questions 35 Marks 20 Minutes\nTotal Prelims Marks:100 Marks\nNegative Marking:0.25 Marks Deducted\nStage 2:Mains Exam Merit Decider\nGeneralist Objective Test Total 250 Marks 3 Hours\nReasoning Ability:50 Questions 50 Marks\nEnglish Language:50 Questions 50 Marks\nGeneral Awareness:50 Questions 50 Marks\nComputer Knowledge:50 Questions 50 Marks\nQuantitative Aptitude:50 Questions 50 Marks\nDescriptive Test:Essay Precis Comprehension 30 Marks Qualifying Only\nSpecialist Objective Test Total 250 Marks\nReasoning:40 Questions 40 Marks\nEnglish:40 Questions 40 Marks\nGeneral Awareness:40 Questions 40 Marks\nComputer Knowledge:40 Questions 40 Marks\nQuantitative Aptitude:40 Questions 40 Marks\nSpecialist Stream Test:50 Questions 50 Marks\nDescriptive Test:30 Marks Qualifying Only\nStage 3:Interview\nFinal Selection Weightage:Mains Objective 80 Percent plus Interview 20 Percent\nPreparation Focus:Strong Insurance Awareness Concepts and Good Speed in Objective Sections Typing Practice for Descriptive Qualifying Test'),
('UIIC AO', 'Type of Exam: Central (Conducted by United India Insurance Company Ltd, a Public Sector Undertaking). For Which Posts: Administrative Officer (Scale I). Generalist: For general operations, underwriting, and claims management. Specialist: For experts in Legal, Accounts/Finance, Company Secretary, Actuaries, Doctors, Engineers (Civil/Automobile/Mechanical/E&C), and Agriculture. For Whom: Generalist: Graduate in any stream with 60% marks (55% for SC/ST). Specialist: Relevant Degree (B.E./B.Tech, LLB, CA, MBBS, etc.) with 60% marks. Age Limit: 21–30 years (General Category). Relaxation: OBC (+3 years), SC/ST (+5 years). When: Irregular. It depends on vacancies (e.g., 2016, 2024, 2025). Why: To get a \"Class I Officer\" job in a PSU General Insurance company. Key Benefit: Unlike other insurance exams (NICL/NIACL) that often have Prelims and Mains, UIIC AO usually conducts a Single Online Exam. This makes the recruitment process much faster. How (Stages): Single Online Exam: Objective + Descriptive Test. Interview. Exam Pattern & Marks Breakdown Stage 1: Single Online Examination (The \"Do or Die\" Day) Since there is no Prelims, this single exam decides your fate. Format: Online (CBT) - 2 Hours 30 Minutes. Type: Objective Test (Multiple Choice) + Descriptive Test. A. Objective Test (Merit Section - 250 Marks) For Generalists: Reasoning: 50 Q | 50 Marks. English Language: 50 Q | 60 Marks (Higher Weightage). Quantitative Aptitude: 40 Q | 50 Marks. General Awareness (with Financial Sector): 40 Q | 50 Marks. Computer Knowledge: 20 Q | 40 Marks (2 marks per question!). Total: 200 Questions | 250 Marks. For Specialists: The structure is similar, but Quantitative Aptitude and General Awareness questions are reduced to make space for a Professional Knowledge section (Technical questions from your branch) carrying high marks. B. Descriptive Test (Qualifying Only) Task: Letter Writing (10 Marks) & Essay Writing (20 Marks). Time: 30 Minutes (Typing on Computer). Score: 30 Marks. Note: '),
('GIC Assistant Manager', 'Type of Exam:Central Conducted by General Insurance Corporation of India GIC Re\nFor Which Posts:Assistant Manager Scale I Desk Job in Reinsurance Risk Assessment Underwriting International Business\nStreams:General Stream Any Graduate Specialist Streams Finance IT Legal Insurance Actuarial and Others\nFor Whom:General Stream Graduate with 60 Percent Marks 55 Percent SC ST Specialist Stream Relevant Degree with 60 Percent Marks\nAge Limit:21–30 Years General Category\nAge Relaxation:OBC plus 3 Years SC ST plus 5 Years\nWhen:Irregular Recruitment Based on Vacancies\nWhy:High Salary Officer Job in National Reinsurer Mostly Mumbai Posting Strong Work Life Balance\nSelection Process:Online Written Exam Objective plus Descriptive Group Discussion Interview\nStage 1:Online Written Exam Total 150 Marks 150 Minutes\nPart A General Stream Higher Order Reasoning Critical Thinking 40 Questions 40 Marks\nPart A Specialist Stream Professional Knowledge 40 Questions 40 Marks\nPart B Objective Test Common for All 80 Marks\nReasoning Ability:20 Questions 20 Marks\nEnglish Language:25 Questions 25 Marks\nGeneral Awareness:20 Questions 20 Marks\nNumerical Ability and Computer Literacy:15 Questions 15 Marks\nPart C Descriptive Test Essay Precis Comprehension 30 Marks Typing on Computer Marks Counted in Merit\nStage 2:Group Discussion and Interview\nFinal Selection Weightage:Written Exam plus GD plus Interview\nFinal Merit Total:200 Marks 150 Written plus 50 GD Interview\nPreparation Focus:Critical Reasoning Practice for General Stream Strong Professional Knowledge for Specialists Good Essay and Precis Writing Skills Important'),
('NIACL AO', 'Type of Exam:Central Conducted by The New India Assurance Company Ltd\nFor Which Posts:Administrative Officer Scale I Generalist and Specialist\nStreams:Generalist Claims Underwriting Administration Specialist Risk Engineering Automobile Legal Accounts Health IT\nFor Whom:Generalist Graduate or Postgraduate with 60 Percent Marks 55 Percent SC ST PwBD Specialist Relevant Professional Degree with 60 Percent Marks\nAge Limit:21–30 Years General Category\nAge Relaxation:OBC plus 3 Years SC ST plus 5 Years\nWhen:Irregular Recruitment Based on Vacancies\nWhy:High Paying Public Sector Insurance Officer Job Strong Salary Perks and Job Security\nBond Requirement:Minimum 4 Years Service Bond Including Probation\nSelection Process:Phase I Prelims Screening Phase II Mains Objective plus Descriptive Phase III Interview\nStage 1:Preliminary Exam Qualifying Only\nEnglish Language:30 Questions 30 Marks 20 Minutes\nReasoning Ability:35 Questions 35 Marks 20 Minutes\nQuantitative Aptitude:35 Questions 35 Marks 20 Minutes\nTotal Prelims Marks:100 Marks\nNegative Marking:0.25 Marks Deducted\nStage 2:Mains Exam Merit Decider\nGeneralist Objective Test Total 200 Marks\nReasoning Ability:50 Questions 50 Marks\nEnglish Language:50 Questions 50 Marks\nGeneral Awareness:50 Questions 50 Marks\nQuantitative Aptitude:50 Questions 50 Marks\nSpecialist Objective Test Total 200 Marks\nReasoning Ability:40 Questions 40 Marks\nEnglish Language:40 Questions 40 Marks\nGeneral Awareness:40 Questions 40 Marks\nQuantitative Aptitude:40 Questions 40 Marks\nProfessional Knowledge:40 Questions 40 Marks\nDescriptive Test Letter Writing Essay Writing 30 Marks Qualifying Only\nStage 3:Interview\nFinal Selection Weightage:Mains Objective 75 Percent plus Interview 25 Percent\nPreparation Focus:Insurance Awareness for GA Strong Basics in Quant and Reasoning Specialist Candidates Focus on Technical Subject Descriptive Only Needs Basic Passing Level'),
('India Post GDS', 'Type of Exam:No Written Exam Selection Based on 10th Marks\nRecruiting Body:Department of Posts Ministry of Communications Government of India\nFor Which Posts:Branch Postmaster BPM Assistant Branch Postmaster ABPM Dak Sevak\nWork Profile:BPM Branch Management Banking IPPB Accounts ABPM Stamp Sales Delivery Assistance Dak Sevak Mail Delivery and Packing\nFor Whom:10th Pass Candidates with Passing Marks in Mathematics and English\nLanguage Requirement:Must Have Studied Local Language up to 10th Standard\nAge Limit:18–40 Years General Category\nAge Relaxation:OBC plus 3 Years SC ST plus 5 Years\nFor Which Stream:Any Stream 10th Level\nWhen:Twice a Year Typically January February and July August\nRecent Update:Large Vacancy Cycle Released 2026\nWhy:Easiest Government Affiliated Job Without Written Exam Suitable for Rural Candidates\nSelection Process:Online Application Automated Merit List Based on 10th Percentage Document Verification Medical and Police Verification\nMerit Rule:Highest Percentage Holder for Each Post Office Vacancy Gets Selected\nCutoff Trend:General OBC Often 95 Percent to 100 Percent\nSalary Structure:Time Related Continuity Allowance TRCA Not Regular Pay Scale\nBPM Salary Range:12000 to 29380 Approx Starting In Hand 15000 to 17000\nABPM Dak Sevak Salary Range:10000 to 24470 Approx Starting In Hand 13000 to 14000\nOther Requirements:Basic Computer Knowledge Cycling Skill Required Self Declaration Accepted in Some Cases\nPreparation Advice:High 10th Marks Critical Computer Certificate Helpful Apply in Home Region for Better Chances'),
('FCI Manager', 'Type of Exam:Central Conducted by Food Corporation of India\nFor Which Posts:Manager General Depot Movement Accounts Technical Civil Electrical Mechanical Engineering Hindi\nWork Profile:Food Grain Procurement Storage Quality Control Logistics Administration\nFor Whom:General Depot Movement Graduate with 60 Percent Marks 55 Percent SC ST PH Accounts BCom plus MBA Finance CA CS CMA Technical BSc Agriculture or BE BTech Food Science Food Tech BioTech Engineers Degree in Civil Electrical Mechanical Engineering\nAge Limit:28 Years General Category Hindi Manager Up to 35 Years\nAge Relaxation:OBC plus 3 Years SC ST plus 5 Years\nWhen:Irregular Recruitment Based on Vacancies\nWhy:Class II Gazetted Officer Level PSU Job High Salary Housing and Medical Benefits\nSelection Process:Phase I Screening Phase II Merit Interview Training\nTraining Period:6 Months as Management Trainee before Confirmation\nStage 1:Phase I Preliminary Exam Qualifying Only\nEnglish Language:25 Questions 25 Marks 15 Minutes\nReasoning Ability:25 Questions 25 Marks 15 Minutes\nNumerical Aptitude:25 Questions 25 Marks 15 Minutes\nGeneral Studies:25 Questions 25 Marks 15 Minutes\nTotal Prelims Marks:100 Marks\nNegative Marking:0.25 Marks Deducted\nStage 2:Phase II Mains Exam Merit Decider\nManager General Depot Movement Paper I Only\nEnglish:45 Questions\nReasoning:45 Questions\nNumerical Aptitude:45 Questions\nGeneral Studies Computer Awareness Management Ethics Agriculture Economy:45 Questions\nTotal:120 Questions 120 Marks 90 Minutes\nManager Accounts Technical Engineering\nPaper I Same as Above 120 Marks\nPaper II Subject Specific 60 Questions 120 Marks 60 Minutes\nStage 3:Interview\nFinal Selection Weightage:Phase II Written 90 Percent plus Interview 10 Percent\nPreparation Focus:Strong Quant and Reasoning for General Stream Strong Technical Subject Knowledge for Specialist Streams Good Awareness of Agriculture Economy and Management Concepts'),
('FCI JE', 'TypeofExam:CentralConductedbyFoodCorporationofIndia\nForWhichPosts:JuniorEngineerCivilElectricalMechanical\nJECivil:MaintenanceandConstructionofFCIGodownsSilosOfficeBuildings\nJEElectricalMechanical:MaintenanceofElectricalSystemsWeighbridgesConveyorsinDepots\nForWhom:\nOptionADegreeHolders:BEBTechinCivilElectricalMechanicalNoExperienceRequired\nOptionBDiplomaHolders:DiplomainCivilElectricalMechanicalplus1YearExperience\nAgeLimit:18to28YearsGeneralCategory\nAgeRelaxation:OBCplus3YearsSCSTplus5Years\nWhen:IrregularBasedonVacancies\nWhy:PSUJobwithHighSalaryComparedtoOtherJEPosts\nSalaryScale:34000to103400\nStartingGrossSalary:Approx55000to60000perMonth\nSelectionProcess:Phase1ScreeningPhase2MeritDocumentVerification\nInterview:NotConductedforJE\nStage1:Phase1OnlineScreeningExamQualifyingOnly\nEnglishLanguage:25Questions25Marks15Minutes\nReasoningAbility:25Questions25Marks15Minutes\nNumericalAptitude:25Questions25Marks15Minutes\nGeneralStudies:25Questions25Marks15Minutes\nSubjects:HistoryGeographyEconomyGeneralScienceClass8LevelplusCurrentAffairs\nTotalMarks:100\nNegativeMarking:0.25MarksDeducted\nStage2:Phase2TechnicalMeritExam\nPaperIGeneralAptitude\nTime:90Minutes\nEnglish:25Questions\nReasoning:25Questions\nNumericalAptitude:25Questions\nGeneralStudiesClass10LevelplusComputerAwareness:45Questions\nTotalPaperIMarks:120\nPaperIITechnicalSubject\nTime:60Minutes\nBranchSpecificEngineeringQuestionsCivilorElectricalorMechanical\nTotalQuestions:60\nMarksperQuestion:2\nTotalPaperIIMarks:120\nFinalMeritCalculation:PaperIplusPaperIITotal240Marks\nPreparationFocus:StrongTechnicalSubjectKnowledgeisCriticalPaperIICarriesHighWeightageReviseCoreEngineeringSubjectsThoroughlyAlongwithBasicAptitudeandGeneralStudies'),
('ESIC UDC', 'TypeofExam:CentralConductedbyEmployeesStateInsuranceCorporationStatutoryBodyunderMinistryofLabourandEmployment\nForWhichPosts:UpperDivisionClerkUDC\nRole:PureDeskJobDraftingLettersMaintainingFilesProcessingOnlineDataHandlingAccountsinESICOfficesHospitals\nForWhom:IndianCitizenswithBachelorsDegreeinAnyStream\nComputerSkill:WorkingKnowledgeofComputerOperationsOfficeSuitesDatabasesRequired\nAgeLimit:18to27YearsGeneralCategory\nAgeRelaxation:OBCplus3YearsSCSTplus5YearsPwBDplus10Years\nWhen:IrregularBasedonVacancies\nWhy:RelaxedGovernmentJobFixed9to5Schedule5DayWorkWeekMostlyUrbanPostings\nSalary:PayLevel4CentralGovtPayScaleStartingGrossSalaryApprox42000to45000perMonth'),
('ESIC MTS', 'Type of Exam: Central (Conducted by the Employees\' State Insurance Corporation).\nFor Which Posts: Multi-Tasking Staff (MTS).\nWork Profile: Group C non-technical office support job.\nDuties Include: Maintaining files, photocopying, dispatching mail, opening/closing rooms, assisting UDCs/Officers.\nJob Level: Peon/Office Assistant level.\nEligibility: Indian citizens who are 10th Pass (Matriculation) from a recognized board.\nNote: No higher degree or experience required.\nAge Limit (General): 18–25 years.\nAge Relaxation: OBC +3 years, SC/ST +5 years.\nNote: Stricter than UDC exam (UDC allows up to 27 years).\nExam Frequency: Irregular, usually along with UDC recruitment (like 2022, expected 2025/26).\nWhy This Job: Low Entry Barrier – One of the few central government jobs after 10th.\nWork-Life Balance – Fixed 9-to-5 job with weekends off.\nSalary – Pay Level-1, approx ₹24,000–₹28,000/month depending on city.\nSelection Stages: Phase I – Preliminary Exam (Screening).\nSelection Stages: Phase II – Mains Exam (Final Merit).\nBonus: No Interview and No Computer Skill Test.\nPhase I Mode: Online (CBT).\nPhase I Duration: 60 Minutes.\nGeneral Intelligence & Reasoning: 25 Questions | 50 Marks.\nGeneral Awareness: 25 Questions | 50 Marks.\nQuantitative Aptitude: 25 Questions | 50 Marks.\nEnglish Comprehension: 25 Questions | 50 Marks.\nPhase I Total: 100 Questions | 200 Marks.\nSelection Ratio: 1:10 (10 candidates shortlisted per seat).\nPhase II Mode: Online (CBT).\nPhase II Duration: 120 Minutes.\nGeneral Intelligence & Reasoning: 50 Questions | 50 Marks.\nGeneral Awareness: 50 Questions | 50 Marks.\nQuantitative Aptitude: 50 Questions | 50 Marks.\nEnglish Comprehension: 50 Questions | 50 Marks.\nPhase II Total: 200 Questions | 200 Marks.\nNegative Marking: 0.25 marks deducted per wrong answer.\nDifficulty Level: Very easy, 10th standard level, easier than Bank Clerk or SSC CHSL.\nFinal Merit: Based only on Mains score (200 Marks).\nCutoff Warning: General category often 160–170+ marks due to easy pape');
INSERT INTO `exams` (`exam_name`, `detail`) VALUES
('ESIC SSO', 'Type of Exam: Central (Conducted by the Employees\' State Insurance Corporation).\nFor Which Posts: Social Security Officer (SSO) / Manager Gr. II / Superintendent.\nThe Power Profile: Inspector-level job with authority to inspect factories and companies for ESI and labor law compliance.\nDuties Include: Checking account books, verifying employee records, ensuring payment of ESI dues.\nEligibility: Indian citizens with a Bachelor’s Degree in any stream.\nPreference: Commerce, Law, or Management graduates preferred (others can apply).\nComputer Skill: Working knowledge of computers (MS Office & databases) is mandatory.\nAge Limit (General): 21–27 years.\nAge Relaxation: OBC +3 years, SC/ST +5 years.\nExam Frequency: Irregular, conducted when vacancies arise (e.g., 2018, 2022).\nWhy This Job: High Salary – Pay Level-7 with starting gross approx ₹75,000–₹80,000/month.\nAuthority: Field inspection powers unlike desk-based bank jobs.\nSelection Stages: Phase I – Prelims (Qualifying).\nSelection Stages: Phase II – Mains (Final Merit).\nSelection Stages: Phase III – Computer Skill Test + Descriptive English (Qualifying).\nPhase I Mode: Online (CBT) with sectional timing.\nPhase I Duration: 60 Minutes.\nEnglish Language: 30 Questions | 30 Marks | 20 Minutes.\nReasoning Ability: 35 Questions | 35 Marks | 20 Minutes.\nQuantitative Aptitude: 35 Questions | 35 Marks | 20 Minutes.\nPhase I Total: 100 Questions | 100 Marks.\nNegative Marking: 0.25 marks deducted per wrong answer.\nPhase II Mode: Online (CBT).\nPhase II Duration: 2 Hours.\nReasoning / Intelligence: 40 Questions | 60 Marks | 35 Minutes.\nGeneral/Economy/Financial/Insurance Awareness: 40 Questions | 40 Marks | 20 Minutes.\nEnglish Language: 30 Questions | 40 Marks | 30 Minutes.\nQuantitative Aptitude: 40 Questions | 60 Marks | 35 Minutes.\nPhase II Total: 150 Questions | 200 Marks.\nUnique Feature: Reasoning and Quant carry 1.5 marks per question (high-scoring areas).\nPhase III Nature: Qualifying only, marks not added to merit.\nComputer Skill Te'),
('DRDO CEPTAM', 'Type of Exam: Central (Conducted by the Centre for Personnel Talent Management under DRDO).\nFor Which Posts: Senior Technical Assistant-B (STA-B), Technician-A (Tech-A), Admin & Allied (A&A).\nSTA-B Role: Group B officer-level technical job assisting scientists in research and development.\nTech-A Role: Group C technical support with hands-on machinery and lab work.\nAdmin & Allied Role: Non-technical posts like Clerk, Store Assistant, Fireman, Driver (separate notification).\nEligibility for STA-B: Diploma in Engineering (Mechanical, Electrical, E&C, Computer, etc.) OR B.Sc (Physics, Chemistry, Maths, etc.).\nStrict Rule: B.Tech/B.E. holders are NOT eligible for STA-B.\nEligibility for Tech-A: 10th Class + ITI Certificate in relevant trade (Fitter, Electrician, COPA, Welder, etc.).\nEligibility for Admin & Allied: 10th / 12th / Graduation depending on post.\nAge Limit (General): 18–28 years.\nAge Relaxation: OBC +3 years, SC/ST +5 years.\nExam Frequency: Irregular, CEPTAM cycles (CEPTAM-10, CEPTAM-11, etc.), usually every 1–2 years (Expected 2025/26).\nWhy This Job: Opportunity to work in India’s premier Defence Research organization.\nSalary (STA-B): Approx ₹50,000–₹55,000/month.\nPerks: CSD Canteen facility, DRDO township quarters.\nBonus: No Interview for STA-B or Tech-A.\nSTA-B Selection Stage 1: Tier 1 Screening Test (Qualifying Only).\nTier 1 Mode: Online (CBT).\nTier 1 Duration: 90 Minutes.\nTier 1 Subjects: Quantitative Aptitude, General Intelligence & Reasoning, General Awareness, English Language, General Science.\nTier 1 Total: 120 Questions | 120 Marks.\nTier 1 Rule: Marks not added to final merit, only qualifying.\nSTA-B Selection Stage 2: Tier 2 Selection Test (Final Merit).\nTier 2 Mode: Online (CBT).\nTier 2 Duration: 90 Minutes.\nTier 2 Syllabus: Subject-specific (Engineering or Science discipline).\nTier 2 Total: 100 Questions | 100 Marks.\nSTA-B Final Merit: Based 100% on Tier 2 marks.\nTech-A Selection Stage 1: Written Test (Main Exam).\nTech-A Tier 1 Mode: Online (CBT).\nT'),
('ISRO Scientist/Engineer Exam', 'Type of Exam: Central (Conducted by ISRO Centralised Recruitment Board – ICRB).\nFor Which Posts: Scientist/Engineer ‘SC’.\nStatus: Group ‘A’ Gazetted Officer post (Entry Level Scientist).\nMain Streams: Electronics, Mechanical, Computer Science.\nOther Streams: Civil, Electrical, Architecture (released separately and less frequently).\nEligibility: Indian citizens with B.E./B.Tech degree in First Class.\nStrict Marks Rule: Minimum 65% aggregate or 6.84 CGPA mandatory (no relaxation).\nAge Limit (General): 28 years.\nAge Relaxation: OBC +3 years, SC/ST +5 years.\nExam Frequency: Irregular, usually once a year or once in 1–1.5 years depending on mission needs.\nWhy This Job: Opportunity to work on rockets (PSLV/GSLV) and missions like Chandrayaan and Gaganyaan.\nPay Level: Level 10 (similar starting basic pay as IAS/IPS).\nExtra Benefits: Performance Related Incentive Scheme (PRIS) and high social prestige.\nSelection Stages: Written Test + Interview.\nPattern Update: Written test marks are now counted in final selection.\nWritten Test Mode: Online (CBT).\nWritten Test Duration: 120 Minutes.\nPaper Structure: Single paper with Part A and Part B.\nPart A Type: Discipline-specific technical questions.\nPart A Questions: 80.\nPart A Marks: 80 Marks (+1 correct, -0.33 wrong).\nPart A Syllabus: Based on GATE syllabus of respective branch.\nPart A Nature: More theoretical, less calculation-heavy, calculators usually not allowed.\nPart B Type: Aptitude section.\nPart B Questions: 15.\nPart B Marks: 20 Marks (usually no negative marking).\nPart B Syllabus: Numerical, Logical, and Diagrammatic Reasoning.\nWritten Test Total: 100 Marks (Scaled).\nPart-wise Qualifying Rule: Minimum 50% in Part A and 50% in Part B separately (General category).\nInterview Stage: Personal Interview.\nInterview Call Ratio: 1:5 based on written test performance.\nInterview Marks: 100 Marks.\nInterview Qualifying Rule: Minimum 50/100 required, otherwise disqualified.\nFinal Weightage: 50% Written Test + 50% Interview.\nImportant Cha'),
('AFCAT', 'Type of Exam: Central (Conducted by the Indian Air Force).\nFor Which Posts: Commissioned Officer (Group A) in the Indian Air Force.\nFlying Branch: Pilots (fighter, transport, helicopter).\nGround Duty (Technical): Aeronautical Engineers (Electronics/Mechanical) maintaining aircraft and systems.\nGround Duty (Non-Technical): Administration, Logistics, Accounts, Education, Weapon Systems.\nEligibility Flying Branch: Graduate (3 years) in any stream with 60% + Physics & Maths in 12th with 50% each OR B.E./B.Tech with 60%.\nEligibility Ground Duty Technical: B.E./B.Tech in relevant engineering fields with 60% + 50% in Physics & Maths in 12th.\nEligibility Ground Duty Non-Technical Admin/Logistics: Graduate in any stream with 60%.\nEligibility Ground Duty Non-Technical Accounts: B.Com with 60%.\nAge Limit Flying Branch: 20–24 years.\nAge Limit Ground Duty: 20–26 years.\nAge Relaxation: No age relaxation for SC/ST/OBC in AFCAT.\nExam Frequency: Conducted twice a year (February and August), notifications in December and June.\nWhy Join: Elite lifestyle, adventure, high respect, starting CTC approx ₹18–20 Lakhs per year.\nSelection Stages: Written Exam + AFSB Interview + Medical Examination.\nWritten Exam Name: AFCAT Online Test.\nTechnical Note: Engineering Knowledge Test (EKT) discontinued; engineers also give only AFCAT paper.\nWritten Exam Mode: Online (CBT).\nWritten Exam Duration: 2 Hours.\nGeneral Awareness Topics: History, Geography, Sports, Defence, Current Affairs.\nEnglish Section: Comprehension, Error Detection, Vocabulary.\nNumerical Ability Level: Basic math (Decimals, Fractions, Profit & Loss, Simple Interest).\nReasoning & Military Aptitude: Verbal reasoning + Non-verbal (spatial ability, pattern matching).\nWritten Exam Total: 100 Questions | 300 Marks.\nMarking Scheme Correct: +3 Marks.\nMarking Scheme Wrong: -1 Mark.\nTypical Cutoff: Around 150–160 out of 300.\nStage 2 Name: AFSB (Air Force Selection Board) Interview.\nAFSB Centers: Dehradun, Mysore, Gandhinagar, Varanasi, Guwahat'),
('Indian Navy Entrance Test (INET)', 'Status Update: The earlier INET for Officers (written exam) has been discontinued since COVID-19.\nCurrent Officer Recruitment Mode: Direct Entry (Shortlisting based on marks/JEE rank) or through UPSC exams (NDA/CDS).\nActive Use of INET Name: Now refers to Sailor Entry (Agniveer) Computer-Based Test.\nOfficer Entry Type: Direct Shortlisting (No Written Exam).\nOfficer Posts: Short Service Commission (SSC) Officers.\nExecutive Branches: General Service, Pilot, Observer, ATC, Logistics, Naval Armament.\nTechnical Branches: Engineering (General), Electrical (General), Naval Architecture.\nEducation Branch: Education Officer.\nOfficer Eligibility: Unmarried Indian citizens.\nOfficer Qualification: B.E./B.Tech in relevant streams with minimum 60% marks.\nFinal Year Eligibility: Final year students can apply.\nOfficer Age Limit: 19–24 years (varies slightly by branch).\nOfficer Notification Cycle: Twice a year (Jan/Feb and July/Aug).\nOfficer Rank on Joining: Sub Lieutenant (Class-I Gazetted Officer).\nOfficer Selection Stage 1: Shortlisting based on B.E./B.Tech percentage or JEE Mains rank (for 10+2 Cadet Entry).\nOfficer Selection Stage 2: 5-Day SSB Interview.\nSSB Centers: Bangalore, Bhopal, Kolkata, Visakhapatnam.\nOfficer Selection Stage 3: Medical Examination.\nOfficer Final Merit: Based entirely on SSB marks.\nAgniveer Entry Type: Central Computer-Based Test (INET).\nAgniveer SSR Role: Technical sailors working on ships and submarines (radars, missiles, engines).\nAgniveer MR Role: Chef, Steward, Hygienist.\nAgniveer SSR Qualification: 10+2 with Physics, Maths and one of Chemistry/Biology/Computer Science.\nAgniveer MR Qualification: 10th Pass.\nAgniveer Age Limit: 17.5–21 years.\nAgniveer Recruitment Cycle: Twice a year.\nAgniveer Selection Stage 1: INET Online CBT.\nAgniveer Selection Stage 2: Physical Fitness Test + Offline Written Exam + Medical Exam.\nINET SSR Exam Mode: Online (CBT).\nINET SSR Exam Duration: 60 Minutes.\nINET SSR English: 25 Questions.\nINET SSR Science: 25 Questions.\nINE'),
('Indian Coast Guard Navik', 'Type of Exam: Central (Conducted by the Indian Coast Guard, Ministry of Defence).\nFor Which Posts: Navik (General Duty), Navik (Domestic Branch), Yantrik.\nNavik GD Role: Sailor on ships handling navigation, weapons, and sensors.\nNavik DB Role: Logistics support such as Cook and Steward.\nYantrik Role: Technical maintenance of engines, electrical systems, and electronics.\nEligibility Navik GD: 10+2 with Maths and Physics from a recognized board.\nEligibility Navik DB: 10th Pass.\nEligibility Yantrik: 10th Pass + Diploma in Electrical/Mechanical/Electronics Engineering.\nAge Limit (General): 18–22 years.\nAge Relaxation: OBC +3 years, SC/ST +5 years.\nExam Frequency: Twice a year for batches starting Jan/Feb and Jul/Aug.\nNotification Months: Usually September and January.\nWhy Join: Opportunity to serve in a uniformed armed force.\nService Type: Permanent job with pension, medical, and CSD canteen benefits.\nSelection Stages: Stage I Written Exam, Stage II PFT + Document Verification, Stage III Medicals at INS Chilka, Stage IV Final Merit List.\nWritten Exam Importance: Final merit based only on written exam marks.\nNegative Marking: No negative marking in written exam.\nNavik DB Exam Sections: Section I only.\nSection I Subjects: Maths 20, Science 10, English 15, Reasoning 10, GK 5.\nSection I Total: 60 Questions | 60 Marks | 45 Minutes.\nSection I Level: Class 10 syllabus.\nSafe Score DB: Around 50+ marks for General category.\nNavik GD Exam Sections: Section I + Section II in one sitting.\nSection II Subjects: Maths 25, Physics 25.\nSection II Total: 50 Questions | 50 Marks | 30 Minutes.\nSection II Level: Class 12 technical syllabus.\nNavik GD Grand Total: 110 Marks.\nYantrik Exam Sections: Section I + Technical Section (III/IV/V as per diploma branch).\nYantrik Technical Section: 50 Questions from diploma engineering stream.\nYantrik Grand Total: 110 Marks.\nStage II Test: Physical Fitness Test (Qualifying only).\nPFT Run: 1.6 km in 7 minutes.\nPFT Squat-ups: 20.\nPFT Push-ups: 10.\nPhysical'),
('Indian Coast Guard Yantrik', 'ype of Exam: Central (Conducted by the Indian Coast Guard, Ministry of Defence).\nPost: Yantrik (Mechanical / Electrical / Electronics).\nService Status: Permanent Government Job with pension benefits, not under Agnipath scheme.\nEntry Rank: Yantrik (equivalent to Petty Officer rank in Navy, higher than Navik).\nRole Mechanical: Maintain and operate ship engines and propulsion systems.\nRole Electrical: Maintain ship power generation and electrical systems.\nRole Electronics: Maintain radars, sensors, and communication equipment.\nEligibility Education: 10th Pass + Diploma in Mechanical/Electrical/Electronics/Telecommunication Engineering (3 or 4 years, AICTE approved).\nEligibility Note: 12th pass alone is not eligible without a Diploma.\nAge Limit (General): 18–22 years.\nAge Relaxation: OBC +3 years, SC/ST +5 years.\nExam Frequency: Twice a year, batches usually start in February and August.\nWhy Join: Permanent defence career with long-term job security.\nBasic Pay: Pay Level-5, Basic ₹29,200.\nYantrik Allowance: Additional ₹6,200 per month special pay.\nStarting Gross Salary: Approx ₹45,000–₹50,000 per month.\nSelection Stage I: Computer-Based Written Exam (Section I + Technical Section).\nSelection Stage II: Physical Fitness Test + Document Verification.\nSelection Stage III: Final Medical Examination at INS Chilka.\nWritten Exam Total Duration: 75 Minutes.\nNegative Marking: No negative marking, attempt all questions.\nSection I Type: General Ability Section.\nSection I Duration: 45 Minutes.\nSection I Syllabus Level: Class 10 standard.\nSection I Maths: 20 Questions.\nSection I Science: 10 Questions.\nSection I English: 15 Questions.\nSection I Reasoning: 10 Questions.\nSection I GK: 5 Questions.\nSection I Passing Marks: 30 for General/OBC/EWS.\nTechnical Section Name: Section III/IV/V (based on diploma branch).\nTechnical Section Duration: 30 Minutes.\nTechnical Section Questions: 50 Questions from diploma engineering syllabus.\nTechnical Section Passing Marks: 20 for General/OBC/EWS.\nWri'),
('Territorial Army Officer Exam', 'Type of Exam: Central (Conducted by the Territorial Army Directorate, Indian Army).\nPost: Lieutenant (Commissioned Officer).\nService Type: Part-time Army service for employed civilians.\nService Model: Mandatory 2 months training/service per year, remaining time in civilian job.\nWartime Role: Can be embodied for full-time duty during national emergency or war.\nEligibility Civilian: Must be gainfully employed in a job, business, or professional practice.\nEligibility Ex-Servicemen: Former Commissioned Officers of Armed Forces.\nEmployment Rule: Unemployed candidates are not eligible.\nAge Limit: 18–42 years.\nUnique Age Advantage: Only Army officer entry allowing candidates up to 42 years.\nEducation Requirement: Graduate in any discipline from recognized university.\nExam Frequency: Twice a year (generally July and December).\nExam Mode: Computer-Based Test (CBT).\nWhy Join: Opportunity to serve as an Army Officer without leaving civilian career.\nRank on Commission: Lieutenant.\nService Benefits: Same rank, pay, and privileges as Regular Army officers during embodied service.\nAdditional Benefits: CSD canteen and medical facilities during training/service period.\nStage 1 Name: Online Entrance Exam (CBT).\nExam Structure: Two papers conducted in two sessions on the same day.\nPaper 1 Subjects: Reasoning and Elementary Mathematics.\nReasoning Questions: 50 | 50 Marks.\nMathematics Questions: 50 | 50 Marks.\nMaths Syllabus Level: 10th standard (Arithmetic, Algebra, Geometry, Mensuration, Unitary Method).\nPaper 2 Subjects: General Knowledge and English.\nGK Questions: 50 | 50 Marks.\nEnglish Questions: 50 | 50 Marks.\nTotal Exam: 200 Questions | 200 Marks | 4 Hours total duration.\nNegative Marking: 0.33 marks deducted for each wrong answer.\nMinimum Marks Rule: 40% required in each section separately.\nAggregate Rule: Minimum 50% overall (100/200).\nStage 2: Service Selection Board (SSB) Interview.\nSSB Duration: 5 Days.\nSSB Process: Screening, Psychology Tests, GTO Tasks, Personal Interview.'),
('Agniveer (Army/Navy/Air Force)', 'Type of Service: 4-Year Tour of Duty under Agnipath Scheme.\nEntry Rank: Agniveer in Army, Navy, or Air Force.\nService Duration: 4 years total.\nPermanent Selection Rule: Only top 25% retained in regular cadre after 4 years.\nExit for Others: 75% released with financial package and skill certificate.\nAge Limit: 17.5–21 years.\nMarital Status: Unmarried candidates (females eligible in Navy and selected roles).\n1st Year Salary: ₹30,000 per month (approx ₹21,000 in hand).\n4th Year Salary: ₹40,000 per month (approx ₹28,000 in hand).\nSeva Nidhi Package: Approx ₹11.71 lakh tax-free after 4 years.\nIndian Army Roles: GD, Technical, Clerk/Store Keeper, Tradesmen.\nArmy GD Eligibility: 10th pass with 45% aggregate and 33% in each subject.\nArmy Technical Eligibility: 12th pass with PCM and English, 50% marks.\nArmy Clerk Eligibility: 12th pass with 60% aggregate and 50% in English and Math/Accounts.\nArmy Tradesman Eligibility: 8th or 10th pass depending on trade.\nArmy Selection Step 1: Online Common Entrance Exam (CEE).\nArmy Selection Step 2: Physical Fitness Test including run, pull-ups, ditch, balance.\nArmy Selection Step 3: Medical Examination.\nAir Force Streams: Science and Other Than Science.\nAir Force Science Eligibility: 10+2 with Physics, Math, English (50%) or 3-year Diploma.\nAir Force Non-Science Eligibility: 10+2 any stream with 50% marks and 50% in English.\nAir Force Phase I Science Test: English, Physics, Math (60 mins).\nAir Force Phase I Other Test: English, Reasoning, General Awareness (45 mins).\nAir Force Combined Test: English, Physics, Math, RAGA (85 mins).\nAir Force Phase II: Physical Fitness Test and Adaptability Test-II.\nAir Force PFT: 1.6 km run, push-ups, sit-ups, squats.\nIndian Navy Posts: SSR and MR.\nNavy SSR Eligibility: 10+2 with Math, Physics and one science subject.\nNavy MR Eligibility: 10th pass.\nNavy Stage I: INET computer-based test.\nNavy INET Subjects: English, Science, Math, General Awareness.\nNavy Stage II: Physical Fitness Test and medical checks.'),
('UPSC Geo-Scientist Exam', 'Type of Exam: Central (Conducted by the Union Public Service Commission).\nPosts: Group A and Group B Scientist posts under Ministry of Mines and Ministry of Jal Shakti.\nGeologist Role: Geological Survey of India work in mapping, mineral exploration, and surveys.\nGeophysicist Role: Work in GSI or CGWB using gravity, magnetic, and seismic methods.\nChemist Role: Lab analysis of rocks, minerals, and water samples in GSI or CGWB.\nScientist B Hydrogeology Role: Groundwater exploration and management in CGWB.\nMinimum Qualification: Master’s Degree (M.Sc or M.Tech) in relevant stream.\nGeologist Qualification: Master’s in Geology, Applied Geology, Marine Geology, or Mineral Exploration.\nGeophysicist Qualification: Master’s in Physics, Applied Physics, Geophysics, or Marine Geophysics.\nChemist Qualification: Master’s in Chemistry, Applied Chemistry, or Analytical Chemistry.\nHydrogeology Qualification: Master’s in Geology, Applied Geology, or Marine Geology.\nAge Limit: 21–32 years.\nAge Relaxation: OBC +3 years, SC/ST +5 years.\nExam Frequency: Once a year with notification around September.\nPrestige Factor: One of the top technical government jobs for science postgraduates.\nPay Level: Level 10 Class I Gazetted Officer.\nJob Nature: Mix of fieldwork in remote areas and advanced laboratory research.\nSelection Stages: Preliminary Exam, Mains Exam, Interview.\nPrelims Nature: Objective computer-based test with marks counted in final merit.\nPrelims Paper I: General Studies including current affairs, science, geography, polity, economy.\nPrelims Paper I Marks: 100 Marks in 2 hours.\nPrelims Paper II: Stream-specific technical subject questions.\nPrelims Paper II Marks: 300 Marks in 2 hours.\nPrelims Total: 400 Marks.\nPrelims Negative Marking: One third marks deducted per wrong answer.\nMains Nature: Descriptive written examination.\nMains Structure: Three subject papers related to chosen stream.\nMains Marks: 200 Marks per paper, total 600 Marks.\nMains Duration: 3 hours per paper over 2 days.'),
('State PSC Civil Services Exams', 'Type of Exam: State Level conducted by respective State Public Service Commissions like GPSC, UPPSC, MPSC.\nPosts: Class 1 and Class 2 Officers in State Administration.\nClass 1 Examples: Deputy Collector (SDM), Deputy Superintendent of Police (DySP), District Registrar.\nClass 2 Examples: Mamlatdar (Tehsildar), Section Officer (SO), Taluka Development Officer (TDO).\nMinimum Qualification: Bachelor’s Degree in any stream from a recognized university.\nDomicile Rule: Candidates from other states can apply but usually without reservation benefits.\nLanguage Requirement: Knowledge of the local state language is generally mandatory.\nAge Limit: Higher than UPSC, commonly around 20–35 years for General category.\nAge Relaxation: Many states allow up to 40 years for reserved categories or women.\nExam Frequency: Irregular, though some PSCs like GPSC and UPPSC have become more consistent recently.\nMajor Advantage: Posting usually within the same state.\nAuthority Level: Officers like SDM and DySP hold strong district or taluka-level administrative power.\nSelection Stages: Preliminary Exam, Mains Exam, Interview.\nPrelims Nature: Objective screening test with MCQs.\nPrelims Papers: Usually two papers.\nPrelims Paper 1 Focus: General Studies including History, Polity, Geography, Economy.\nState Focus in Prelims: Around 30–40% questions related to specific state history, geography, and culture.\nPrelims Paper 2: CSAT or Aptitude including Math and Reasoning, usually qualifying only.\nPrelims Marks Rule: Not counted in final merit list.\nMains Nature: Descriptive written examination.\nLanguage Paper English: Essay, letter, and comprehension type questions.\nLanguage Paper Local: Descriptive paper in state language, sometimes counted for merit.\nGeneral Studies Papers in Mains: History, Geography, Polity, Economy, Ethics, and State-specific topics.\nState Focus in Mains: Detailed questions on state schemes, history, and local governance.\nOptional Subject Trend: Many states have removed optional su'),
('State Forest Service Exams', 'Type of Exam: State Level conducted by State Public Service Commissions such as GPSC, MPSC, UPPSC.\nPosts: Assistant Conservator of Forests (ACF) and Range Forest Officer (RFO).\nACF Rank: Class 1 Gazetted Officer and sub-divisional head of forest department.\nRFO Rank: Class 2 Gazetted Officer in charge of a forest range.\nRFO Authority: Uniformed officer with field control and sometimes armed authority in sensitive zones.\nMinimum Qualification: Science or Engineering graduates only.\nEligible Degrees Science: B.Sc in Botany, Zoology, Chemistry, Physics, Maths, Geology, Forestry, Environment.\nEligible Degrees Engineering: B.E or B.Tech in any branch.\nEligible Degree Veterinary: B.V.Sc.\nNot Eligible: Arts, Commerce, and Law graduates.\nAge Limit: Around 20–35 or 36 years depending on state rules.\nJob Appeal: Uniformed forest service with outdoor field life.\nLegal Powers: Authority to arrest, raid, and investigate forest and wildlife crimes.\nPerks: Government vehicle, forest quarters, and disciplined service lifestyle.\nSelection Stages: Prelims, Mains, Physical Walking Test, Interview.\nPhysical Test Name: Walking Test for endurance.\nMale Walking Standard: 25 km walk within 4 hours.\nFemale Walking Standard: Around 14–16 km walk within 4 hours depending on state.\nPhysical Rule: Failure in walking test leads to disqualification regardless of written score.\nPrelims Nature: Objective type screening exam often common with State Civil Services.\nPrelims Subjects: History, Polity, Geography, Economy, Science, Maths, Current Affairs.\nPrelims Cutoff Trend: Separate and often lower cutoff for Forest candidates due to science-only eligibility.\nMains Nature: Descriptive written examination.\nMains Language Paper 1: State language (e.g., Gujarati) around 150 marks.\nMains Language Paper 2: English around 150 marks.\nMains GS Paper 1: History and Culture.\nMains GS Paper 2: Polity and Economy.\nMains GS Paper 3: Science, Environment, and Forestry-focused topics.\nOptional Subject Trend: Some st'),
('State Engineering Service Exams', 'Type of Exam: State Level conducted by State Public Service Commissions such as GPSC, MPSC, UPPSC.\nPost: Assistant Engineer (AE) Class 2 Gazetted Officer.\nPrimary Role: Technical head at Taluka or Sub-Division level supervising public works.\nProject Types: Roads, bridges, canals, irrigation systems, and water supply projects.\nAuthority Power: Responsible for quality checks and approval of contractor bills.\nPromotion Path: Assistant Engineer to Executive Engineer to Superintending Engineer.\nRequired Qualification: B.E. or B.Tech degree in relevant engineering branch.\nEligible Branch Civil: Civil Engineering with highest number of vacancies.\nEligible Branch Mechanical: Mechanical Engineering mainly in irrigation or public works departments.\nEligible Branch Electrical: Electrical Engineering mainly in power or water supply departments.\nDiploma Rule: Diploma holders are not eligible for AE and must apply for Junior Engineer posts.\nAge Limit: Around 20–35 or 36 years depending on state rules.\nJob Advantage: Posting generally within home state.\nPower Aspect: Direct responsibility over infrastructure quality and execution.\nPay Level: Usually Level 9 or Level 10 under state pay structure.\nStarting Salary: Approximately ₹55,000 to ₹65,000 per month.\nSelection Stages: Written Examination and Interview.\nGPSC Written Format: Objective MCQ based exam conducted in one or two days.\nWritten Part 1: General Studies for 100 marks.\nGS Subjects: History, Geography, Polity of state and India, Reasoning, Current Affairs.\nWritten Part 2: Technical Subject for 200 marks from engineering branch.\nDifficulty Level: Easier than GATE or IES but requires high speed and accuracy.\nWritten Total Marks: 300 marks.\nNegative Marking: Usually one third marks deducted per wrong answer.\nInterview Marks: 100 marks.\nFinal Merit Formula: Written 300 plus Interview 100 equals 400 marks.\nInterview Focus: Technical concepts, engineering drawings, IS Codes, and local infrastructure projects.\nMPSC Pattern: Separ'),
('State Police SI Exams', 'Type of Exam: State Level conducted by State Police Recruitment Boards or SSC for Delhi Police.\nPost: Sub-Inspector (SI).\nUniform Rank: Two stars on shoulder.\nPrimary Role: Investigating Officer handling crime scenes, charge sheets, and arrests.\nStation Role: May act as Station House Officer in smaller police stations.\nMinimum Qualification: Graduate in any stream.\nAge Limit General: Usually 21–35 years depending on state.\nGujarat Age Limit: 21–35 years.\nDelhi CPO Age Limit: 20–25 years.\nJob Appeal: Uniformed officer role with authority and public interaction.\nSelection Stages: Physical Test, Written Exam, Medical Examination.\nPhysical Test Type: Running plus height and chest measurement.\nGujarat PSI Physical Rule: Only qualifying, no extra marks for faster time.\nGujarat Male Run: 5 km in 25 minutes.\nGujarat Female Run: 1.6 km in 9 minutes 30 seconds.\nGujarat Written Paper 1: Objective exam for 200 marks.\nPaper 1 Part A: Reasoning and Data Interpretation 50 marks plus Quantitative Aptitude 50 marks.\nPaper 1 Part B: Constitution, History, Geography, Science, Current Affairs for 100 marks.\nGujarat Syllabus Change: Law subjects like IPC and CrPC removed from written exam.\nGujarat Written Paper 2: Descriptive language paper in Gujarati and English for 100 marks.\nGujarat Final Merit: Based on 300 marks from both written papers.\nUP Police SI Written Subjects: Hindi, Law and Constitution and GK, Math, Reasoning each 100 marks.\nUP Law Focus: IPC, CrPC, Women Protection Acts, Traffic Rules.\nUP Male Run: 4.8 km in 28 minutes.\nUP Female Run: 2.4 km in 16 minutes.\nDelhi Police SI Exam Body: Conducted by SSC as CPO exam.\nDelhi Paper 1 Subjects: Math, Reasoning, GK, English for 200 marks.\nDelhi Physical Test: High jump, long jump, and 1.6 km run in 6.5 minutes.\nDelhi Paper 2: English language paper for 200 marks.\nHeight Requirement Male: Around 165 cm in Gujarat and 170 cm in Delhi or UP.\nHeight Requirement Female: Around 158 cm in Gujarat and 157 cm in Delhi.\nChest Requirement M'),
('State Police Constable Exams', 'Universal Eligibility Education: 12th Pass is required in most state police constable recruitments.\nEligibility Exception: Few older or special recruitments accepted 10th pass but now rare.\nUniversal Age Limit: Generally 18 to 25 years for General category.\nAge Relaxation: OBC, SC, ST usually get 3 to 5 years relaxation.\nPhysical Standard Purpose: Body measurements checked before written exam.\nMale Safe Height: Around 168 to 170 cm fits most states.\nGujarat Male Height: Minimum 165 cm.\nUP or MP or Delhi Male Height: Around 168 to 170 cm.\nFemale Safe Height: Around 157 to 158 cm in most states.\nMale Chest Standard: Around 80 cm unexpanded and 85 cm expanded.\nChest Expansion Rule: Minimum 5 cm expansion required.\nPhysical Endurance Test Type: Running test in every state police exam.\nMale Running Target: Prepare for about 5 km in 24 to 25 minutes.\nFemale Running Target: Prepare for 1.6 km in about 8.5 to 9.5 minutes.\nWritten Exam Core Subjects: Reasoning, Maths, and General Knowledge form major portion.\nReasoning Topics: Coding decoding, number series, blood relations, direction sense.\nMaths Level: Basic 10th standard arithmetic topics.\nMaths Topics: Percentage, average, ratio, profit and loss.\nGK Focus Area: Indian Constitution, History, and Geography.\nMedical Vision Rule: Good eyesight required, usually 6/6 in better eye.\nColor Blindness Rule: Color blindness leads to rejection in police recruitment.\nOrthopedic Check: Candidates checked for knock knees and flat foot.\nState Difference Factor: Each state adds its own local GK and language section.\nGujarat Local Focus: Gujarat history, culture, and Gujarati language.\nUP Local Focus: Uttar Pradesh GK and Hindi language.\nMaharashtra Local Focus: Marathi language and state knowledge.'),
('State SSC/SSSB Exams', 'Identity: State Subordinate Services Selection Board Exams such as GSSSB, UPSSSC, DSSSB.\nExam Level: State Level recruitment for Group C non gazetted posts.\nPost Category: Clerical, Revenue, and other support level government jobs.\nClerical Posts: Junior Clerk, Senior Clerk, Office Assistant, Head Clerk.\nRevenue Posts: Talati, Patwari, Lekhpal.\nOther Posts: Gram Sevak, Forest Guard, Bin Sachivalaya Clerk.\nMinimum Qualification: Usually graduate in any stream for clerical posts.\nLower Qualification Posts: Some field posts may allow 12th pass.\nComputer Requirement: CCC computer certificate generally mandatory.\nAge Limit Range: Usually 20 to 35 years for general category.\nJob Nature: Fixed hour desk job in government offices.\nOffice Posting: Collector office, Sachivalaya, Taluka or district offices.\nPay Level Range: Level 2 to Level 5 with starting salary around 26000 to 40000 per month.\nGSSSB System Change: Gujarat merged many separate exams into one Combined Competitive Exam.\nGSSSB Stage 1: Preliminary exam used only for screening.\nGSSSB Prelims Mode: Online CBT for 60 minutes.\nGSSSB Prelims Reasoning: 40 marks highest weightage.\nGSSSB Prelims Maths: 30 marks.\nGSSSB Prelims English: 15 marks.\nGSSSB Prelims Gujarati: 15 marks.\nGSSSB Prelims Total: 100 questions for 100 marks.\nGSSSB Prelims Merit Rule: Marks not counted in final merit.\nGSSSB Group A Posts: Higher clerical posts like Head Clerk and Senior Clerk.\nGSSSB Group A Exam Type: Descriptive written exam.\nGSSSB Group A Gujarati Paper: 100 marks descriptive.\nGSSSB Group A English Paper: 100 marks descriptive.\nGSSSB Group A GS Paper: 150 marks.\nGSSSB Group A Skill Need: Essay, letter and report writing ability.\nGSSSB Group B Posts: Entry level clerical posts like Junior Clerk.\nGSSSB Group B Exam Type: Objective MCQ exam.\nGSSSB Group B English: 20 marks.\nGSSSB Group B Gujarati: 20 marks.\nGSSSB Group B Polity and RTI: 30 marks.\nGSSSB Group B History Geography Culture: 30 marks.\nGSSSB Group B Economy Science: 30 marks'),
('State TET Exams', 'Type of Exam: State Level Eligibility Test for teaching jobs.\nExam Nature: Not a direct recruitment exam but a qualifying eligibility license.\nPurpose: Required to apply for Vidhyasahayak or Shikshan Sahayak teacher posts.\nTET 1 Post Level: Primary Teacher for Standards 1 to 5.\nTET 2 Post Level: Upper Primary Teacher for Standards 6 to 8.\nTAT Secondary Level: High School Teacher for Standards 9 and 10.\nTAT Higher Secondary Level: Teacher for Standards 11 and 12.\nTET 1 Qualification: 12th pass plus PTC or D.El.Ed.\nTET 2 Qualification: Graduate with B.Ed or PTC.\nTAT Qualification: Graduate or Post Graduate with B.Ed.\nCertificate Validity: Lifetime validity once qualified.\nGeneral Qualifying Marks: 60 percent or 90 out of 150.\nReserved Qualifying Marks: 55 percent or 82 out of 150.\nGujarat TET Exam Type: Objective MCQ single stage exam.\nGujarat TET 1 Total Marks: 150 marks in 90 minutes.\nTET 1 CDP: 30 marks from Child Development and Pedagogy.\nTET 1 Language 1: Gujarati for 30 marks.\nTET 1 Language 2: English for 30 marks.\nTET 1 Mathematics: 30 marks.\nTET 1 EVS: 30 marks.\nGujarat TET 2 Total Marks: 150 marks in 120 minutes.\nTET 2 General Part: 75 marks from CDP, languages, and GK.\nTET 2 Subject Part: 75 marks from chosen teaching subject.\nTET 2 Streams: Maths Science, Social Science, or Language teachers.\nGujarat TAT Pattern: Two tier exam with Prelims and Mains.\nTAT Prelims Nature: Objective screening exam.\nTAT Prelims General Studies: 100 marks from reasoning, teaching aptitude, GK.\nTAT Prelims Subject Paper: 100 marks from chosen subject.\nTAT Prelims Negative Marking: 0.25 marks per wrong answer.\nTAT Prelims Rule: Minimum qualifying cutoff needed to enter Mains.\nTAT Mains Nature: Descriptive written exam.\nTAT Mains Paper 1: Language paper of 100 marks in Gujarati or English or Hindi.\nTAT Mains Paper 2: 100 marks from subject content and teaching pedagogy.\nTAT Mains Focus: Writing lesson methods and teaching approach for topics.\nOther State TET Pattern: Most states f'),
('KVS Recruitment Exam', 'Type of Exam: Central exam conducted by Kendriya Vidyalaya Sangathan under Ministry of Education.\nPosts: Teaching and Non Teaching staff in central government schools.\nPRT Role: Primary Teacher for classes 1 to 5.\nTGT Role: Trained Graduate Teacher for classes 6 to 10 in specific subjects.\nPGT Role: Post Graduate Teacher for classes 11 and 12 in specific subjects.\nNon Teaching Posts: Librarian, Junior Secretariat Assistant, Senior Secretariat Assistant.\nPRT Qualification: 12th with 50 percent plus D.El.Ed or JBT and CTET Paper 1 pass.\nPRT Rule Update: B.Ed candidates not eligible for PRT as per Supreme Court order.\nTGT Qualification: Bachelor degree with 50 percent plus B.Ed and CTET Paper 2 pass.\nPGT Qualification: Master degree with 50 percent plus B.Ed and CTET not required.\nPRT Age Limit: Maximum 30 years for general category.\nTGT Age Limit: Maximum 35 years for general category.\nPGT Age Limit: Maximum 40 years for general category.\nWomen Age Relaxation: All women get 10 year age relaxation for teaching posts.\nExam Frequency: Recruitment occurs irregularly usually every 2 to 4 years.\nSalary Benefit: Higher salary than most state teaching jobs.\nPRT Starting Salary: Around 55000 per month.\nPGT Starting Salary: Around 70000 per month.\nSchool Advantage: Central schools with better facilities and all India transfer policy.\nSelection Stage 1: Online computer based written exam.\nSelection Stage 2: Demo Teaching and Interview for teaching posts.\nSkill Test Stage: Typing test required for clerical posts like JSA.\nPRT Exam Duration: 180 minutes.\nPRT Total Marks: 180 marks.\nPRT Language Section: Hindi 10 and English 10 marks.\nPRT General Awareness Section: GK 10, Reasoning 5, Computer 5.\nPRT Pedagogy Section: Perspectives on Education and Child Development for 60 marks.\nPRT Subject Section: 80 marks from Hindi, English, Maths, and EVS at NCERT level.\nTGT and PGT Exam Duration: 180 minutes.\nTGT and PGT Total Marks: 180 marks.\nTGT and PGT Language Section: Hindi 10 and Engli'),
('NVS Recruitment Exam', 'Type of Exam: Central recruitment conducted by Navodaya Vidyalaya Samiti under Ministry of Education.\nPosts: Teaching and non teaching staff for Jawahar Navodaya Vidyalayas.\nSchool System: Fully residential schools for talented rural students.\nPGT Role: Post Graduate Teacher for classes 11 and 12.\nTGT Role: Trained Graduate Teacher for classes 6 to 10.\nNon Teaching Posts: Junior Secretariat Assistant, Lab Attendant, Mess Helper, Catering Assistant.\nPRT Note: NVS generally does not recruit Primary Teachers as schools start from class 6.\nTGT Qualification: Bachelor degree with 50 percent plus B.Ed and CTET Paper 2 pass.\nPGT Qualification: Master degree with 50 percent plus B.Ed and CTET not required.\nJSA Qualification: 12th pass with typing speed of 30 wpm in English or 25 wpm in Hindi.\nLab Attendant Qualification: 10th pass with lab certificate or 12th with science.\nTGT Age Limit: Maximum 35 years.\nPGT Age Limit: Maximum 40 years.\nWomen Relaxation: Female candidates get 10 year age relaxation for teaching posts.\nAccommodation Benefit: Free residential quarters provided on campus.\nFood Benefit: Meals are subsidized in residential school campus.\nSalary Level TGT: Around 65000 plus per month gross.\nSalary Level PGT: Around 75000 plus per month gross.\nSavings Advantage: Rural residential posting leads to higher savings.\nExam Mode Teaching: Online computer based test of 180 minutes.\nNegative Marking Rule: One fourth mark deducted for each wrong answer.\nGeneral Section Marks: Around 40 to 50 marks from awareness, reasoning, ICT and teaching aptitude.\nSubject Section Marks: 80 marks from subject specific content.\nLanguage Section TGT: 30 marks qualifying from English, Hindi and regional language.\nLanguage Section PGT: 20 marks qualifying from English and Hindi.\nLanguage Rule: Minimum 40 percent required in each language separately.\nLanguage Warning: Failure in language section leads to disqualification even with high subject score.\nJSA Exam Subjects: Reasoning, quantitative'),
('JEE Main', 'Identity: JEE Main national level engineering entrance exam.\nConducting Body: National Testing Agency.\nPurpose: Admission to NITs, IIITs, and other centrally funded technical institutes.\nSecondary Purpose: Screening exam for JEE Advanced for IIT admissions.\nEligibility Stream: Students must have studied Physics, Chemistry, and Mathematics in Class 12.\nAttempt Limit: Students can attempt for three consecutive years after Class 12.\nExample Eligibility: Students passing in 2024, 2025, or appearing in 2026 can attempt the 2026 exam.\nAge Limit: No official age limit but limited by three year attempt rule.\nExam Frequency: Conducted twice a year.\nSession Months: Usually January and April sessions.\nScore Policy: Best percentile from two sessions considered for ranking.\nMain Benefit: Entry into top government engineering colleges.\nInstitute Advantage: Strong placements, infrastructure, and national brand value.\nExam Mode: Computer based test of three hours.\nSubjects: Physics, Chemistry, and Mathematics.\nTotal Questions: 75 questions overall.\nTotal Marks: 300 marks.\nSection A Per Subject: 20 multiple choice questions.\nSection A Marking: Four marks for correct and minus one for wrong answer.\nSection B Per Subject: 5 numerical value questions.\nSection B Answer Type: Student types the numerical answer on screen.\nSection B Marking: Four marks for correct and minus one for wrong answer.\nBoard Percentage Rule Purpose: Required for admission but not for writing exam.\nExam Eligibility Rule: Only passing Class 12 is required to appear.\nAdmission Rule General Category: Minimum 75 percent in Class 12 or top 20 percentile of board.\nAdmission Rule SC ST: Minimum 65 percent in Class 12.\nPaper 2A Purpose: For Bachelor of Architecture admissions.\nPaper 2A Sections: Mathematics, Aptitude, and Drawing test.\nPaper 2B Purpose: For Bachelor of Planning admissions.\nPaper 2B Sections: Mathematics, Aptitude, and Planning based questions.\nResult Format: Scores declared in percentile form called NTA s'),
('JEE Advanced', 'Identity: JEE Advanced national level entrance exam for IIT admissions.\nConducting Body: Organized each year by one of the IITs under the Joint Admission Board.\nPurpose: Admission into 23 Indian Institutes of Technology.\nDream Factor: Only gateway to IIT Bombay, IIT Delhi, IIT Madras and other IITs.\nOther Accepting Institutes: IISc Bangalore, IISERs, IIST, and RGIPT also use scores.\nEligibility Path: Cannot apply directly and must first qualify JEE Main.\nMain Cutoff Rule: Only top 2.5 lakh rank holders of JEE Main can appear.\nAttempt Limit: Maximum two attempts in two consecutive years.\nYear Rule Example: If passed Class 12 in 2024 you can attempt in 2024 and 2025 only.\nExam Frequency: Conducted once every year.\nExam Months: Usually held in May or June.\nPrestige Value: IIT tag is globally recognized for academic excellence.\nPattern Nature: No fixed pattern and marking scheme changes every year.\nPaper Structure: Two compulsory papers conducted on the same day.\nPaper Timing: Paper 1 in morning and Paper 2 in afternoon.\nSubjects in Both Papers: Physics, Chemistry, and Mathematics.\nTotal Marks Variation: Total marks change each year usually between 300 and 360 or more.\nCompulsory Rule: Both papers must be attempted or result is cancelled.\nSingle Correct MCQ: One correct option with positive and negative marking.\nMultiple Correct MCQ: More than one correct option with partial marking scheme.\nPartial Marking Concept: Selecting some correct options gives partial marks but wrong choice causes negative marks.\nInteger Type Questions: Numerical answer type sometimes without negative marking.\nMatrix Match Type: Matching type questions between two columns.\nEligibility JEE Main Rule: Must be among top 2.5 lakh candidates in JEE Main.\nAge Limit Rule: Candidate must be born on or after a specified date with relaxation for reserved categories.\nClass 12 Marks Rule: Minimum 75 percent aggregate or top 20 percentile of board required.\nReserved Category Marks Rule: Minimum 65 percent fo'),
('BITSAT', 'Type of Exam: University level entrance exam conducted by BITS Pilani.\nInstitute Status: Private deemed university but considered highly prestigious and comparable to top IITs.\nPurpose: Admission to various programs at BITS campuses.\nEngineering Programs: B.E. courses like Computer Science, Mechanical, Electrical, Chemical and others.\nPharmacy Program: B.Pharm course for Biology or Mathematics students.\nIntegrated M.Sc. Program: Dual degree pathway where students join M.Sc. first and later get a B.E. degree based on CGPA.\nDual Degree Advantage: Many students enter M.Sc. Physics or Maths to later secure Computer Science as second degree.\nYear of Passing Rule: Eligible only in the year of passing Class 12 or the immediately following year.\nExample Rule: A student passing 12th in 2025 can attempt BITSAT in 2025 and 2026 only.\nSubject Requirement: Must have studied Physics, Chemistry and Mathematics in Class 12.\nBiology Option: PCB students eligible for B.Pharm program.\nAge Limit Concept: No fixed age limit but effectively limited by passing year rule.\nExam Frequency: Conducted twice each year.\nSession Months: Usually May and June sessions.\nScore Policy: Best score out of two attempts considered for admission.\nReservation Policy: No reservation system and admission is purely merit based.\nBoard Topper Benefit: State or central board rank 1 students get direct admission without BITSAT.\nExam Mode: Computer based test of 3 hours duration.\nTotal Questions: 130 questions in the main exam.\nTotal Marks: 390 marks before bonus questions.\nCorrect Answer Marking: Plus 3 marks for each correct answer.\nWrong Answer Marking: Minus 1 mark for each incorrect answer.\nPhysics Section: 30 questions for 90 marks.\nChemistry Section: 30 questions for 90 marks.\nEnglish Proficiency Section: 10 questions for 30 marks.\nLogical Reasoning Section: 20 questions for 60 marks.\nMathematics Section: 40 questions for 120 marks.\nBonus Question Feature: Option to attempt 12 extra questions after finishing'),
('VITEEE', 'Type of Exam: University level entrance exam conducted by Vellore Institute of Technology.\nPurpose: Admission to B.Tech programs at VIT campuses.\nMain Campus: VIT Vellore is the most prestigious campus.\nSecond Campus: VIT Chennai is the next preferred option.\nOther Campuses: VIT AP Amaravati and VIT Bhopal are newer campuses.\nMinimum Qualification: 12th pass with Physics, Chemistry, and Mathematics or Biology.\nMarks Requirement: Minimum 60 percent aggregate in PCM or PCB in Class 12.\nRelaxation Rule: 50 percent required for SC, ST, and North Eastern state candidates.\nAge Limit Rule: Candidate must be born on or after a specified date usually limiting age to around 21 years.\nExample Age Rule: For 2026 exam candidate must be born on or after 1 July 2004.\nExam Frequency: Conducted once every year.\nExam Month: Usually held in April.\nMajor Advantage: No negative marking in the exam.\nPlacement Reputation: VIT Vellore known for large placement drives and top company visits.\nExam Mode: Computer based test.\nExam Duration: 2 hours 30 minutes.\nTotal Questions: 125 questions.\nTotal Marks: 125 marks.\nCorrect Answer Marking: One mark awarded for each correct answer.\nWrong Answer Marking: No negative marks for incorrect answers.\nMathematics or Biology Section: 40 questions.\nPhysics Section: 35 questions.\nChemistry Section: 35 questions.\nAptitude Section: 10 questions.\nEnglish Section: 5 questions.\nSeat Category System: Fee structure depends on rank based categories from 1 to 5.\nCategory 1 Meaning: Lowest tuition fee for top rank holders.\nHigher Categories Meaning: Fees increase from Category 2 to Category 5.\nCategory 5 Meaning: Highest tuition fee for lower ranks.\nFee Variation Example: Same branch can have different fees depending on category.\nSpeed Strategy: About one minute per question so quick solving required.\nAttempt Strategy: Attempt all questions since there is no negative marking.\nEasy Scoring Area: English and Aptitude sections provide easy marks.\nTop Rank Target: Under'),
('SRMJEEE', 'Identity: SRMJEEE university level engineering entrance exam.\nConducting Body: SRM Institute of Science and Technology.\nPurpose: Admission to B.Tech programs in SRM campuses.\nMain Campus: SRM Kattankulathur in Chennai is the flagship campus.\nOther Chennai Campuses: SRM Ramapuram and Vadapalani.\nNorth India Campus: SRM Ghaziabad in Delhi NCR region.\nHaryana Campus: SRM Sonepat is a newer campus.\nOther Campuses: SRM AP Amaravati and SRM Trichy.\nMinimum Qualification: 12th pass with Physics, Chemistry, and Mathematics or Biology.\nMarks Requirement: Minimum 60 percent aggregate in PCM or PCB in Class 12.\nAge Requirement: Candidate must be at least 16 years and 6 months old by July 31 of exam year.\nExam Frequency: Conducted in three phases each year.\nPhase Months: Usually April, June, and July.\nBest Score Rule: Highest score among attempts is considered for admission.\nExam Purpose Advantage: Easier alternative compared to JEE Main.\nSeat Availability: Large intake allows average rank students to secure CSE.\nExam Mode: Online remote proctored or center based depending on policy.\nExam Duration: 2 hours 30 minutes.\nTotal Questions: 125 questions.\nTotal Marks: 125 marks.\nCorrect Answer Marking: One mark awarded for correct answer.\nWrong Answer Marking: No negative marking for wrong answer.\nPhysics Section: 35 questions.\nChemistry Section: 35 questions.\nMathematics or Biology Section: 40 questions.\nEnglish Section: 5 questions.\nAptitude Section: 10 questions.\nMain Campus Demand: Kattankulathur campus has highest demand.\nCSE Rank Target: Usually under 10000 rank required for CSE in main campus.\nOther Branch Rank Range: ECE and Mechanical possible up to around 30000 rank.\nFee Range: Tuition fees roughly 3 to 4.5 lakh per year for CSE.\nFee Structure: Generally fixed high fees unlike category based system in VIT.\nScholarship Benefit: Top rankers can receive up to 100 percent tuition fee waiver.\nDifficulty Level: Easier to moderate compared to VITEEE.\nSpeed Requirement: Same pace a');
INSERT INTO `exams` (`exam_name`, `detail`) VALUES
('MET (Manipal Entrance Test)', 'Identity: MET Manipal Entrance Test university level engineering exam.\nConducting Body: Manipal Academy of Higher Education.\nPurpose: Admission to B.Tech programs in Manipal campuses.\nMain Campus: MIT Manipal is the flagship and most reputed campus.\nBengaluru Campus: MIT Bengaluru is a newer campus gaining popularity due to location.\nJaipur Campus: Manipal University Jaipur known for large modern infrastructure.\nSikkim Campus: SMIT Sikkim located in Himalayan region.\nMinimum Qualification: 12th pass with Physics, Mathematics, and English as compulsory subjects.\nMarks Requirement: Minimum 50 percent aggregate in Physics, Mathematics, and one optional subject.\nEligibility Advantage: Lower board percentage requirement compared to exams like BITSAT.\nExam Phases: Conducted in two phases.\nPhase Months: Usually April and May.\nBest Score Rule: Best score out of two attempts used for ranking.\nCampus Life Benefit: MIT Manipal known for strong campus culture and facilities.\nPlacement Strength: Main campus placements comparable to older NITs.\nExam Mode: Computer based test.\nExam Duration: 2 hours.\nTotal Questions: 60 questions.\nTotal Marks: 240 marks.\nMathematics Section: 20 questions including MCQ and NAT.\nPhysics Section: 15 questions including MCQ and NAT.\nChemistry Section: 15 questions including MCQ and NAT.\nEnglish Section: 10 MCQ questions.\nMCQ Marking: Plus 4 marks for correct and minus 1 mark for wrong answer.\nNAT Marking: Plus 4 marks for correct and no negative for wrong answer.\nNAT Strategy: Attempt all numerical questions since there is no penalty.\nMain Campus CSE Rank: Usually requires rank under 2000.\nCSE Specialization Rank: Around 3500 rank for AI or ML branches.\nECE Rank Range: Around 6000 to 8000 for main campus.\nMechanical Rank Range: Up to around 20000 for main campus.\nJaipur or Bengaluru CSE Rank: Possible with ranks around 10000 to 15000 or higher.\nDifficulty Level: Harder than VITEEE but easier than JEE Main.\nNegative Marking Presence: MET includes negat'),
('GATE', 'Identity: GATE Graduate Aptitude Test in Engineering national level exam.\nConducting Body: Jointly conducted by IISc Bangalore and seven IITs.\nPurpose Higher Studies: Admission to M.Tech, M.E., and Ph.D. programs in IITs, NITs, and IIITs.\nStipend Benefit: M.Tech students through GATE receive monthly stipend around 12400 rupees.\nPSU Purpose: Used for direct recruitment in Public Sector Undertakings as Class 1 officers.\nTop PSUs: ONGC, IOCL, NTPC, GAIL, BHEL and similar companies recruit via GATE.\nForeign Use: Some foreign universities accept GATE score for masters admissions.\nEligible Year Students: Third year students can appear in GATE.\nEligible Graduates: Final year students and graduates are eligible.\nEligible Degrees: B.E., B.Tech, B.Arch, B.Sc Research, and M.Sc.\nAge Limit Rule: No age limit for appearing in GATE.\nExam Frequency: Conducted once every year.\nExam Timing: Usually held during first two weekends of February.\nCareer Benefit PSU: PSU jobs offer very high starting salary packages for engineers.\nCareer Benefit M.Tech: IIT M.Tech provides access to high level research and R&D roles.\nExam Mode: Computer based test of three hours duration.\nTotal Questions: 65 questions in the paper.\nTotal Marks: 100 marks overall.\nScore Validity: GATE score valid for three years for higher studies.\nPSU Validity Rule: Most PSUs consider only current year GATE score.\nGeneral Aptitude Section: 15 marks common for all branches.\nEngineering Mathematics Section: Around 13 marks depending on branch.\nCore Technical Section: Around 72 marks from candidate’s main discipline.\nMCQ Question Type: Single correct option with negative marking.\nMCQ Negative Marking 1 Mark: One third mark deducted for wrong answer.\nMCQ Negative Marking 2 Mark: Two third mark deducted for wrong answer.\nMSQ Question Type: Multiple correct options with no negative marking.\nMSQ Rule: Marks awarded only if all correct options selected.\nNAT Question Type: Numerical answer type with no negative marking.\nMarks Mean'),
('NATA', 'Identity: NATA National Aptitude Test in Architecture.\nConducting Body: Council of Architecture.\nPurpose: Admission to five year Bachelor of Architecture degree course.\nProfessional Rule: B.Arch degree required to legally practice as architect in India.\nScore Acceptance: Accepted by most architecture colleges except IITs, NITs, and IIITs.\nAlternative Exam for IITs: IIT and NIT architecture admissions use JEE Main Paper 2 instead.\nMinimum Qualification Path 1: 12th pass with Physics and Mathematics plus one optional subject.\nMinimum Qualification Path 2: 10 plus 3 diploma with Mathematics.\nBoard Marks Requirement: Minimum 50 percent aggregate in 10 plus 2.\nExam Schedule: Conducted on weekends from April to July.\nAttempt Flexibility: Multiple attempts allowed and best score considered.\nPurpose Advantage: Required for admission to top state architecture colleges.\nSkill Focus: Exam emphasizes creativity and visual skills over rote learning.\nExam Mode: Hybrid exam with offline and online parts.\nTotal Duration: Three hours.\nTotal Marks: 200 marks.\nNegative Marking Rule: No negative marking in the exam.\nPart A Mode: Offline drawing and composition test.\nPart A Duration: 90 minutes.\nPart A Marks: 80 marks across three drawing questions.\nDrawing Task Type 1: Color composition scene drawing.\nDrawing Task Type 2: Black and white perspective sketching.\nDrawing Task Type 3: Three dimensional composition using shapes.\nPart B Mode: Online computer based aptitude test.\nPart B Duration: 90 minutes.\nPart B Marks: 120 marks from 45 questions.\nVisual Reasoning Section: Questions on 2D and 3D shapes and visual puzzles.\nGeneral Knowledge Section: Questions on famous buildings, architects, materials and logos.\nMathematics Section: Basic geometry and arithmetic of 10th level.\nEnglish Section: Verbal reasoning and comprehension questions.\nPart A Qualifying Rule: Minimum qualifying marks required in drawing section.\nPart B Qualifying Rule: Minimum qualifying marks required in aptitude sectio'),
('UCEED', 'Type of Exam: National level design entrance exam conducted by IIT Bombay.\nPurpose: Admission to Bachelor of Design programs in participating institutes.\nParticipating Institutes: IIT Bombay, IIT Delhi, IIT Guwahati, IIT Hyderabad, IIT Roorkee, and IIITDM Jabalpur.\nScore Acceptance: Many private universities also accept UCEED scores for design admissions.\nStream Eligibility: Open to students from Science, Commerce, and Arts streams.\nScience Requirement Note: IIT Guwahati, IIT Roorkee, and IIITDM Jabalpur usually require Physics, Chemistry, and Maths in Class 12.\nOpen Stream IITs: IIT Bombay, IIT Delhi, and IIT Hyderabad accept students from any stream.\nAttempt Limit: Maximum two attempts in two consecutive years.\nYear Rule Example: If Class 12 passed in 2026, attempts allowed in 2026 and 2027 only.\nAge Limit Rule: Candidate must be born on or after a specified date with relaxation for reserved categories.\nExam Frequency: Conducted once every year.\nExam Month: Usually held in January.\nCareer Advantage: Offers IIT tag and entry into top design careers like product design and UI UX.\nTotal Exam Duration: Three hours.\nTotal Marks: 300 marks.\nPart A Mode: Computer based test of two hours.\nPart A Marks: 200 marks.\nPart A NAT Questions: Numerical answer type questions with no negative marking.\nPart A MSQ Questions: Multiple select questions with partial marking and negative marking for wrong choices.\nPart A MCQ Questions: Single correct option questions with negative marking.\nPart A Syllabus Areas: Visualization, spatial ability, design sensitivity, logical reasoning, language, and creativity.\nPart B Mode: Offline pen and paper drawing test of one hour.\nPart B Marks: 100 marks.\nPart B Question Type 1: Sketching a scene to test perspective and proportions.\nPart B Question Type 2: Design aptitude drawing to test creative problem solving.\nEvaluation Rule: Part B evaluated only if candidate qualifies Part A.\nSeat Availability: Total B.Des seats in IITs are around 200 to 250.\nCo'),
('CEED', 'Type of Exam: National level design entrance exam conducted by IIT Bombay.\nPurpose: Admission to Master of Design and Ph.D. programs in design.\nParticipating Institutes: IISc Bangalore, IIT Bombay, IIT Delhi, IIT Guwahati, IIT Hyderabad, IIT Jodhpur, IIT Kanpur, IIT Roorkee, and IIITDM Jabalpur.\nScore Acceptance: Several private design institutes also accept CEED scores for M.Des admissions.\nMinimum Qualification: Degree, diploma, or postgraduate degree of at least three years after 10 plus 2.\nEligible Backgrounds: B.Des, B.Arch, B.E., B.Tech, B.F.A., G.D. Art and similar professional courses.\nThree Year Degree Note: Candidates with three year degrees like B.A. or B.Sc. may apply but four year professional degrees are often preferred.\nFinal Year Eligibility: Students appearing for final year exams are also eligible.\nAge Limit Rule: No age limit to appear in CEED.\nAttempt Rule: Unlimited attempts allowed.\nExam Frequency: Conducted once every year.\nExam Month: Usually held in January.\nCareer Advantage: M.Des from IIT or IISc is considered a top design qualification in India.\nStipend Benefit: M.Des students often receive monthly assistantship around twelve thousand rupees.\nTotal Exam Duration: Three hours.\nTotal Marks Basis: 200 marks with different weightage for parts.\nPart A Mode: Computer based screening test of one hour.\nPart A Purpose: Filters candidates and Part B evaluated only if Part A is cleared.\nPart A Marks Role: Counts as 25 percent weightage in final score.\nPart A NAT Questions: Numerical answer questions with no negative marking.\nPart A MSQ Questions: Multiple select questions with negative marking.\nPart A MCQ Questions: Multiple choice questions with negative marking.\nPart A Syllabus Areas: Visualization, spatial ability, social awareness, logical reasoning, language and design sensitivity.\nPart B Mode: Offline pen and paper drawing test of two hours.\nPart B Marks Role: Counts as 75 percent weightage in final score.\nPart B Question Count: Five subjectiv'),
('NEET UG', 'Type of Exam: National level medical entrance exam conducted by National Testing Agency.\nPurpose: Admission to undergraduate medical and allied health courses.\nPrimary Course: MBBS Bachelor of Medicine and Bachelor of Surgery.\nDental Course: BDS Bachelor of Dental Surgery.\nAYUSH Courses: BAMS, BHMS, BUMS, and BSMS programs.\nOther Courses: Veterinary and select B.Sc Nursing programs also use NEET scores.\nSingle Exam Rule: Only entrance test for all medical colleges including AIIMS and JIPMER.\nRequired Subjects: Physics, Chemistry, Biology or Biotechnology, and English in Class 12.\nMinimum Marks General: At least 50 percent aggregate in PCB subjects.\nMinimum Marks Reserved: At least 40 percent aggregate for OBC, SC, and ST.\nOpen School Eligibility: Students from open schooling boards are eligible as per current rules.\nMinimum Age: Candidate must be 17 years old by 31 December of admission year.\nUpper Age Limit: No upper age limit to appear in NEET.\nExam Frequency: Conducted once every year.\nExam Month: Usually held on the first Sunday of May.\nCompetition Level: Around 24 lakh students compete for roughly 1 lakh MBBS seats.\nExam Mode: Offline pen and paper test using OMR sheet.\nTotal Duration: Three hours and twenty minutes.\nTotal Questions: 200 questions provided but only 180 to be attempted.\nTotal Marks: Maximum 720 marks.\nCorrect Answer Marking: Four marks awarded for each correct answer.\nWrong Answer Penalty: One mark deducted for each incorrect answer.\nSubjects in Exam: Physics, Chemistry, Botany, and Zoology.\nSection A Structure: 35 compulsory questions in each subject.\nSection B Structure: 15 questions provided but only 10 to be attempted in each subject.\nChoice Rule: If more than 10 attempted in Section B, only first 10 are evaluated.\nPhysics Marks Weightage: 180 marks total.\nChemistry Marks Weightage: 180 marks total.\nBiology Marks Weightage: 360 marks combined from Botany and Zoology.\nSyllabus Authority: Syllabus defined by National Medical Commission.\nRecent'),
('NEET PG', 'Identity: NEET PG national level postgraduate medical entrance exam.\nConducting Body: National Board of Examinations in Medical Sciences.\nPurpose: Admission to MD, MS, PG Diploma, and DNB courses.\nCoverage: Used for government, private, deemed universities and AFMS institutions.\nExcluded Institutes: Institutes like AIIMS, PGI Chandigarh, JIPMER and NIMHANS use INI CET instead.\nCurrent Status: Traditional NEET PG pattern continues as NExT is postponed.\nExam Schedule: Usually conducted around August each year.\nCareer Purpose: Required for specialization after MBBS for better career growth.\nExam Mode: Computer based test.\nTotal Duration: Three hours thirty minutes.\nTotal Questions: 200 multiple choice questions.\nTotal Marks: 800 marks.\nCorrect Answer Marking: Four marks awarded for each correct answer.\nWrong Answer Penalty: One mark deducted for each incorrect answer.\nSectional Pattern: Paper divided into five sections named A to E.\nQuestions Per Section: 40 questions in each section.\nTime Per Section: 42 minutes fixed for each section.\nAuto Submit Rule: Section automatically closes after time ends.\nNavigation Restriction: Candidates cannot return to previous sections.\nPreparation Impact: Time management must be practiced section wise.\nSyllabus Coverage: Includes all nineteen subjects from MBBS curriculum.\nClinical Weightage: Major portion from Medicine, Surgery, OBGYN and PSM.\nPara Clinical Weightage: Significant weightage from Pathology, Pharmacology and Microbiology.\nPre Clinical Weightage: Smaller portion from Anatomy, Physiology and Biochemistry.\nShort Subjects: ENT, Ophthalmology, Orthopedics, Radiology, Dermatology, Psychiatry and Pediatrics also included.\nQuestion Style: Mostly integrated clinical scenario based questions.\nEligibility Degree: Must have completed MBBS from recognized institution.\nRegistration Requirement: Must have registration with State Medical Council or NMC.\nInternship Rule: One year internship must be completed before cutoff date.\nInternshi'),
('INI-CET', 'Identity: INI CET national level postgraduate medical entrance exam.\nConducting Body: AIIMS New Delhi.\nPurpose: Admission to MD, MS, MCh, DM and MDS courses.\nInstitute Coverage: Used for Institutes of National Importance across India.\nMajor Institutes: Includes AIIMS campuses, JIPMER, PGIMER, NIMHANS and SCTIMST.\nEligibility Degree: MBBS or BDS recognized by NMC or DCI.\nMinimum Marks: 55 percent aggregate for General, 50 percent for SC or ST.\nExam Frequency: Conducted twice every year.\nSessions: May exam for July session and November exam for January session.\nCareer Goal: Entry into India’s top government medical research institutes.\nFee Advantage: Very low tuition fees compared to private colleges.\nStipend Benefit: High monthly stipend during residency.\nClinical Exposure: Considered among the best clinical training environments in India.\nExam Mode: Computer based test.\nTotal Duration: Three hours.\nTotal Questions: 200 questions.\nCorrect Marking: One mark awarded for each correct answer.\nWrong Penalty: One third mark deducted for each wrong answer.\nDifficulty Level: Considered tougher than NEET PG.\nReason for Toughness: More complex question formats and deeper concepts.\nQuestion Types: Includes single correct, multiple correct and matching type questions.\nImage Questions: High number of radiology, pathology slide and clinical image questions.\nInternship Rule July Session: Internship must be completed by July 31.\nInternship Rule January Session: Internship must be completed by January 31.\nInternship Warning: Even one day delay makes candidate ineligible for that session.\nSeat Availability: Much fewer seats compared to NEET PG.\nConcept Focus: Greater emphasis on basic sciences like Anatomy, Biochemistry and Pathology.\nResearch Orientation: Questions often test conceptual and research understanding.\nTime Pressure: Less time per question compared to NEET PG.\nGuessing Risk: Negative marking makes blind guessing very risky.\nPreparation Strategy: Practice previous AIIMS an'),
('AIIMS BSc Nursing', 'AIIMS New Delhi BSc Nursing Entrance national level exam.\nConducting Body AIIMS New Delhi.\nPurpose Admission to BSc Nursing courses in multiple AIIMS campuses.\nCourse Type One BSc Hons Nursing four year degree.\nCourse Type Two BSc Post Basic Nursing two year degree for GNM nurses.\nCampuses Include AIIMS New Delhi, AIIMS Jodhpur, AIIMS Bhopal, AIIMS Rishikesh, AIIMS Bhubaneswar and others.\nEligibility Hons Course Only female candidates allowed.\nMale Rule Male candidates not eligible for BSc Hons Nursing at AIIMS.\nPost Basic Eligibility Both male and female candidates eligible with GNM qualification.\nMinimum Age Candidate must be at least 17 years by 31 December of admission year.\nExam Frequency Conducted once every year.\nUsual Month Usually held in June.\nMajor Benefit Training in top government medical institutes of India.\nFee Advantage Very low annual tuition fee around six hundred rupees.\nCareer Advantage AIIMS nursing graduates highly preferred in NORCET recruitment.\nJob Outcome Leads to permanent Nursing Officer posts with high starting salary.\nExam Mode Computer Based Test.\nExam Duration Two hours.\nTotal Questions One hundred questions.\nTotal Marks One hundred marks.\nCorrect Marking One mark for each correct answer.\nNegative Marking One third mark deducted for each wrong answer.\nPhysics Weightage Thirty marks.\nChemistry Weightage Thirty marks.\nBiology Weightage Thirty marks.\nGeneral Knowledge Weightage Ten marks.\nGK Importance General Knowledge section often decides top ranks.\nLanguage Medium Question paper available in English and Hindi.\nEducation Requirement Must pass Class 12 with Physics Chemistry Biology and English.\nMinimum Marks General Category Needs fifty five percent in PCBE subjects.\nMinimum Marks Reserved Category Needs fifty percent in PCBE subjects.\nAppearing Students Students appearing in Class 12 final exams also eligible.\nPost Basic Stage One Written test of seventy marks.\nPost Basic Stage Two Interview or assessment of thirty marks.\nPost Basic '),
('GPAT', ''),
('NIPER JEE', 'Type of Exam National level entrance for Pharmacy studies.\nConducting Body National Board of Examinations in Medical Sciences now conducts the exam.\nMajor Change Earlier conducted by National Testing Agency now shifted to NBEMS.\nPaper Trend Expect more conceptual and clinical style questions after the shift.\nMain Purpose Admission to MPharm programs in top pharmacy institutes.\nTop Colleges Includes NIPERs, government colleges and university pharmacy departments.\nStipend Benefit Qualified students pursuing AICTE approved MPharm receive monthly scholarship.\nScholarship Amount Approx twelve thousand four hundred rupees per month for two years.\nPhD Use Also used as screening exam for PhD in Pharmacy.\nEligibility Degree Bachelor of Pharmacy four year degree required.\nFinal Year Rule Final year BPharm students also eligible.\nNot Eligible BTech Pharmaceutical Technology students cannot apply.\nAge Limit No upper age limit.\nExam Frequency Conducted once every year.\nRecent Cycle Latest exam conducted in March 2026 cycle.\nScore Validity GPAT score valid for three years.\nExam Mode Computer Based Test.\nExam Duration Three hours.\nTotal Questions One hundred twenty five questions.\nTotal Marks Five hundred marks.\nCorrect Marking Four marks awarded for each correct answer.\nNegative Marking One mark deducted for each wrong answer.\nChemistry Weightage Pharmaceutical Chemistry has highest weightage.\nPharmaceutics Weightage Pharmaceutics also has highest weightage equal to Chemistry.\nPharmacology Weightage Pharmacology has moderate weightage.\nPharmacognosy Weightage Pharmacognosy has smaller but scoring weightage.\nOther Subjects Includes Biochemistry, Biotechnology, Microbiology, Pharmaceutical Analysis, Clinical Pharmacy and Jurisprudence.\nQualifying Nature Cutoff varies every year depending on difficulty.\nGeneral Cutoff Usually around one hundred fifty marks out of five hundred.\nOBC Cutoff Usually slightly lower than general category.\nSCST Cutoff Lowest cutoff among categories.\nNIPER '),
('CAT', 'Type of Exam: National level entrance for NIPER institutes.\nConducting Body: Exam conducted each year by one of the NIPER institutes on rotation.\nMain Purpose: Admission to top pharmacy institutes of India known as NIPERs.\nCourses Offered: MS Pharm, MPharm, MTech Pharm, MBA Pharm and PhD programs.\nTop Institute: NIPER Mohali is the oldest and most prestigious campus.\nOther Campuses: Include NIPER Hyderabad, Ahmedabad, Guwahati, Raebareli, Kolkata and Hajipur.\nGolden Eligibility Rule: Candidate must have a valid GPAT score.\nApplication Restriction: Without GPAT qualification you cannot apply for NIPER JEE.\nExam Frequency: Conducted once every year usually after GPAT results.\nExam Mode: Computer Based Test.\nExam Duration: Two hours.\nTotal Questions: Two hundred questions.\nTotal Marks: One hundred scaled marks.\nCorrect Marking: Half mark for each correct answer.\nNegative Marking: One fourth negative of question value deducted for wrong answer.\nSpeed Factor: Average time per question is about thirty six seconds.\nExam Nature: Focus more on speed and memory than deep calculations.\nChemistry Dominance: Organic Chemistry and spectroscopy form largest portion.\nBiotechnology Portion: Includes gene cloning fermentation and blotting techniques.\nPharmacology Portion: Covers mechanism of action CNS and chemotherapy topics.\nGeneral Aptitude: Includes reasoning basic maths and data interpretation.\nGeneral Knowledge: Includes pharma current affairs Nobel prizes and industry updates.\nEnglish Portion: Basic grammar synonyms and antonyms.\nMBA Special Rule: MBA Pharm candidates also appear for same written test.\nMBA Final Selection: MBA Pharm admission also includes group discussion and interview.\nMBA Advantage: MBA Pharm graduates from top NIPERs get very high salary packages.\nChemistry Strategy: Strong grip on organic name reactions and spectroscopy is essential.\nAptitude Strategy: Easy scoring questions from GK and reasoning should not be skipped.\nTop Rank Target: Rank under one hund'),
('XAT', 'Type of Exam: National level management entrance exam.\nConducting Body: Conducted by the Indian Institutes of Management on a rotational basis.\nMain Purpose: Admission to MBA and PGDM programs in top business schools.\nIIM Institutes: Covers admission to 21 IIMs including BLACKI group.\nBLACKI Meaning: Refers to IIM Bangalore IIM Lucknow IIM Ahmedabad IIM Calcutta IIM Kozhikode and IIM Indore.\nTop Non IIM Colleges: Scores also accepted by FMS Delhi SPJIMR MDI Gurgaon IIT DoMS and IIM Mumbai.\nEligibility Degree: Bachelor degree in any stream required.\nMinimum Marks: Fifty percent marks required for General category.\nRelaxation Rule: Forty five percent required for SC ST and PwD.\nFinal Year Rule: Final year graduation students can also apply.\nAge Limit: No upper age limit.\nExam Frequency: Conducted once every year.\nExam Month: Usually held on the last Sunday of November.\nCareer Benefit: MBA from top IIMs can lead to very high salary packages.\nNetworking Advantage: Opportunity to build strong peer and alumni network.\nExam Mode: Computer Based Test.\nTotal Duration: Two hours total exam time.\nTotal Questions: Approximately sixty six questions.\nTotal Marks: One hundred ninety eight marks.\nSectional Time Rule: Forty minutes per section with strict time lock.\nSection Switch Rule: Candidates cannot move back to previous sections.\nSection One Name: VARC meaning Verbal Ability and Reading Comprehension.\nVARC Focus: Reading comprehension passages dominate this section.\nSection Two Name: DILR meaning Data Interpretation and Logical Reasoning.\nDILR Nature: Considered the toughest section with puzzles and sets.\nSection Three Name: QA meaning Quantitative Ability.\nQA Focus: Arithmetic topics form largest share of questions.\nMCQ Marking: Three marks for correct answer and minus one for wrong.\nTITA Marking: Three marks for correct and zero negative for wrong.\nTITA Strategy: All TITA questions should be attempted due to no penalty.\nSelection Reality: CAT percentile alone does not guaran'),
('CMAT', 'Type of Exam: National level management entrance exam.\nConducting Body: Conducted by XLRI Jamshedpur on behalf of XAMI.\nMain Purpose: Admission to MBA and PGDM programs in top management institutes.\nFlagship College: XLRI Jamshedpur is among India’s top B schools equal to top IIMs.\nXAMI Colleges: Includes XIM Bhubaneswar GIM Goa XIME Bangalore and LIBA Chennai.\nOther Accepting Colleges: Scores accepted by IMT Ghaziabad MICA Ahmedabad IMI New Delhi TAPMI Manipal and Great Lakes.\nEligibility Degree: Bachelor degree in any stream of minimum three years duration.\nMinimum Marks Rule: No minimum percentage required to appear for the exam.\nFinal Year Rule: Final year graduation students are eligible.\nAge Limit: No upper age limit.\nExam Frequency: Conducted once every year.\nExam Month: Usually held on the first Sunday of January.\nKey Advantage: Only exam that tests real life decision making ability.\nBrand Value: XLRI is India’s top institute for Human Resource Management.\nExam Mode: Computer Based Test.\nTotal Duration: Approximately three hours ten minutes.\nTotal Questions: Around ninety five to one hundred questions.\nTotal Marks: One hundred marks.\nPart One Sections: Verbal and Logical Ability Decision Making Quant and Data Interpretation.\nPart Two Sections: General Knowledge plus Essay Writing.\nSection Switching: Free switching allowed within Part One sections.\nGK Timing: General Knowledge section attempted in last fifteen minutes.\nEssay Rule: Essay evaluated only if candidate is shortlisted for interview.\nCorrect Marking: One mark awarded for each correct answer.\nWrong Penalty: Minus zero point twenty five for each wrong answer.\nUnattempted Penalty: Leaving more than eight questions blank leads to minus zero point ten per extra blank.\nGK Marking: No negative marking in General Knowledge section.\nGK Usage: GK score used during interview stage not percentile calculation.\nDecision Making Nature: Questions based on ethical and managerial dilemmas.\nDecision Making Importance:'),
('MAT', 'Type of Exam: National level management entrance exam conducted across India.\nConducting Body: Conducted by National Testing Agency.\nMain Purpose: Admission to AICTE approved MBA and PGDM programs.\nExam Reach: Accepted by more than one thousand business schools in India.\nTop Government Colleges: Includes JBIMS Mumbai and PUMBA Pune.\nTop Private Colleges: Includes Great Lakes GIM and other reputed institutes.\nEligibility Degree: Bachelor degree in any stream required.\nFinal Year Rule: Final year graduation students are eligible.\nAge Limit: No upper age limit.\nExam Frequency: Conducted once every year.\nExam Month: Usually held in January or February.\nDifficulty Level: Easier than CAT and XAT exams.\nReturn on Investment: Leads to low fee high salary government MBA colleges.\nExam Mode: Computer Based Test.\nExam Duration: Three hours.\nTotal Questions: One hundred questions.\nTotal Marks: Four hundred marks.\nCorrect Marking: Four marks awarded for each correct answer.\nNegative Marking: One mark deducted for each wrong answer.\nSections Count: Five sections and all are compulsory.\nQuant Section: Twenty questions focused on arithmetic algebra charts and tables.\nLogic Section: Twenty questions on reasoning puzzles series and coding.\nLanguage Section: Twenty questions on reading comprehension grammar and vocabulary.\nGK Section: Twenty questions from static GK and current affairs.\nInnovation Section: Twenty questions from entrepreneurship and business awareness.\nInnovation Topics: Startup India schemes funding stages and business terms.\nSection Balance: All sections carry equal weightage of eighty marks.\nTime Advantage: Plenty of time available compared to CAT exam.\nJBIMS Cutoff: Around ninety nine point nine nine percentile required.\nSIMSREE Cutoff: Around ninety nine point nine five percentile required.\nGIM Goa Cutoff: Usually above ninety five percentile.\nGreat Lakes Cutoff: Generally ninety five to ninety nine percentile.\nPUMBA Cutoff: Around ninety six to ninety eight perce'),
('SNAP', 'Type of Exam: National level management entrance exam conducted across India.\nConducting Body: Conducted by All India Management Association.\nMain Purpose: Admission to MBA and PGDM programs in more than six hundred business schools.\nExam Position: Known as the backup option for students who missed CAT or CMAT.\nTop Accepting Colleges: Includes BIMTECH Greater Noida XIME Bangalore Christ University Bangalore JAGSoM Bangalore and DY Patil Pune.\nEligibility Degree: Graduate in any discipline can apply.\nFinal Year Rule: Final year students are eligible.\nExam Frequency: Conducted four times every year.\nExam Months: Usually held in February May September and December.\nMultiple Attempts Benefit: Candidates can reappear within the same year to improve score.\nExam Modes: Available in Paper Based Test Computer Based Test and Internet Based Test modes.\nHome Mode Feature: IBT allows candidates to take the test from home with online proctoring.\nExam Format: Conducted in PBT CBT or IBT mode.\nExam Duration: Two hours.\nTotal Questions: One hundred fifty questions.\nTotal Marks: One hundred fifty marks.\nCorrect Marking: One mark for each correct answer.\nNegative Marking: Zero point two five marks deducted for each wrong answer.\nTotal Sections: Five sections in the exam.\nLanguage Section: Thirty questions focused on reading comprehension and grammar.\nReasoning Section: Thirty questions on intelligence and critical reasoning.\nData Section: Thirty questions on data analysis and data sufficiency.\nMath Section: Thirty questions on basic mathematical skills.\nGK Section: Thirty questions on Indian and global environment.\nGK Rule: GK marks are not included in final percentile calculation.\nPercentile Basis: Percentile calculated only on first four sections totaling one hundred twenty marks.\nGK Usage: GK may be considered only during interviews by some colleges.\nBIMTECH Cutoff: Around eighty to eighty five percentile required.\nXIME Cutoff: Around seventy five to eighty percentile required.\nChr'),
('NMAT', 'Type of Exam: University level management entrance exam.\nConducting Body: Conducted by Symbiosis International University.\nMain Purpose: Admission to MBA and MSc programs in Symbiosis institutes.\nFlagship Colleges: Includes SIBM Pune and SCMHRD Pune.\nOther Institutes: SIIB Pune SIBM Bangalore and SIOM Nashik also accept scores.\nEligibility Degree: Graduate in any discipline with minimum fifty percent marks.\nReserved Marks Rule: Forty five percent required for SC and ST candidates.\nFinal Year Rule: Final year graduation students are eligible.\nExam Month: Conducted in December on multiple dates.\nBrand Value: Top Symbiosis colleges offer packages comparable to leading IIMs.\nSpeed Advantage: Shortest major MBA entrance exam in India.\nExam Mode: Computer Based Test.\nExam Duration: Sixty minutes.\nTotal Questions: Sixty questions.\nTotal Marks: Sixty marks.\nEnglish Section: Fifteen questions from grammar vocabulary and reading comprehension.\nReasoning Section: Twenty five questions from analytical and logical reasoning.\nQuant Section: Twenty questions from arithmetic algebra geometry and data interpretation.\nTime Pressure: Exactly one minute available per question.\nCorrect Marking: One mark awarded for each correct answer.\nNegative Marking: Zero point two five marks deducted for wrong answers.\nAttempt Opportunity: Candidates can attempt the exam up to three times in the same year.\nBest Score Rule: Highest score among attempts is used for percentile calculation.\nAttempt Strategy: Taking at least two attempts is recommended for safety.\nSectional Cutoff: Usually no sectional cutoff only overall percentile matters.\nSIBM Pune Cutoff: Around ninety eight point five percentile required.\nSCMHRD Cutoff: Around ninety seven percentile required.\nSIIB Pune Cutoff: Around ninety three to ninety four percentile required.\nSIBM Bangalore Cutoff: Around ninety percentile required.\nSIOM Nashik Cutoff: Around eighty five to eighty seven percentile required and mainly for engineers.\nEnglish St'),
('IIFT MBA Entrance', 'Type of Exam: National (Conducted by the Graduate Management Admission Council – GMAC, the same body that conducts GMAT)\nFor Which Posts: Admission to MBA/PGDM programs in NMIMS (Narsee Monjee Institute of Management Studies) and 40+ other B-Schools\nMain Target: NMIMS Mumbai (One of India\'s Top 10 B-Schools)\nOther Top Colleges: XIM University, K. J. Somaiya Institute of Management, TAPMI, SDA Bocconi Asia Center, SPJIMR (PGMPW)\nFor Whom: Bachelor’s Degree in any discipline with minimum 50% marks\nEligibility Status: Final year graduation students are eligible\nWhen: Conducted over a 70–75 day testing window (usually from October to December)\nWhy: It is the only major MBA exam that allows you to choose your exam date and time slot\nBig Advantage: No negative marking allows you to attempt 100% of the paper without fear\nExam Pattern: Computer Adaptive Test (Adaptive Test)\nAdaptive Meaning: If you answer correctly, the next question becomes tougher and carries more marks; if you answer wrong, the next question becomes easier and carries fewer marks\nFormat: Computer Based Test (CBT) – 2 Hours (120 Minutes)\nTotal Questions: 108 Questions\nTotal Marks: 360 Marks (Scaled Score)\nMarking Scheme Correct Answer: +1 (Scaled)\nMarking Scheme Wrong Answer: 0 Marks (No Negative Marking)\nSection 1 Name: Language Skills\nSection 1 Questions: 36\nSection 1 Time Limit: 28 Minutes\nSection 1 Focus: Speed is critical (less than 1 minute per question)\nSection 2 Name: Quantitative Skills\nSection 2 Questions: 36\nSection 2 Time Limit: 52 Minutes\nSection 2 Focus: Arithmetic, Algebra, Data Interpretation (Toughest section)\nSection 3 Name: Logical Reasoning\nSection 3 Questions: 36\nSection 3 Time Limit: 40 Minutes\nSection 3 Focus: Critical Reasoning, Puzzles, Input-Output\nTotal Questions Overall: 108\nTotal Time Overall: 120 Minutes\nCrucial Rule: You cannot switch between sections once a section’s time ends\nSection Order Choice: You can choose the order of sections at the start of the exam\nSpecial Rule N'),
('TISSNET', 'Type of Exam: NONE (Indian Institute of Foreign Trade has cancelled its own entrance exam)\nAdmissions Based On: CAT (Common Admission Test) scores only\nFor Which Posts: Admission to MBA in International Business (IB) and Business Analytics (BA)\nCampus 1: IIFT Delhi (Flagship campus, known as Mecca for Trade)\nCampus 2: IIFT Kolkata (Equally reputed with unified placements)\nCampus 3: IIFT Kakinada (Newer campus, Integrated Programme focus)\nFor Whom Education: Bachelor’s Degree minimum 3 years with 50% marks (45% for SC/ST/PwD)\nMaths Rule for MBA BA: Mathematics or Statistics required at 10+2 or Graduation level\nMaths Rule for MBA IB: No Mathematics restriction\nWhen Step 1: Apply for CAT during August–September\nWhen Step 2: Apply separately to IIFT during October–November\nBig Advantage: IIFT offers very high placement packages\nAverage Salary: Approx ₹29–30 Lakhs CTC\nHighest Domestic Salary: Often crosses ₹75 Lakhs\nSpecialization: Only top Indian B-School specializing in Foreign Trade (Export-Import, Logistics, International Finance)\nImportant Trap Name: Separate Application Trap\nCAT Form Requirement: Appear for CAT exam\nIIFT Form Requirement: Must fill separate application form on official IIFT website\nCritical Warning: Even with 99.99 percentile in CAT, missing IIFT form means no interview call\nSelection Stage 1 Name: Shortlisting Based on CAT\nGeneral Category CAT Cutoff: Approx 95–98 percentile\nSectional Cutoff Rule: Must clear VARC, DILR, and QA sectional cutoffs individually\nSelection Stage 2 Name: WAT PI Extempore\nStage Timing: Usually conducted in February–March\nWAT Meaning: Essay writing on current or business topics\nExtempore Meaning: Speak for 2 minutes instantly on a random topic\nInterview Focus Area: GK, Geography, International Trade, Business News\nCommon Interview Questions: Indian ports, world capitals, FDI vs FII, trade routes\nFinal Selection Parameter 1: CAT Score\nCAT Score Weightage: 45–55%\nFinal Selection Parameter 2: GD PI WAT Performance\nGD PI WAT W'),
('CLAT', 'Identity Card: TISS Admission 2026\nType of Exam: Accepted Scores Only (No separate TISS exam)\nInstitute: Tata Institute of Social Sciences\nCampuses: Mumbai (Main), Tuljapur, Hyderabad, Guwahati\nBig Advantage 1: Very low fees approx ₹1.5–2 Lakhs for 2 years\nBig Advantage 2: Average package for HRM course approx ₹27+ Lakhs\nReputation: Asia’s oldest and most prestigious institute for social work\n\nAdmission System Name: Two-Route Admission System\nRule: You must apply through the correct exam based on your course choice\n\nRoute 1 Name: CAT Route (For Flagship Management Courses)\nRequired Exam: CAT (Common Admission Test) 2025\nRoute 1 Courses 1: MA in Human Resource Management & Labour Relations (HRM & LR)\nRoute 1 Courses 2: MA in Organisation Development Change and Leadership (ODCL)\nRoute 1 Courses 3: Master of Hospital Administration (MHA)\nRoute 1 Stage 1: Shortlisting based on CAT 2025 score\nRoute 1 Stage 2: Online Assessment or Personal Interview\nRoute 1 Important Rule: Without CAT 2025 score you cannot apply for these courses for 2026–28 batch\nRoute 1 Next Chance: You must wait for CAT 2026 if you missed CAT 2025\n\nRoute 2 Name: CUET PG Route (For All Other MA Courses)\nRequired Exam: CUET-PG 2026 conducted by NTA\nRoute 2 Courses: Social Work, Development Studies, Public Health, Psychology and 50+ other programs\nCommon Paper Code: COQP11 (General Paper) for many TISS courses\nImportant Warning: Paper codes change every year so verify on official TISS or NTA website\n\nRoute 2 Stage 1: CUET-PG score carries 75% weightage\nRoute 2 Stage 2: Online Assessment or Interview carries 25% weightage\n\nCUET PG Exam Format: Computer Based Test\nCUET PG Exam Duration: 105 Minutes\nCUET PG Total Questions: 75 Questions\nCUET PG Total Marks: 300 Marks\nCUET PG Marking Correct: +4 Marks\nCUET PG Marking Wrong: −1 Mark\n\nCUET PG Syllabus Part 1: Language Comprehension including English or Hindi grammar and reading skills\nCUET PG Syllabus Part 2: General Knowledge and Current Affairs\nCUET PG Syllab'),
('AILET', 'Type of Exam: National (Conducted by the Consortium of National Law Universities)\nExam Name: CLAT (Common Law Admission Test)\nFor Which Courses 1: 5-Year Integrated LLB UG courses (BA LLB, BBA LLB, BCom LLB, etc.)\nFor Which Courses 2: LLM PG courses\nParticipating Institutes: Admission to 24 National Law Universities in India\nTop Tier Institute 1: NLSIU Bangalore\nTop Tier Institute 2: NALSAR Hyderabad\nTop Tier Institute 3: WBNUJS Kolkata\nOther Accepting Institutes 1: Nirma University\nOther Accepting Institutes 2: NMIMS\nOther Uses: Some PSUs use CLAT PG scores for legal recruitment\n\nEligibility Education: 12th Pass or Appearing with minimum 45% marks (40% for SC/ST)\nEligibility Stream: Open to Science, Commerce, and Arts/Humanities\nEligibility Status: Students appearing for Class 12 board exams in 2026 are eligible\nAge Limit: No age limit\n\nExam Frequency: Once a year\nExpected Exam Time: Usually in December\nBatch Note: Exam for 2026 admission cycle likely in December 2025\n\nCareer Benefit 1: Corporate law placements ₹16–20 Lakhs+ in top law firms and companies\nCareer Benefit 2: Strong foundation for Judiciary exams and Civil Services\n\nExam Mode: Offline Pen and Paper\nExam Duration: 2 Hours (120 Minutes)\nTotal Questions: 120 Questions\nTotal Marks: 120 Marks\nMarking Correct: +1 Mark\nMarking Wrong: −0.25 Mark\n\nSection 1 Name: English Language\nSection 1 Questions: Approx 22–26\nSection 1 Weightage: Around 20%\nSection 1 Focus: Reading comprehension, tone inference, vocabulary in context\n\nSection 2 Name: Current Affairs and General Knowledge\nSection 2 Questions: Approx 28–32\nSection 2 Weightage: Around 25%\nSection 2 Focus: Passage-based news questions requiring outside knowledge\n\nSection 3 Name: Legal Reasoning\nSection 3 Questions: Approx 28–32\nSection 3 Weightage: Around 25%\nSection 3 Focus: Apply legal principles given in passage to factual situations\n\nSection 4 Name: Logical Reasoning\nSection 4 Questions: Approx 22–26\nSection 4 Weightage: Around 20%\nSection 4 Focus: Critica'),
('LSAT—India', 'Type of Exam: University Level Law Entrance\nExam Name: AILET (All India Law Entrance Test)\nConducting Body: National Law University Delhi\nCrucial Distinction: NLU Delhi is not part of the CLAT consortium and CLAT score is not valid here\nPurpose: Admission only to NLU Delhi\n\nCourses Offered 1: B.A. LL.B. (Hons) 5-Year Integrated Course\nCourses Offered 2: LL.M 1-Year Master of Law\nCourses Offered 3: Ph.D Doctoral Programs\nInstitute Status: Consistently ranked among top law schools in India with extremely limited seats\nCompetition Level: Considered one of the toughest law admissions in India due to low seat count\n\nEligibility Education: 12th Pass or Appearing with minimum 45% marks (40% for SC/ST/PwD)\nEligibility Status: Students appearing for Class 12 in 2026 are eligible\n\nExam Frequency: Once per year\nExpected Exam Month: December\nExpected Exam Year for 2026 Batch: December 2025\n\nExam Mode: Offline Pen and Paper\nExam Duration: 2 Hours (120 Minutes)\nTotal Questions: 150 Questions\nSpeed Requirement: About 1.25 questions per minute\nTotal Marks: 150 Marks\nMarking Correct: +1 Mark\nMarking Wrong: −0.25 Mark\n\nSection 1 Name: English Language\nSection 1 Questions: 50\nSection 1 Weightage: Around 33%\nSection 1 Focus: Reading comprehension, grammar, vocabulary, idioms\n\nSection 2 Name: Current Affairs and General Knowledge\nSection 2 Questions: 30\nSection 2 Weightage: Around 20%\nSection 2 Focus: Static GK and current affairs with direct questions\n\nSection 3 Name: Logical Reasoning\nSection 3 Questions: 70\nSection 3 Weightage: Around 47%\nSection 3 Focus: Critical reasoning, analytical puzzles, principle-fact questions\n\nLegal Reasoning Rule: No separate legal section but legal principles may appear inside logical reasoning questions\nPrior Legal Knowledge Requirement: Not required\n\nTotal BA LLB Seats: Approx 123 Seats\nGeneral Category Seats: Approx 50 Seats\nRank Reality: Even AIR 60 may not guarantee a General category seat\nTarget Rank: Effectively Top 50 for strong General category c'),
('CUET UG', 'Type of Exam: International Law Entrance Test\nExam Name: LNAT (Law National Aptitude Test)\nConducting Body: Pearson VUE\n\nUsed For Admission 1: Jindal Global Law School 5-Year B.A./B.B.A. LL.B. (Hons)\nUsed For Admission 2: Top UK Law Universities\n\nTop UK Universities Accepting LNAT 1: University of Oxford\nTop UK Universities Accepting LNAT 2: University of Cambridge\nTop UK Universities Accepting LNAT 3: London School of Economics and Political Science\nTop UK Universities Accepting LNAT 4: University College London\nTop UK Universities Accepting LNAT 5: King\'s College London\n\nEligibility Education: 12th Pass or Appearing\nEligibility Stream: Open to all streams\nTesting Window: Usually September to January for next academic year\nBooking Tip: Slot booking is flexible but centers fill quickly\n\nKey Benefit 1: Only pathway for 5-Year Integrated LLB at Jindal Global Law School\nKey Benefit 2: Same score usable for multiple UK universities\n\nExam Format: Computer Based Test at authorized center\nTotal Duration: 2 Hours 15 Minutes\nTotal Sections: Two Sections\n\nSection A Name: Multiple Choice Questions\nSection A Duration: 95 Minutes\nSection A Questions: 42 Questions\nSection A Structure: 12 argumentative passages with 3–4 questions each\nSection A Skills Tested: Induction, deduction, inference, critical thinking\n\nSection B Name: Essay Writing\nSection B Duration: 40 Minutes\nSection B Task: Choose 1 out of 3 prompts and write 500–600 word essay\n\nScoring Section A: Computer marked out of 42 and used directly by JGLS\nScoring Section B: Essay sent to university for manual evaluation of writing and argument skills\n\nSubject Coverage: No Law syllabus, no GK, no Mathematics\nCore Focus: Argument analysis, logical reasoning, and structured writing\n\nOld Exam Comparison Name: LSAT—India (Discontinued)\nDifference 1: LNAT includes mandatory essay unlike old LSAT—India\nDifference 2: LNAT reading passages are more academic and philosophy-based\nDifference 3: LNAT score has global acceptance unlike LSA'),
('CUET PG', 'Type of Exam: National (Conducted by the National Testing Agency)\nExam Name: CUET UG (Common University Entrance Test - Undergraduate)\n\nPurpose: Admission to Undergraduate Bachelor’s programs across India\n\nCentral Universities Accepting CUET 1: University of Delhi\nCentral Universities Accepting CUET 2: Banaras Hindu University\nCentral Universities Accepting CUET 3: Jawaharlal Nehru University\nCentral Universities Accepting CUET 4: Jamia Millia Islamia\nCentral Universities Accepting CUET 5: University of Allahabad\nCentral Universities Accepting CUET 6: Aligarh Muslim University\n\nOther Universities Accepting CUET 1: Dr. B. R. Ambedkar University Delhi\nOther Universities Accepting CUET 2: Galgotias University\nOther Universities Accepting CUET 3: Amity University\n\nImpact Rule: CUET has largely replaced Class 12 board marks as the main admission criteria\n\nEligibility Education: 12th Pass or Appearing from recognized board\nEligibility Stream: Open to Science, Commerce, and Arts students\n\nExam Frequency: Once per year\nExam Month: Usually May\nExam Schedule Style: Conducted across multiple days and shifts\n\nMajor Advantage 1: One exam provides access to 250+ universities\nMajor Advantage 2: Flexible subject combinations depending on course rules\n\nExam Mode: Hybrid (Some high-registration subjects offline, others CBT)\nMaximum Subjects Allowed: Up to 5 subjects\nDuration Per Subject: Usually 45 minutes\nDuration for Calculation Subjects: 60 minutes (Maths, Physics, Chemistry, Accountancy, Economics)\n\nMarking Correct Answer: +5 Marks\nMarking Wrong Answer: −1 Mark\n\nSection 1 Name: Languages\nSection 1 Details: Choice of 13 languages including English and Hindi\nSection 1 Importance: Mandatory for most university programs\n\nSection 2 Name: Domain Subjects\nSection 2 Details: 27 subjects based only on Class 12 syllabus\nSection 2 Rule: No Class 11 syllabus included\n\nSection 3 Name: General Test\nSection 3 Syllabus: GK, Current Affairs, Numerical Ability, Logical Reasoning\nSection 3 Needed F'),
('NIFT Entrance Exam', 'Type of Exam: National (Conducted by the National Testing Agency)\nExam Name: CUET PG (Common University Entrance Test - Postgraduate)\n\nPurpose: Admission to Master’s Degree programs such as MA, MSc, MCA, MBA, LLM, MCom, MTech and others\n\nMajor Universities Accepting CUET PG 1: University of Delhi\nMajor Universities Accepting CUET PG 2: Jawaharlal Nehru University\nMajor Universities Accepting CUET PG 3: Banaras Hindu University\nMajor Universities Accepting CUET PG 4: University of Hyderabad\nOther Accepting Institutes: Several state, deemed and private universities including Tata Institute of Social Sciences for selected programs\n\nEligibility Education: Bachelor’s Degree passed or appearing\nAge Limit: No age limit\n\nExam Frequency: Once per year\nExam Month: Usually March\n\nMajor Benefit 1: Single exam gateway to DU and JNU postgraduate programs\nMajor Benefit 2: Exam is now fully subject-focused with no general section for most papers\n\nExam Mode: Computer Based Test\nExam Duration: 105 Minutes (1 Hour 45 Minutes)\nTotal Questions: 75 Questions\nTotal Marks: 300 Marks\n\nMarking Correct Answer: +4 Marks\nMarking Wrong Answer: −1 Mark\n\nPaper Structure Change: Part A General section removed for most subjects\nMain Section: All 75 questions from core subject domain\n\nException Paper Type 1: COQP11 General Paper used for LLB and some interdisciplinary courses\nException Paper Type 2: COQP12 MBA aptitude-based paper\nException Rule: These papers include aptitude and reasoning instead of core subject theory\n\nImportant Concept Name: Paper Code Selection\nCritical Rule: Admission eligibility depends entirely on selecting the correct paper code\n\nCommon Paper Code COQP11: Used for General courses like LLB and some Social Work programs\nCommon Paper Code COQP12: Used for MBA admissions in universities like BHU\nScience Paper Code SCQP09: Used for Computer Science and MCA programs\nScience Paper Code SCQP19: Used for Mathematics\nScience Paper Code SCQP17: Used for Life Sciences\nHumanities Paper Co');
INSERT INTO `exams` (`exam_name`, `detail`) VALUES
('NID DAT', 'Type of Exam: National (Conducted by the National Testing Agency)\nInstitute: National Institute of Fashion Technology\nCampuses: 18 campuses including Delhi, Mumbai, Bangalore, Gandhinagar\n\nPrograms Offered B.Des: Bachelor of Design 4 Years (Fashion Design, Leather Design, Accessory Design, Textile Design, Knitwear Design, Fashion Communication)\nPrograms Offered B.F.Tech: Bachelor of Fashion Technology 4 Years (Apparel Production – Technical Course)\nMasters Programs: M.Des, M.F.M (Master of Fashion Management), M.F.Tech\n\nEligibility B.Des: 12th Pass or Appearing from any stream\nEligibility B.F.Tech: 12th Pass or Appearing with Physics and Mathematics compulsory\n\nAge Limit General and OBC: Less than 24 years as of 1 August of admission year\nAge Limit SC ST PwD: Relaxation of 5 years (Up to 29 years)\n\nExam Frequency: Once a year\nExam Month: Usually February\nNext Exam Date: 8 February 2026\n\nKey Benefit 1: Considered the IIT of Fashion in India\nKey Benefit 2: Strong placements with major brands and designers\nInstitute Status: Statutory body under Ministry of Textiles Government of India\n\nExam Pattern Name: Double Stage Pattern (GAT plus CAT for Design)\n\nB.Des Selection Stage 1 Part 1: CAT Creative Ability Test\nCAT Weightage: 50%\nCAT Mode: Pen and Paper Drawing Test\nCAT Duration: 3 Hours\nCAT Focus: Observation skills, creativity, visualization, drawing ability\nCAT Negative Marking: No\n\nB.Des Selection Stage 1 Part 2: GAT General Ability Test\nGAT Weightage B.Des: 30%\nGAT Mode: Computer Based Test\nGAT Duration B.Des: 2 Hours\nGAT Syllabus: English, General Knowledge, Mathematics, Logical Reasoning\nGAT Negative Marking: Yes (−0.25)\n\nB.Des Selection Stage 2: Situation Test\nSituation Test Weightage: 20%\nSituation Test Description: Model making using given materials like cardboard, wire, clay, paper within time limit\n\nB.F.Tech Selection Process: Single Stage Only\nB.F.Tech Exam Name: GAT General Ability Test\nB.F.Tech Weightage: 100%\nB.F.Tech Mode: Computer Based Test\nB.F.Tech Dur'),
('IISER Aptitude Test (IAT)', 'Type of Exam: National (Conducted by the National Institute of Design)\nExam Name: NID DAT (Design Aptitude Test)\n\nPurpose: Admission to professional design programs at NID campuses\n\nPrograms Offered B.Des: Bachelor of Design 4 Years\nPrograms Offered M.Des: Master of Design 2.5 Years\n\nEligibility B.Des: 12th Pass or Appearing from any stream\nEligibility M.Des: Bachelor’s Degree in any discipline or 4-year Diploma in Design\n\nAge Limit General and EWS B.Des: Up to 20 years\nAge Relaxation OBC SC ST: 3 years\n\nExam Stage 1 Timing: DAT Prelims usually in December or January\nExam Stage 2 Timing: DAT Mains usually in April or May\n\nInstitute Reputation: NID Ahmedabad is considered the most prestigious design campus in India\nCampus Culture: Studio-based learning, practical design focus, minimal textbook dependence\n\nB.Des Campuses 1: NID Ahmedabad Main Campus\nB.Des Campuses 2: NID Andhra Pradesh\nB.Des Campuses 3: NID Haryana\nB.Des Campuses 4: NID Madhya Pradesh\nB.Des Campuses 5: NID Assam\nImportant Note B.Des: NID Bengaluru and NID Gandhinagar do not offer B.Des\n\nM.Des Campuses 1: NID Ahmedabad\nM.Des Campuses 2: NID Gandhinagar\nM.Des Campuses 3: NID Bengaluru\n\nSelection System Name: Two Stage Selection Process\n\nStage 1 Name: DAT Prelims\nStage 1 Mode: Pen and Paper\nStage 1 Duration: 3 Hours\nStage 1 Total Marks: 100 Marks\n\nPrelims Part 1 Type: Objective Section\nPrelims Part 1 Marks: 30 Marks\nPrelims Part 1 Syllabus: Design GK, Art and Culture Current Affairs, Logical Reasoning\n\nPrelims Part 2 Type: Subjective Section\nPrelims Part 2 Marks: 70 Marks\nPrelims Part 2 Focus 1: Drawing skills including perspective, light and shadow, human proportions\nPrelims Part 2 Focus 2: Visual storytelling and storyboarding\nPrelims Part 2 Focus 3: Creative imagination based design problems\n\nStage 2 Name: DAT Mains\n\nMains for B.Des: Studio Test only\nStudio Test Task: 3D model making or material-based problem solving\nMains for M.Des: Studio Test plus Personal Interview\nM.Des Interview Focus: Portfolio'),
('NEST', 'Type of Exam: National (Conducted by the Joint Admissions Committee IISER)\nExam Name: IISER Aptitude Test (IAT)\n\nPurpose: Admission to 5-Year BS-MS Dual Degree and 4-Year BS Degree programs in top science institutes\n\nParticipating Institute 1: IISER Pune\nParticipating Institute 2: IISER Kolkata\nParticipating Institute 3: IISER Mohali\nParticipating Institute 4: IISER Bhopal\nParticipating Institute 5: IISER Thiruvananthapuram\nParticipating Institute 6: IISER Tirupati\nParticipating Institute 7: IISER Berhampur\nSpecial Institute 1: Indian Institute of Science Bangalore admission available through IAT channel\nSpecial Institute 2: IIT Madras BS in Medical Sciences and Engineering via IAT\n\nEligibility Education: 12th Pass or Appearing in Science stream\nEligibility Subjects: At least three among Physics Chemistry Biology Mathematics in Class 12\nEligibility Marks: Minimum 60% aggregate (55% for SC/ST/PwD)\n\nExam Frequency: Once per year\nExam Month: Usually June\n\nCareer Advantage 1: Strong focus on scientific research careers\nCareer Advantage 2: Less speed pressure compared to JEE style exams\nScholarship Opportunity: Students may receive INSPIRE or similar scholarships during study\n\nExam Mode: Computer Based Test\nExam Duration: 3 Hours (180 Minutes)\nTotal Questions: 60 Questions\nTotal Marks: 240 Marks\n\nMarking Correct Answer: +4 Marks\nMarking Wrong Answer: −1 Mark\n\nSection Physics Questions: 15\nSection Physics Level: JEE Main level conceptual questions\n\nSection Chemistry Questions: 15\nSection Chemistry Level: NCERT plus JEE Main\nSection Chemistry Focus: Organic and Inorganic heavily NCERT based\n\nSection Mathematics Questions: 15\nSection Mathematics Level: JEE Main level\nSection Mathematics Note: PCB students should target easier topics\n\nSection Biology Questions: 15\nSection Biology Level: Strictly NCERT\nSection Biology Note: Must-attempt scoring area especially for PCM students\n\nKey Rule: You cannot ignore Mathematics or Biology completely\n\nStrategy PCM Students: Focus on easy'),
('ICAR AIEEA', 'Type of Exam: National (Conducted jointly by NISER Bhubaneswar and UM-DAE CEBS Mumbai)\nExam Name: NEST (National Entrance Screening Test)\n\nPurpose: Admission to 5-Year Integrated M.Sc. program in Basic Sciences\n\nParticipating Institute 1: NISER Bhubaneswar under Department of Atomic Energy\nParticipating Institute 2: UM-DAE CEBS Mumbai (University of Mumbai – Department of Atomic Energy Centre for Excellence in Basic Sciences)\n\nEligibility Education: 12th Pass or Appearing in Science stream\nEligibility Subjects: Must have studied Physics Chemistry Mathematics Biology in Class 12\nEligibility Marks: Minimum 60% aggregate (55% for SC/ST/PwD)\n\nExam Frequency: Once per year\nExam Month: Usually June\n\nCareer Benefit 1: Top students may get direct opportunity to join Bhabha Atomic Research Centre as Scientific Officers\nScholarship Benefit: DISHA Scholarship approx ₹60,000 per year plus ₹20,000 summer internship grant\n\nExam Mode: Computer Based Test\nExam Duration: 3 Hours 30 Minutes\nSections: 4 Sections Physics Chemistry Mathematics Biology\nTotal Marks: Around 200 Marks (about 50 per section)\n\nQuestion Type 1: MCQ single correct answer with negative marking\nQuestion Type 2: MSQ multiple correct answers with no negative marking\n\nKey Pattern Name: Best of Three Rule\nBest of Three Meaning: Final merit usually calculated from best 3 subject scores out of PCMB\nAttempt Rule: You can attempt all 4 sections and best 3 will be counted automatically\n\nSMAS Rule Name: Section-wise Minimum Admissible Score\nSMAS Requirement: Must clear minimum cutoff marks in at least 3 subjects\nSMAS Meaning: You cannot score very high in two subjects and zero in the third counted subject\n\nComparison Feature 1: NEST counts best 3 subjects while IISER IAT counts all 4\nComparison Feature 2: NEST difficulty level closer to JEE Advanced\nComparison Feature 3: NEST allows skipping one subject strategically\nComparison Feature 4: NEST includes tricky MSQs unlike mostly MCQ pattern in IAT\n\nSeat Count NISER Bhubanes'),
('NCHM JEE', 'Type of Exam UG: National (Conducted by the National Testing Agency)\nAdmission Authority: Indian Council of Agricultural Research\n\nPurpose UG: Admission to Bachelor Degree programs in Agriculture and Allied Sciences\n\nUG Courses 1: BSc Hons Agriculture\nUG Courses 2: BSc Hons Horticulture\nUG Courses 3: BSc Hons Forestry\nUG Courses 4: B.F.Sc Fisheries\nUG Courses 5: Community Science\nUG Courses 6: Sericulture\nUG Courses 7: Food Nutrition and Dietetics\n\nUG BTech Courses 1: Agricultural Engineering\nUG BTech Courses 2: Dairy Technology\nUG BTech Courses 3: Food Technology\nUG BTech Courses 4: Biotechnology\n\nSeat Rule 1: 100 percent seats in ICAR Deemed Universities filled through CUET\nICAR Deemed University 1: Indian Agricultural Research Institute\nICAR Deemed University 2: National Dairy Research Institute\nICAR Deemed University 3: Rani Lakshmi Bai Central Agricultural University\nICAR Deemed University 4: Dr Rajendra Prasad Central Agricultural University\n\nSeat Rule 2: 20 percent All India Quota seats in State Agricultural Universities\nExample SAU 1: Punjab Agricultural University\nExample SAU 2: Tamil Nadu Agricultural University\nExample SAU 3: Govind Ballabh Pant University of Agriculture and Technology\n\nExam Requirement UG: Must appear in CUET UG (Common University Entrance Test - Undergraduate)\nSubject Rule UG: Choose any 3 domain subjects from Physics Chemistry Mathematics Biology or Agriculture\n\nPopular Combo 1: PCB for Agriculture Horticulture Fisheries\nPopular Combo 2: PCM for Agricultural Engineering and Dairy Technology\nPopular Combo 3: ABC Agriculture Biology Chemistry easier scoring option\n\nMarking Scheme CUET: +5 correct minus 1 wrong\n\nEligibility UG Marks: Minimum 50 percent General OBC EWS or 40 percent SC ST PwD\nEligibility UG Subject Rule: Must have studied chosen CUET subjects in Class 12\n\nIdentity Card PG Admissions: ICAR AIEEA PG\nType of Exam PG: National (Conducted by NTA for ICAR)\n\nPurpose PG: Admission to Master degree programs in Agricultural Universi'),
('UGC NET', 'Type of Exam: National (Conducted by the National Testing Agency)\nExam Name: NCHM JEE (National Council for Hotel Management Joint Entrance Examination)\n\nPurpose: Admission to BSc in Hospitality and Hotel Administration\n\nParticipating Institutes: 75 plus Institutes of Hotel Management across India\nTop Central IHM 1: IHM Pusa\nTop Central IHM 2: IHM Mumbai\nTop Central IHM 3: IHM Bangalore\nTop Central IHM 4: IHM Hyderabad\nTop Central IHM 5: IHM Chennai\nTop Central IHM 6: IHM Kolkata\n\nEligibility Education: 12th Pass or Appearing with English as core subject\nEligibility Stream: Open to Arts Commerce and Science students\nAge Limit: No upper age limit\n\nCareer Path 1: Chef Hotel Manager Hospitality Professional\nCareer Path 2: Luxury retail aviation and corporate service sector roles\nPlacement Brands: Oberoi Taj Marriott Starbucks McDonalds and more\n\nExam Mode: Computer Based Test\nExam Duration: 3 Hours (180 Minutes)\nTotal Questions: 120 Questions\nTotal Marks: 480 Marks\n\nMarking Correct Answer: +4 Marks\nMarking Wrong Answer: −1 Mark\n\nSection English Language Questions: 45\nSection English Marks: 180\nSection English Importance: Highest weightage and major rank decider\n\nSection Service Sector Aptitude Questions: 30\nSection Service Sector Marks: 120\nSection Service Sector Focus: Situational judgment and hospitality ethics\n\nSection Reasoning Questions: 15\nSection Reasoning Marks: 60\nSection Reasoning Focus: Basic puzzles and logical deduction\n\nSection Numerical Ability Questions: 15\nSection Numerical Ability Marks: 60\nSection Numerical Ability Level: Basic 10th standard mathematics\n\nSection General Knowledge Questions: 15\nSection GK Marks: 60\nSection GK Focus: Current affairs and hospitality industry awareness\n\nService Sector Strategy Rule: Choose answers that prioritize guest satisfaction while respecting company rules\nService Sector Warning: Avoid aggressive or ignoring responses in situational questions\n\nTop College Rank Target 1: IHM Pusa Safe Rank under 350 AIR\nTop College '),
('CSIR NET', 'Type of Exam: National (Conducted by the National Testing Agency)\nExam Name: UGC NET (University Grants Commission National Eligibility Test)\n\nPurpose 1: Qualification for Junior Research Fellowship\nPurpose 2: Eligibility for Assistant Professor positions in colleges and universities\nPurpose 3: Direct eligibility for PhD admission interviews in many universities\n\nBenefit JRF: Monthly fellowship approx ₹37,000 plus HRA for PhD research\n\nEligibility Education: Master’s Degree or equivalent with minimum 55 percent marks (50 percent for SC ST OBC PwD)\nEligibility Status: Final year Master’s students are also eligible\n\nExam Frequency: Twice per year\nExam Months: Usually June and December\nExpected June 2026 Cycle: Mid June\n\nMajor Advantage 1: Government funded research fellowship through JRF\nMajor Requirement: NET qualification is essential for permanent Assistant Professor roles in India\n\nExam Mode: Computer Based Test\nExam Duration: 3 Hours (180 Minutes) continuous with no break\nTotal Questions: 150 Questions\nTotal Marks: 300 Marks\n\nMarking Correct Answer: +2 Marks\nMarking Wrong Answer: 0 Marks (No negative marking)\n\nPaper 1 Name: General Aptitude\nPaper 1 Questions: 50\nPaper 1 Marks: 100\nPaper 1 Focus Areas: Teaching aptitude research aptitude reasoning math ICT environment education system\n\nPaper 2 Name: Subject Specific Paper\nPaper 2 Questions: 100\nPaper 2 Marks: 200\nPaper 2 Focus: Based entirely on candidate’s postgraduate subject\n\nAge Limit for JRF: Maximum 30 years (General category)\nAge Relaxation for JRF: Up to 5 years for OBC NCL SC ST PwD Women and Transgender candidates\nAge Limit for Assistant Professor: No upper age limit\n\nResult Category 1: Qualified for JRF plus Assistant Professor plus PhD admission\nResult Category 2: Qualified for Assistant Professor plus PhD admission only\nResult Category 3: Qualified for PhD admission only\n\nPaper 1 Unit 1: Teaching Aptitude\nPaper 1 Unit 2: Research Aptitude\nPaper 1 Unit 3: Comprehension\nPaper 1 Unit 4: Communication\nPap'),
('SET/SLET', 'Type of Exam: National (Conducted by the National Testing Agency on behalf of Council of Scientific and Industrial Research)\nExam Name: CSIR NET (Council of Scientific and Industrial Research National Eligibility Test)\n\nPurpose 1: Junior Research Fellowship for research in CSIR labs and universities\nPurpose 2: Eligibility for Lectureship or Assistant Professor positions\nPurpose 3: Direct PhD interview eligibility in many institutes\n\nJRF Benefit: Monthly stipend approx ₹37,000 plus HRA for research scholars\n\nEligibility Stream: Only for Science background candidates\nEligibility Education: MSc or equivalent degree such as BS-MS BTech BPharma MBBS with minimum 55 percent marks (50 percent for SC ST PwD)\nSpecial Rule: BTech and BPharma candidates eligible for JRF only not Lectureship\n\nExam Frequency: Twice per year\nExam Months: Usually June and December\n\nExam Mode: Computer Based Test\nExam Duration: 3 Hours\nTotal Marks: 200 Marks\n\nPaper Structure: Divided into Part A Part B and Part C\n\nPart A Name: General Aptitude\nPart A Focus: Quantitative aptitude logical reasoning graphical analysis\nPart A Strategy: Scoring section for candidates strong in basic math and logic\n\nPart B Name: Subject Knowledge Conventional\nPart B Focus: Standard theory based conceptual questions\nPart B Strategy: Tests core subject fundamentals\n\nPart C Name: Subject Knowledge Analytical\nPart C Focus: Application of scientific concepts to experiments and data\nPart C Importance: Highest weightage and main rank deciding section\nPart C Strategy: Attempt selected high confidence questions from large pool\n\nNegative Marking Rule: Usually 25 percent negative marking for wrong answers\nException Subject: Mathematical Sciences often has no negative marking in Part C\n\nSubject 1: Chemical Sciences including Organic Inorganic Physical Analytical Chemistry\nSubject 2: Earth Sciences including Geology Geophysics Oceanography Atmospheric Science\nSubject 3: Life Sciences including Botany Zoology Microbiology Genetics Bio'),
('MHT-CET', 'Type of Exam: State Level (Conducted by individual state agencies)\n\nPurpose: Eligibility for Assistant Professor Lectureship only\nValidity Scope: SET qualification is valid only in the state where you clear the exam\nExample Rule: Clearing MH SET allows teaching eligibility in Maharashtra and Goa only\nJRF Availability: SET does not provide Junior Research Fellowship in most states\n\nEligibility Education: Master’s Degree in relevant subject with minimum 55 percent marks (50 percent for SC ST OBC PwD)\nEligibility Status: Final year Master’s students are eligible\n\nExam Frequency: Varies by state usually once a year\n\nMajor Advantage 1: Generally easier than national level UGC NET\nMajor Advantage 2: Question paper often available in English and the respective state language\nMajor Advantage 3: Good backup option for candidates missing UGC NET cutoff\n\nExample State Exam 1: MH SET for Maharashtra and Goa\nExample State Exam 2: WB SET for West Bengal\nExample State Exam 3: K SET for Karnataka\nExample State Exam 4: G SET for Gujarat\nExample State Exam 5: TN SET for Tamil Nadu\nExample State Exam 6: AP SET and TS SET for Andhra Pradesh and Telangana\nExample State Exam 7: JK SET for Jammu and Kashmir\nExample State Exam 8: MP SET for Madhya Pradesh\nExample State Exam 9: NE SLET for North Eastern states\n\nExam Mode: Mostly Offline OMR based though some states shifting to CBT\nTotal Questions: 150 Questions\nTotal Marks: 300 Marks\nExam Duration: 3 Hours continuous\n\nPaper 1 Name: General Aptitude\nPaper 1 Questions: 50\nPaper 1 Marks: 100\nPaper 1 Syllabus: Teaching aptitude research aptitude reasoning environment ICT communication\n\nPaper 2 Name: Subject Specific Paper\nPaper 2 Questions: 100\nPaper 2 Marks: 200\nPaper 2 Syllabus: Based on candidate’s Master’s subject\n\nNegative Marking Rule: No negative marking in most SET exams\n\nAge Limit: No upper age limit\nValidity Period: Lifetime validity within the qualifying state\n\nDomicile Rule: Candidates from other states can usually apply\nReservation'),
('KCET', 'Type of Exam: State Level (Conducted by the State Common Entrance Test Cell Maharashtra)\nExam Name: MHT-CET (Maharashtra Common Entrance Test)\n\nPurpose 1: Admission to BE and BTech Engineering courses in Maharashtra\nPurpose 2: Admission to BPharm and PharmD courses\nPurpose 3: Admission to BSc Agriculture Horticulture and Forestry programs\n\nSeat Rule Maharashtra Domicile: 85 percent seats reserved for Maharashtra state candidates\nSeat Rule All India: 15 percent seats for All India candidates often through JEE Main\n\nEligibility Education: 12th Pass or Appearing in Science stream\nEligibility Group PCM: Required for Engineering\nEligibility Group PCB: Required for Pharmacy and Agriculture\n\nExam Frequency: Once per year\nExam Months: Usually April or May\n\nMajor Advantage 1: Only state entrance route to top Maharashtra engineering colleges\nMajor Advantage 2: No negative marking reduces risk\n\nExam Mode: Computer Based Test\nExam Duration: 3 Hours total\nSyllabus Weightage: 20 percent Class 11 and 80 percent Class 12 Maharashtra State Board syllabus\n\nMarking Scheme: No negative marking\nDifficulty Level: Easier than JEE Main but above board exam level\n\nEngineering Paper 1 Subject: Mathematics\nMaths Questions: 50\nMarks per Maths Question: 2 Marks\nMaths Total Marks: 100\nMaths Time Limit: 90 Minutes\n\nEngineering Paper 2 Subjects: Physics and Chemistry\nPhysics Questions: 50\nChemistry Questions: 50\nMarks per Question: 1 Mark\nPhysics Chemistry Total Marks: 100\nPhysics Chemistry Time Limit: 90 Minutes\nPaper Switching Rule: Physics Chemistry section opens only after Maths time ends\n\nTop College 1: COEP Technological University\nCOEP Percentile Target: 99.8 plus percentile for Computer Science and EnTC\n\nTop College 2: Veermata Jijabai Technological Institute\nVJTI Percentile Target: 99.7 plus percentile\n\nTop College 3: Sardar Patel Institute of Technology\nSPIT Percentile Target: Around 99.5 percentile\n\nTop College 4: Pune Institute of Computer Technology\nPICT Percentile Target: Around 99.4'),
('COMEDK UGET', 'Type of Exam: State Level (Conducted by the Karnataka Examinations Authority)\nExam Name: KCET (Karnataka Common Entrance Test)\n\nPurpose 1: Admission to BE and BTech Engineering colleges in Karnataka\nPurpose 2: Admission to BPharm and PharmD courses\nPurpose 3: Admission to Agriculture Horticulture Forestry Sericulture and related farm science programs\nPurpose 4: Admission to Veterinary and allied science courses\nImportant Medical Rule: MBBS BDS and AYUSH admissions are through NEET not KCET\n\nDomicile Rule General: Candidate must have studied in Karnataka for at least 7 years between Class 1 and 2nd PUC\nDomicile Special Categories: Includes Horanadu and Gadinadu Kannadigas defense personnel and central government employees\n\nEligibility Education: 12th Pass or Appearing in Science stream\nEligibility PCM: Required for Engineering\nEligibility PCB: Required for Pharmacy and Agriculture\nEligibility PCMB: Required if candidate wants both Engineering and Agriculture options\n\nExam Frequency: Once per year\nExam Month: Usually April\nTentative Exam Window 2026: 23 to 24 April 2026\n\nExam Mode: Offline OMR based\nTotal Questions: 180 Questions\nTotal Marks: 180 Marks\nMarking Scheme: +1 for correct answer and no negative marking\n\nDay 1 Morning Subject: Biology\nBiology Questions: 60\nBiology Duration: 80 Minutes\n\nDay 1 Afternoon Subject: Mathematics\nMaths Questions: 60\nMaths Duration: 80 Minutes\n\nDay 2 Morning Subject: Physics\nPhysics Questions: 60\nPhysics Duration: 80 Minutes\n\nDay 2 Afternoon Subject: Chemistry\nChemistry Questions: 60\nChemistry Duration: 80 Minutes\n\nKannada Language Test: Required only for Horanadu and Gadinadu Kannadiga candidates\nKannada Test Questions: 50\nKannada Test Level: Basic language proficiency\n\nEngineering Rank Rule: 50 percent KCET score plus 50 percent Class 12 PCM board marks\nAgriculture Rank Rule: 25 percent KCET plus 25 percent Class 12 marks plus 50 percent practical test\n\nTop College 1: R. V. College of Engineering\nRVCE Rank Target CSE ISE: Below 200'),
('WBJEE', 'Type of Exam: National level entrance (Conducted by the Consortium of Medical Engineering and Dental Colleges of Karnataka)\nExam Name: COMEDK UGET\n\nPurpose: Admission to BE and BTech programs in 150+ private engineering colleges in Karnataka\n\nTop College 1: R. V. College of Engineering\nTop College 2: BMS College of Engineering\nTop College 3: Ramaiah Institute of Technology\n\nSeat Category: Mainly for Non Karnataka quota seats in private colleges\nAdmission Basis: Purely merit based for All India candidates\n\nEligibility Education: 12th Pass or Appearing\nEligibility Stream: Science stream with Physics and Mathematics compulsory\nOptional Subject Rule: Third subject can be Chemistry Biotechnology Biology Computer Science or Electronics\nEnglish Requirement: English must be a compulsory subject in Class 12\n\nExam Frequency: Once per year\nExam Date 2026: 9 May 2026\n\nExam Mode: Computer Based Test\nExam Duration: 3 Hours (180 Minutes)\nTotal Questions: 180 Questions\nTotal Marks: 180 Marks\n\nMarking Scheme Correct: +1 Mark\nMarking Scheme Wrong: 0 Marks (No negative marking)\nZero Score Rule: Candidates scoring zero are not assigned a rank\n\nSection Physics Questions: 60\nSection Physics Difficulty: Moderate formula based\n\nSection Chemistry Questions: 60\nSection Chemistry Difficulty: Easy to moderate NCERT based\n\nSection Mathematics Questions: 60\nSection Mathematics Difficulty: Lengthy and calculus heavy\n\nSyllabus Weightage: About one third from Class 11 and two thirds from Class 12 CBSE syllabus\n\nTop Rank Target 1: RVCE CSE ISE rank under 150 to 400 (Score 160+)\nTop Rank Target 2: BMSCE rank under 400 to 1000\nTop Rank Target 3: MSRIT rank under 600 to 1300\nTop Rank Target 4: PES University accepts some COMEDK ranks around top 1000\nTop Rank Target 5: BMSIT and Dayananda Sagar rank under 2000 to 3500\n\nPreparation Strategy 1: Aim for 165+ marks since there is no negative marking\nPreparation Strategy 2: Practice full length tests to improve speed for 180 questions in 180 minutes\nPreparat'),
('GUJCET', 'Type of Exam: State Level (Conducted by the West Bengal Joint Entrance Examinations Board)\nExam Name: WBJEE (West Bengal Joint Entrance Examination)\n\nPurpose 1: Admission to Undergraduate Engineering and Technology programs in West Bengal\nPurpose 2: Admission to Pharmacy courses\nPurpose 3: Admission to Architecture courses\n\nTop Government College 1: Jadavpur University\nTop Government College 2: University of Calcutta\nTop Government College 3: Kalyani Government Engineering College\nTop Private College 1: Institute of Engineering and Management Kolkata\nTop Private College 2: Heritage Institute of Technology Kolkata\nTop Private College 3: Techno India Group colleges\n\nEligibility Education: 12th Pass or Appearing in Science stream\nDomicile Rule Government Colleges: Majority seats reserved for West Bengal domicile students\nDomicile Rule Private Colleges: Limited seats open for All India candidates\n\nExam Frequency: Once per year\nExam Month: Usually April\nTentative Exam Date 2026: 26 April 2026\n\nExam Mode: Offline OMR based\nTotal Marks: 200 Marks\nTotal Duration: 4 Hours (Two separate papers)\n\nPaper 1 Subject: Mathematics\nPaper 1 Marks: 100\nPaper 1 Time: 11:00 AM to 1:00 PM\n\nPaper 2 Subject: Physics and Chemistry\nPaper 2 Marks: 100\nPaper 2 Time: 2:00 PM to 4:00 PM\n\nCategory 1 Question Type: Single correct answer\nCategory 1 Marks: 1 Mark\nCategory 1 Negative Marking: −0.25\n\nCategory 2 Question Type: Single correct answer higher difficulty\nCategory 2 Marks: 2 Marks\nCategory 2 Negative Marking: −0.5\n\nCategory 3 Question Type: Multiple correct answers\nCategory 3 Marks: 2 Marks\nCategory 3 Negative Marking: No negative marking\nCategory 3 Partial Marking Rule: Partial marks awarded if some correct options selected without choosing wrong ones\n\nTop Rank Target Jadavpur University CSE IT: Rank within 10 to 100\nTop Rank Target Jadavpur University Core Branches: Rank within 500\nTypical Safe Score for JU Top Branches: Around 120 plus out of 200\n\nTop Rank Target Calcutta University: Rank '),
('AP EAPCET', 'Type of Exam: State Level (Conducted by the Gujarat Secondary and Higher Secondary Education Board)\nExam Name: GUJCET (Gujarat Common Entrance Test)\n\nPurpose 1: Admission to BE and BTech Engineering colleges in Gujarat\nPurpose 2: Admission to BPharm and DPharm programs\n\nAdmission Authority: ACPC (Admission Committee for Professional Courses Gujarat)\n\nMerit Formula Rule: Final merit is calculated using Board Exam Percentile plus GUJCET Percentile\nStandard Weightage: 50 percent Board Marks and 50 percent GUJCET Score\nPossible Variation: Ratio sometimes changed to 60:40 as per state policy updates\n\nDomicile Rule: Majority seats in government colleges reserved for Gujarat domicile candidates\nEligibility Education: 12th Pass or Appearing in Science stream\nEligibility Groups: Group A PCM for Engineering Group B PCB for Pharmacy Group AB for both\n\nExam Frequency: Once per year\nExam Month: March or April\nExam Date 2026: 29 March 2026\n\nExam Mode: Offline OMR based\nExam Duration: 3 Hours total\nTotal Questions: 120 Questions\nTotal Marks: 120 Marks\n\nMarking Scheme Correct: +1 Mark\nMarking Scheme Wrong: −0.25 Mark\n\nSession 1 Subjects: Physics and Chemistry\nPhysics Questions: 40\nChemistry Questions: 40\nSession 1 Duration: 120 Minutes\nSession 1 Total Marks: 80\n\nSession 2 Subject: Mathematics or Biology\nSession 2 Questions: 40\nSession 2 Duration: 60 Minutes\nSession 2 Total Marks: 40\n\nSyllabus Rule: Questions mainly from Class 12 NCERT and Gujarat Board syllabus\nClass 11 Weightage: Very minimal direct questions\n\nTop College 1: Dhirubhai Ambani Institute of Information and Communication Technology\nDAIICT Admission Split: Gujarat quota through GUJCET and All India quota through JEE Main\nDAIICT Rank Target Gujarat: Top 50 to 150 state rank\n\nTop College 2: Nirma University\nNirma Admission Split: GUJCET via ACPC plus JEE Main quota\n\nTop Government College: L. D. College of Engineering\nLDCE Rank Target for CS IT: Within top 500\n\nTop Grant in Aid College: Birla Vishvakarma Mahavidyalaya\n\nO'),
('TS EAMCET', 'Type of Exam: State Level (Conducted by Jawaharlal Nehru Technological University Kakinada on behalf of APSCHE)\nExam Name: AP EAPCET (Engineering Agriculture and Pharmacy Common Entrance Test)\n\nPurpose 1: Admission to BTech Engineering programs in Andhra Pradesh\nPurpose 2: Admission to Agriculture Pharmacy Veterinary and Fisheries courses\nMedical Note: MBBS BDS and AYUSH admissions are through NEET not EAPCET\n\nMerit Formula Rule: Final rank based on entrance score plus board exam marks\nWeightage Formula 2026: 75 percent EAPCET score plus 25 percent Intermediate board group subject marks\n\nEligibility Education: 12th Pass or Appearing in Science stream\nLocal Reservation Rule: 85 percent seats reserved for Andhra Pradesh local candidates\nUnreserved Seats: 15 percent seats open to Telangana and other state candidates\n\nExam Frequency: Once per year\nExam Month: Usually May\nExam Dates 2026 Engineering: 12 May to 18 May\nExam Dates 2026 Agriculture and Pharmacy: 19 May to 20 May\n\nExam Mode: Computer Based Test\nExam Duration: 3 Hours (180 Minutes)\nTotal Questions: 160 Questions\nTotal Marks: 160 Marks\n\nMarking Scheme Correct: +1 Mark\nMarking Scheme Wrong: No negative marking\n\nSection Mathematics or Biology Questions: 80\nSection Physics Questions: 40\nSection Chemistry Questions: 40\n\nMaths Biology Suggested Time: About 85 minutes\nPhysics Suggested Time: About 40 minutes\nChemistry Suggested Time: About 35 minutes\n\nApprox Score 120 plus: Rank under 1,000\nApprox Score 100 to 119: Rank under 5,000\nApprox Score 80 to 99: Rank under 15,000\nApprox Score 60 to 79: Rank under 40,000\nQualifying Marks General: 40 out of 160\n\nTop College 1: JNTU College of Engineering Kakinada\nTarget Rank for CSE: Around 500 to 1,500\n\nTop College 2: Andhra University College of Engineering\nTarget Rank for CSE: Around 800 to 2,000\n\nTop Private College 1: Gayatri Vidya Parishad College of Engineering\nTarget Rank: Around 3,000\n\nTop College 3: Sri Venkateswara University College of Engineering\nTarget Rank: Arou'),
('KEAM', 'Type of Exam: State Level (Conducted by Jawaharlal Nehru Technological University Hyderabad on behalf of TGCHE)\nExam Name: TG EAPCET (Engineering Agriculture and Pharmacy Common Entrance Test)\n\nPurpose 1: Admission to BE and BTech engineering colleges in Telangana\nPurpose 2: Admission to Pharmacy Agriculture Veterinary and related courses\n\nEligibility Education: 12th Pass or Appearing in Science stream\nLocal Reservation Rule: 85 percent seats reserved for Telangana local candidates\nUnreserved Seats: 15 percent seats open to Andhra Pradesh and other state candidates\n\nExam Frequency: Once per year\nExam Month: Usually May\nExpected Engineering Exam Dates 2026: 9 May to 11 May\n\nExam Mode: Computer Based Test\nExam Duration: 3 Hours (180 Minutes)\nTotal Questions: 160 Questions\nTotal Marks: 160 Marks\n\nMarking Scheme Correct: +1 Mark\nMarking Scheme Wrong: No negative marking\n\nSection Mathematics or Biology Questions: 80\nSection Physics Questions: 40\nSection Chemistry Questions: 40\n\nMaths Biology Importance: 50 percent of total paper and main rank deciding section\nPhysics Nature: Usually toughest section\nChemistry Nature: Easiest and scoring section\n\nApprox Score 100 to 160: Rank under 1,000 to 2,000\nApprox Score 80 to 99: Rank under 2,000 to 8,000\nApprox Score 60 to 79: Rank under 8,000 to 20,000\nQualifying Marks General: 40 out of 160\n\nTop College 1: JNTU College of Engineering Hyderabad\nTarget Rank for CSE: Under 500\n\nTop College 2: Osmania University College of Engineering\nTarget Rank for CSE: Under 800\n\nTop Private College 1: Chaitanya Bharathi Institute of Technology\nTarget Rank: Under 1,500\n\nTop Private College 2: VNR Vignana Jyothi Institute of Engineering and Technology\nTarget Rank: Under 2,000\n\nTop Private College 3: Vasavi College of Engineering\nTarget Rank: Under 2,500\n\nPreparation Strategy 1: Focus heavily on Mathematics especially Calculus Vectors and Coordinate Geometry\nPreparation Strategy 2: Attempt all questions due to absence of negative marking\nPreparation'),
('TANCET', 'Type of Exam: State Level (Conducted by the Commissioner for Entrance Examinations Kerala)\nExam Name: KEAM (Kerala Engineering Architecture Medical Entrance Exam)\n\nMajor Update 2026 Mode Change: Exam shifted from OMR to Computer Based Test\nExam Window 2026: 17 April to 23 April\nRegistration Last Date: 6 February 2026\n\nPurpose 1: Admission to BTech Engineering colleges in Kerala\nPurpose 2: Admission to BPharm courses\nPurpose 3: Architecture admission through NATA score but KEAM registration required for counseling\nPurpose 4: MBBS BDS AYUSH via NEET score but KEAM registration required for state quota counseling\n\nRank Formula Engineering: 50 percent KEAM entrance score plus 50 percent Class 12 board marks in Physics Chemistry Mathematics\n\nEligibility Education: 12th Pass or Appearing in Science stream\nDomicile Priority: Keralite category gets main reservation benefits\nNon Keralite Eligibility: Can compete for merit seats mainly in private colleges\n\nExam Mode: Computer Based Test\nExam Duration: 3 Hours (180 Minutes)\nTotal Questions Engineering: 150 Questions\nTotal Marks Engineering: 600 Marks\n\nMarking Scheme Correct: +4 Marks\nMarking Scheme Wrong: −1 Mark\n\nMathematics Questions: 75\nMathematics Marks: 300\nMathematics Weightage: 50 percent of paper\n\nPhysics Questions: 45\nPhysics Marks: 180\nPhysics Weightage: 30 percent\n\nChemistry Questions: 30\nChemistry Marks: 120\nChemistry Weightage: 20 percent\n\nBPharm Exam Pattern: Physics and Chemistry only\nBPharm Questions: 75\nBPharm Duration: 90 Minutes\n\nScore Normalization Rule: Entrance scores normalized if multiple shifts conducted\nBoard Marks Standardization: Board marks scaled across Kerala Board CBSE ISC to equalize scoring\nFinal Rank Basis: Combined normalized entrance score plus standardized board marks\n\nTop Government College 1: College of Engineering Trivandrum\nTarget Rank CET: Under 1,000\n\nTop Aided College: TKM College of Engineering Kollam\nTarget Rank TKM: Under 2,500\n\nTop College for CSE Placements: Model Engineering C'),
('OJEE', 'Type of Exam: State Level (Conducted by Anna University on behalf of the Government of Tamil Nadu)\nExam Name: TANCET (Tamil Nadu Common Entrance Test)\n\nPurpose: Admission to MBA and MCA postgraduate programs in Tamil Nadu\n\nParticipating Colleges: Government Engineering Colleges University Departments and Self Financing Institutions\nTop Government Campus: College of Engineering Guindy\nOther Anna University Campuses: ACT SAP MIT\nTop Private College 1: PSG College of Technology\nTop Private College 2: SSN School of Management\nTop Private College 3: Thiagarajar School of Management\n\nEligibility Education: Bachelor’s Degree of minimum three years duration with 50 percent marks (45 percent for reserved categories)\nNativity Rule: Open to other state candidates but reservation preference usually for Tamil Nadu residents\n\nExam Frequency: Once per year\nExam Month: Usually March\n\nExam Mode: Offline OMR based\nExam Duration: 2 Hours (120 Minutes)\nTotal Questions: 100 Questions\nTotal Marks: 100 Marks\n\nMarking Scheme Correct: +1 Mark\nMarking Scheme Wrong: −1/3 Mark\n\nMBA Section 1: Analysis of Business Situations 20 Questions\nMBA Section 2: Reading Comprehension 20 Questions\nMBA Section 3: Quantitative Ability 20 Questions\nMBA Section 4: Data Sufficiency 20 Questions\nMBA Section 5: English Usage 20 Questions\n\nMCA Section 1: Quantitative Ability 25 Questions\nMCA Section 2: Analytical Reasoning 25 Questions\nMCA Section 3: Logical Reasoning 25 Questions\nMCA Section 4: Computer Awareness 25 Questions\n\nTop Score Target CEG MBA: Around 55 to 60 plus out of 100\nTop Score Target PSG MBA: Around 50 to 55 plus\nTop Score Target SSN MBA: Around 45 to 50 plus\n\nPreparation Strategy 1: Focus on accuracy due to high negative marking\nPreparation Strategy 2: Practice business case study questions for MBA\nPreparation Strategy 3: Be cautious in Data Sufficiency questions to avoid negative marks\nPreparation Strategy 4: MCA aspirants should master basic computer fundamentals\nPreparation Strategy 5: Remem'),
('BCECE', 'Type of Exam: State Level (Conducted by the Odisha Joint Entrance Examination Committee)\nExam Name: OJEE (Odisha Joint Entrance Examination)\n\nPurpose 1: Lateral Entry admission to 2nd Year BTech and BPharm\nPurpose 2: Admission to MBA MCA MTech MPharm MArch MPlan\nPurpose 3: Admission to BPharm Integrated MBA and B.CAT programs\n\nDomicile Rule: Odisha residents get priority access to government colleges\nOutside State Rule: Non Odisha candidates mainly eligible for private colleges and special OJEE seats\n\nExam Frequency: Once per year\nApplication Window 2026: Opened 28 January 2026 and closes 22 March 2026\nExam Dates 2026: Tentatively 4 May to 9 May\n\nExam Mode: Computer Based Test\nMarking Scheme: +4 for correct answer and −1 for wrong answer\n\nLE BTech Duration: 2 Hours\nLE BTech Total Questions: 120\nLE BTech Subjects: Engineering Mathematics 40 Engineering Mechanics 40 Basic Electrical Engineering 40\n\nMBA Duration: 2 Hours\nMBA Total Questions: 120\nMBA Section Quantitative Techniques: 30\nMBA Section Analytical and Logical Reasoning: 30\nMBA Section Verbal Reasoning and Comprehension: 30\nMBA Section General Awareness and Business Fundamentals: 30\n\nMCA Duration: 2 Hours\nMCA Total Questions: 120\nMCA Section Mathematics: 60\nMCA Section Computer Awareness: 60\n\nBPharm Duration: 3 Hours\nBPharm Total Questions: 120\nBPharm Sections: Physics 40 Chemistry 40 Biology or Mathematics 40\n\nTop Government College 1: Odisha University of Technology and Research\nTop Government College 2: Veer Surendra Sai University of Technology\nTop Government College 3: Indira Gandhi Institute of Technology Sarang\nTop University for MBA MCA: Utkal University\n\nLE BTech Strategy: Strengthen Engineering Mechanics and Basic Electrical which are common for all diploma branches\nMCA Strategy: Focus on C programming Data Structures and Digital Logic for high scoring\nMBA Strategy: Prepare static GK and business awareness along with aptitude\nBackup Advice: Even with low JEE Main score candidates should register for '),
('JCECE', 'Type of Exam: State Level (Conducted by the Bihar Combined Entrance Competitive Examination Board)\nExam Name: BCECE (Bihar Combined Entrance Competitive Examination)\n\nCritical Admission Rule Engineering: BTech admission handled through JEE Main via UGEAC counseling\nCritical Admission Rule Medical: MBBS BDS admission handled through NEET via UGMAC counseling\nBCECE Entrance Applies To: Agriculture Pharmacy Nursing Paramedical Fisheries and Dairy courses\n\nPurpose 1: Admission to BSc Agriculture Horticulture Forestry programs\nPurpose 2: Admission to BPharma\nPurpose 3: Admission to BSc Nursing Physiotherapy Occupational Therapy Lab Technology\nPurpose 4: Admission to Fisheries and Dairy Technology courses\n\nDomicile Rule: Primarily for Bihar residents with permanent residence proof\nEligibility Education: 12th Pass or Appearing in Science stream\nEligible Subject Groups: PCM PCB PCMB or Agriculture stream\n\nExam Frequency: Once per year\nApplication Period 2026: Likely from May 2026\nExam Month 2026: Mid July\n\nExam Mode: Offline OMR based\nExam Duration Per Subject: 90 Minutes\nExam Structure: Separate paper for each chosen subject with breaks in between\nQuestions Per Subject: 100\nMarks Per Subject: 400\n\nMarking Scheme Correct: +4 Marks\nMarking Scheme Wrong: −1 Mark\n\nGroup PCM: Physics Chemistry Mathematics for Pharmacy Dairy and Agriculture Engineering related courses\nGroup PCB: Physics Chemistry Biology for Nursing Pharmacy and Agriculture\nGroup CBA or PCA: Chemistry Biology or Math plus Agriculture subject\n\nTop Agriculture University 1: Bihar Agricultural University Sabour\nTop Agriculture College 2: Bhola Paswan Shastri Agricultural College Purnea\nTop Agriculture College 3: Dr Kalam Agricultural College Kishanganj\n\nTop Pharmacy College 1: Muzaffarpur Institute of Technology\nTop Pharmacy Institute 2: Government Pharmacy Institute Patna\n\nTop Nursing Colleges: NMCH Patna DMCH Darbhanga JLNMCH Bhagalpur\n\nAgriculture Strategy Tip: Students with Agriculture subject should choose Agr'),
('CG PET', 'Type of Exam: State Level (Conducted by the Jharkhand Combined Entrance Competitive Examination Board)\nExam Name: JCECE (Jharkhand Combined Entrance Competitive Examination)\n\nPurpose 1: Admission to BSc Agriculture Forestry and Horticulture\nPurpose 2: Admission to BVSc and AH Veterinary course\nPurpose 3: Admission to BFSc Fisheries\nPurpose 4: Admission to BTech Dairy Technology and Agricultural Engineering\n\nDomicile Rule: Only Jharkhand residents with Local Resident Certificate eligible\nEligibility Education: 12th Pass or Appearing in Science stream\n\nExam Frequency: Once per year\nApplication Period 2026: Likely from April 2026\nExam Month 2026: May or June\n\nExam Mode: Offline OMR based\n\nPCM Group Questions: 150\nPCM Subjects: Physics 50 Chemistry 50 Mathematics 50\nPCM Duration: 2.5 Hours\nPCM Eligible Courses: Agriculture Forestry Dairy Technology Agricultural Engineering\n\nPCB Group Questions: 150\nPCB Subjects: Physics 50 Chemistry 50 Biology 50\nPCB Duration: 2.5 Hours\nPCB Eligible Courses: Agriculture Veterinary Fisheries\n\nPCMB Group Questions: 200\nPCMB Subjects: Physics Chemistry Mathematics Biology 50 each\nPCMB Duration: 3.5 Hours\nPCMB Eligible Courses: All courses listed above\n\nMarking Scheme Correct: +1 Mark\nMarking Scheme Wrong: −0.25 Mark\n\nMain University: Birsa Agricultural University\n\nTop Veterinary College: Ranchi Veterinary College\nTop Agriculture College: College of Agriculture BAU Ranchi\nTop Forestry College: College of Forestry BAU Ranchi\nTop Dairy College: Dairy Technology College Hansdiha Dumka\n\nSafe Score Veterinary: 110 plus out of 150 in PCB group\nSafe Score Agriculture Govt Seat: 90 to 100 plus\nSafe Score Forestry Fisheries: 70 to 80 plus\n\nPreparation Strategy 1: PCMB students should choose PCMB group to maximize course options\nPreparation Strategy 2: Focus strongly on Physics formulas since Physics differentiates ranks\nPreparation Strategy 3: Prepare Biology and Chemistry from NCERT for easy scoring\nEngineering Note: Admission to BIT Sindri enginee'),
('HP CET', 'Type of Exam: State Level (Conducted by the Chhattisgarh Professional Examination Board also known as CG Vyapam)\nExam Name: CG PET (Chhattisgarh Pre Engineering Test)\n\nPurpose 1: Admission to BE and BTech engineering colleges in Chhattisgarh\nPurpose 2: Admission to Dairy Technology and Agricultural Engineering programs\n\nDomicile Rule: Chhattisgarh domicile required for most government college seats\nAll India Seats: Limited private college seats for outside state candidates usually through JEE Main not CG PET\n\nExam Frequency: Once per year\nExam Month: Usually May\nTentative Exam Date 2026: 14 May 2026\n\nExam Mode: Offline Pen and Paper OMR\nExam Duration: 3 Hours (180 Minutes)\nTotal Questions: 150 Questions\nTotal Marks: 150 Marks\n\nMarking Scheme Correct: +1 Mark\nMarking Scheme Wrong: No negative marking\n\nPhysics Questions: 50\nChemistry Questions: 50\nMathematics Questions: 50\n\nPhysics Difficulty: Moderate formula and theory based\nChemistry Difficulty: Easy and mostly NCERT based\nMathematics Difficulty: Lengthy and calculation heavy\n\nTop Government College 1: Government Engineering College Raipur\nTarget Score GEC Raipur CSE: Around 85 to 100 plus\n\nTop Government College 2: Government Engineering College Bilaspur\nTarget Score: Around 80 to 95\n\nTop Private College 1: Bhilai Institute of Technology Durg\nTarget Score: Around 75 to 90\n\nTop Government College 3: Government Engineering College Jagdalpur\nTarget Score: Around 65 to 75\n\nTop Private College 2: Shri Shankaracharya Technical Campus Bhilai\nTarget Score: Around 60 to 70\n\nSyllabus Coverage: Based on Class 11 and 12 syllabus from CG Board and CBSE\nWeightage Split: Approx 40 percent Class 11 and 60 percent Class 12\n\nPreparation Strategy 1: Strengthen Chemistry for fast and high scoring\nPreparation Strategy 2: Improve Mathematics calculation speed\nPreparation Strategy 3: Attempt all 150 questions due to absence of negative marking\nPreparation Strategy 4: Practice OMR based mock tests for time management'),
('UKSEE', 'Type of Exam: State Level (Conducted by Himachal Pradesh Technical University)\nExam Name: HP CET (Himachal Pradesh Common Entrance Test)\n\nPurpose 1: Admission to BTech and BPharmacy state quota seats in Himachal Pradesh\nPurpose 2: Admission to MCA and MBA programs in HPTU affiliated colleges\n\nAdmission Route 1: JEE Main ranks given first priority for BTech government college seats\nAdmission Route 2: HP CET ranks used to fill vacant seats after JEE Main list\nVerdict Rule: JEE Main is primary pathway and HP CET acts as backup for state candidates\n\nDomicile Rule: Mainly for Himachal Pradesh bonafide residents to claim 85 percent state quota\nEligibility Education: 12th Pass or Appearing in Science stream\n\nExam Frequency: Once per year\nExam Month: Usually May\nTentative Exam Date 2026: 10 May 2026\n\nExam Mode: Offline Pen and Paper OMR\nExam Duration: 3 Hours 15 Minutes\nTotal Questions: 150 Questions\nTotal Marks: 600 Marks\n\nMarking Scheme Correct: +4 Marks\nMarking Scheme Wrong: −1 Mark\n\nPhysics Questions: 50\nChemistry Questions: 50\nMathematics or Biology Questions: 50\n\nPhysics Level: Moderate formula based\nChemistry Level: Easy and mostly NCERT based\nMathematics Level: Lengthy but easier than JEE Main\n\nPossible Pattern Variation: Section A compulsory and Section B optional style similar to JEE Main in recent cycles\n\nTop Government College 1: Jawaharlal Nehru Government Engineering College Sundernagar\nTarget Rank HP CET: Top 100 to 200\n\nTop Government College 2: Atal Bihari Vajpayee Government Institute of Engineering and Technology\nTarget Rank: Top 300\n\nTop Government College 3: Rajiv Gandhi Government Engineering College Kangra\nTarget Rank: Top 400\n\nTop University Campus: Himachal Pradesh Technical University\n\nPreparation Strategy 1: Prioritize JEE Main preparation along with HP CET\nPreparation Strategy 2: Focus on NCERT Chemistry for easy scoring\nPreparation Strategy 3: Practice time management due to large number of questions\nPreparation Strategy 4: PCB students should c'),
('LPU NEST', 'Major Update: The old UKSEE entrance exam has been discontinued. There is no separate state entrance test for 2026. “UKSEE” now refers only to the centralized counseling process.\n\nConducting Authority: Veer Madho Singh Bhandari Uttarakhand Technical University (UTU), Dehradun\nOfficial Website: uktech.ac.in\n\nCourses Covered Under Counseling\n• B.Tech (First Year and Lateral Entry)\n• B.Pharm (First Year and Lateral Entry)\n• MBA, MCA\n• M.Tech, M.Pharm\n• BHMCT (Hotel Management)\n\nCounseling Start Time: Usually June 2026\n\nNew Admission Routes (No Entrance Exam)\n\nB.Tech First Year\nPriority 1: JEE Main Rank\nPriority 2: Class 12 Merit (only for vacant seats)\n\nB.Tech Lateral Entry\nAdmission based on Diploma or B.Sc marks (no entrance exam)\n\nB.Pharm First Year\nAdmission mainly based on Class 12 PCB/PCM marks\n(Some institutes may consider CUET, but UTU counseling is largely merit based)\n\nB.Pharm Lateral Entry\nBased on D.Pharm marks\n\nMBA\nCAT / MAT / CMAT score preferred\nVacant seats filled using Graduation merit\n\nMCA\nCUET-PG score or Graduation merit\n\nM.Tech\nGATE score\n\nTop Government Colleges Under UTU Counseling\n\nCollege of Technology Pantnagar\nStatus: Most prestigious government option\nAdmission: Strictly through JEE Main\nSafe JEE Rank Target: Approx 50,000 – 1,00,000 AIR\n\nGB Pant Institute of Engineering and Technology Pauri Garhwal\nAutonomous government institute located in the hills\nAdmission: JEE Main\n\nBipin Tripathi Kumaon Institute of Technology Dwarahat\nTop government college in Kumaon region\nAdmission: JEE Main\n\nTHDC Institute of Hydropower Engineering and Technology Tehri\nSpecial focus on Hydro, Electrical and Civil branches\n\nInstitute of Technology UTU Dehradun\nLocated near Sudhowala, Dehradun\n\nSpot Counseling Opportunity (Very Important)\n\nSince there is no entrance exam now, UTU conducts a Spot Round (usually August).\n\nHow it works\nIf government college seats remain vacant after JEE-based rounds, they may be filled using Class 12 percentage.\n\nBest Strategy\nIf your ');
INSERT INTO `exams` (`exam_name`, `detail`) VALUES
('UPSC', 'Type of Exam: University Level (Conducted by Lovely Professional University, Jalandhar, Punjab)\n\n🎯 Purpose of the Exam\n\nUsed for Admission + Scholarship to most programs at LPU, especially:\n\nB.Tech (CSE, ECE, Mechanical, etc.)\n\nMBA, BBA\n\nLaw\n\nHotel Management\n\nDesign\n\nAgriculture\n\n👩‍🎓 Who Can Apply?\n\nEducation: 12th Pass/Appearing\n\nTypical Requirement for B.Tech: ~60% aggregate in qualifying exam\n\nEligibility: Open to students from all over India and abroad\n\n📅 When Is It Conducted?\n\nHeld in multiple phases throughout the year\n\nCurrent Important Phase: Jan–Feb 2026 (Phase 1)\n\n⚠️ Scholarship reduces in later phases — Phase 1 offers the highest fee waiver\n\n💰 Why This Exam Matters\nScholarships\n\nLPU tuition fees are high (can reach ₹1.5 lakh+ per semester).\nLPUNEST is the main way to get 30%–60% fee waiver.\n\nPlacements\n\nKnown for mass recruiters like Cognizant, Capgemini\n\nPublicizes very high packages (often international/off-campus)\n\nRealistic average for most students: ₹5–7 LPA\n\n🧠 Exam Pattern (B.Tech)\n\nFormat: Computer-Based Test (CBT)\nModes Available:\n\nTest Centre Based\n\nOnline Remotely Proctored (from home with webcam)\n\nDuration: 2 Hours 30 Minutes\nTotal Questions: 100\nTotal Marks: 400\n\nMarking Scheme:\n\nCorrect Answer: +4 Marks\n\nWrong Answer: 0 Marks (No Negative Marking)\n👉 Attempt every question\n\nSection Breakdown\nSection	Questions	Marks	Level\nPhysics	25	100	Easy JEE Main level\nChemistry	25	100	NCERT based\nMaths / Biology	25	100	Class 11–12\nEnglish	25	100	Grammar & RC\nTotal	100	400	—\n\nQuestion Types: Mostly MCQs; some fill-in-the-blank (no options)\n\n🎓 Scholarship Categories (Approx)\nCategory	Fee Waiver	Estimated Score (out of 400)\nCategory 1	60%	300+\nCategory 2	50%	250–300\nCategory 3	40%	200–250\nCategory 4	30%	150–200\n\n✅ High scholarship = LPU becomes affordable\n❌ No scholarship = expensive compared to ROI\n\n🏫 Ground Reality\nCampus & Crowd\n\nHuge student population (30,000+).\nYou’ll find:\n\nSerious coders and achievers\n\nStudents treating it casually\n\nSuccess depends o'),
('GPSC', 'Type of Exam: National Level\nConducted By: Union Public Service Commission\n\nFor Which Posts: Recruitment to 24 Civil Services of India\n\nMajor Services Include:\n\nIndian Administrative Service (IAS)\n\nIndian Police Service (IPS)\n\nIndian Forest Service (IFoS)\n\nIndian Foreign Service (IFS)\n\nIndian Revenue Service (IRS)\n\nIndian Railway Management Service (IRMS)\n\nFor Whom:\nEducation: Bachelor’s Degree in any stream (Final year students can apply for Prelims)\n\nAge Limit (as on August 1, 2026):\nGeneral/EWS: 21–32 Years (6 Attempts)\nOBC: 21–35 Years (9 Attempts)\nSC/ST: 21–37 Years (Unlimited Attempts)\n\nWhy This Exam:\nPower & Impact: Officers directly implement government policies\nPrestige: High social respect and authority\nJob Security: Constitutional protection\n\nExam Pattern – Three Stages\nStage 1: Preliminary Examination\n\nDate: May 24, 2026\nType: Objective (MCQ)\nNegative Marking: 1/3rd mark deducted for each wrong answer\n\nPaper 1: General Studies\nSubjects: History, Polity, Geography, Economy, Environment, Science & Tech, Current Affairs\nQuestions: 100\nMarks: 200\nPurpose: Decides cutoff (Target Score: 90–100)\n\nPaper 2: CSAT (Qualifying Only)\nSubjects: Maths, Reasoning, Reading Comprehension\nQuestions: 80\nMarks: 200\nQualifying Marks: 66 (33%)\n\nStage 2: Mains Examination\n\nStarting Date: August 21, 2026\nType: Descriptive (Written)\nTotal Marks: 1750\n\nEssay Paper – 250 Marks\n\nGS Paper I – 250 Marks\nHistory, Society, Geography\n\nGS Paper II – 250 Marks\nPolity, Governance, International Relations\n\nGS Paper III – 250 Marks\nEconomy, Environment, Science & Tech, Security\n\nGS Paper IV – 250 Marks\nEthics, Integrity, Aptitude\n\nOptional Subject Paper I – 250 Marks\nOptional Subject Paper II – 250 Marks\n\nQualifying Papers:\nEnglish + One Indian Language (300 Marks, 25% needed to pass)\n\nStage 3: Personality Test (Interview)\n\nMarks: 275\nFocus: Personality, decision-making ability, awareness, confidence, integrity\n\nImportant Strategies\n\nCSAT Preparation is Essential: Many candidates fail due to '),
('', 'Type of Exam: State Level\nConducted By: Gujarat Public Service Commission (GPSC)\n\nFor Which Posts\n\nClass 1 (Top Administrative Posts)\nDeputy Collector (GAS)\nDeputy Superintendent of Police (GPS)\nDistrict Registrar\n\nClass 2 (Executive & Administrative Posts)\nMamlatdar\nTaluka Development Officer (TDO)\nSection Officer (SO)\nState Tax Inspector (STI)\n\nFor Whom\n\nEducation: Bachelor’s Degree in any stream from a recognized university\n\nLanguage Requirement: Must know Gujarati (Reading, Writing, Speaking)\nNote: Mains includes a compulsory Gujarati Descriptive Paper\n\nAge Limit:\nGeneral: 20–35 Years\nReserved Categories (SEBC/SC/ST/EWS) & Women: +5 Years relaxation\nMaximum Age Limit usually extends up to 45 Years after relaxations\n\nExam Frequency\n\nUsually once a year, but the cycle is often delayed compared to UPSC\n\nExam Pattern – “Mini UPSC” Model\n\nGPSC follows a UPSC-style structure with strong Gujarat-specific focus.\n\nStage 1: Preliminary Examination\n\nType: Objective (MCQ)\nTotal Marks: 400 (200 + 200)\nDuration: 3 Hours per paper\nNegative Marking: 0.33 per wrong answer\n\nPaper 1 – General Studies (200 Marks)\nHistory (India + Gujarat)\nCultural Heritage (India + Gujarat)\nIndian Constitution & Polity\nMathematics & Reasoning\n\nPaper 2 – General Studies (200 Marks)\nEconomy (India + Gujarat)\nGeography (India + Gujarat)\nScience & Technology\nCurrent Affairs\n\nStage 2: Mains Examination\n\nType: Descriptive (Written)\nTotal Marks: 900\nMedium: English or Gujarati (except language papers)\n\nPaper 1 – Gujarati Language (150 Marks)\nGrammar, Precis Writing, Translation, Letter/Report Writing\n\nPaper 2 – English Language (150 Marks)\nGrammar, Comprehension, Writing Skills\n\nPaper 3 – Essay (150 Marks)\n3 Essays on social/current topics\n\nPaper 4 – GS 1 (150 Marks)\nHistory, Culture, Geography\n\nPaper 5 – GS 2 (150 Marks)\nPolity, Public Administration, Ethics\n\nPaper 6 – GS 3 (150 Marks)\nEconomy, Science & Tech, Current Affairs\n\nStage 3: Interview\n\nMarks: 100\nFocus: Personality, leadership, awareness of Gu');
INSERT INTO `favourite_careers` (`id`, `user_id`, `user_name`, `favourite_career`) VALUES
(90, 1, 'bhavya', '{\"career\": \"Chemistry\", \"title\": \"Science & Research (PCM)\", \"description\": \"\\n\\n        <h5>\\ud83d\\udccc Basic Introduction</h5>\\n        <p>\\n          Science &amp; Research is an academic and research-focused career path for PCM students.\\n          It emphasizes deep understanding of Physics, Chemistry, and Mathematics through\\n          theory, experiments, and analysis.\\n        </p>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83d\\udccb Key Details</h5>\\n        <ul>\\n          <li><strong>Degree Type:</strong> B.Sc / Integrated M.Sc</li>\\n          <li><strong>Duration:</strong> 3 \\u2013 5 Years</li>\\n          <li><strong>Stream:</strong> Pure Science (PCM)</li>\\n          <li><strong>Mode:</strong> Full-Time</li>\\n          <li><strong>Focus:</strong> Concepts, research, experiments</li>\\n        </ul>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83c\\udfaf Specializations</h5>\\n        <ul>\\n          <li>Physics</li>\\n          <li>Chemistry</li>\\n          <li>Mathematics</li>\\n          <li>Statistics</li>\\n          <li>Data Science (Science route)</li>\\n        </ul>\\n\\n        <h5 class=\\\"mt-4\\\">\\u2705 Eligibility</h5>\\n        <ul>\\n          <li>Passed 12th with <strong>PCM</strong></li>\\n          <li>Strong interest in theory &amp; problem-solving</li>\\n        </ul>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83d\\udcdd Entrance Exams</h5>\\n        <ul>\\n          <li>CUET (UG)</li>\\n          <li>University-level science entrance exams</li>\\n          <li>IISER Aptitude Test (for top institutes)</li>\\n        </ul>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83d\\udcbc Career Options</h5>\\n        <ul>\\n          <li>Research Scientist</li>\\n          <li>Professor / Lecturer</li>\\n          <li>Scientific Officer</li>\\n          <li>Lab Analyst</li>\\n          <li>Data Scientist (Research-based)</li>\\n        </ul>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83d\\udcb0 Salary Info</h5>\\n        <ul>\\n          <li><strong>Freshers:</strong> \\u20b93 \\u2013 5 LPA</li>\\n          <li><strong>After PhD:</strong> \\u20b98 \\u2013 15+ LPA</li>\\n        </ul>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83c\\udfdb\\ufe0f Government Scope</h5>\\n        <p>\\n          Very strong government scope in ISRO, DRDO, CSIR, IISc,\\n          government universities, and national research laboratories.\\n        </p>\\n\\n        <h5 class=\\\"mt-4\\\">\\u2696\\ufe0f Private vs Government Comparison</h5>\\n        <table class=\\\"table table-bordered\\\">\\n          <tbody><tr>\\n            <th>Aspect</th>\\n            <th>Private</th>\\n            <th>Government</th>\\n          </tr>\\n          <tr>\\n            <td>Salary Growth</td>\\n            <td>Moderate</td>\\n            <td>Stable</td>\\n          </tr>\\n          <tr>\\n            <td>Job Security</td>\\n            <td>Medium</td>\\n            <td>High</td>\\n          </tr>\\n        </tbody></table>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83c\\udf93 Internship Importance</h5>\\n        <p>\\n          Research internships are crucial for PhD admissions, skill development,\\n          and scientific exposure.\\n        </p>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83e\\udded Career Path Flow</h5>\\n        <p>\\n          12th PCM \\u2192 B.Sc \\u2192 M.Sc \\u2192 PhD \\u2192 Research Scientist / Professor\\n        </p>\\n\\n        <p class=\\\"fw-semibold fst-italic mt-3\\\">\\n          \\u201cScience rewards patience, curiosity, and deep thinking.\\u201d\\n        </p>\\n\\n      \", \"header_class\": \"modal-header bg-success text-white\", \"source_page\": \"12th.html\", \"icon_class\": \"bi-eyedropper\"}'),
(92, 3, 'laksh', '{\"career\": \"Clerical & Assistant\", \"title\": \"Clerical & Assistant Government Jobs\", \"description\": \"\\n\\n                <!-- INTRO -->\\n                <p class=\\\"text-secondary fs-5 mb-4\\\">\\n                    Clerical &amp; Assistant Government Jobs are entry-level positions in government departments.\\n                    These roles focus on office administration, record keeping, and supporting senior officers\\n                    in daily government work.\\n                </p>\\n\\n                <!-- JOB ROLES -->\\n                <h5 class=\\\"fw-bold text-dark mt-4 mb-3\\\">Common Job Roles</h5>\\n                <ul class=\\\"list-unstyled\\\">\\n                    <li class=\\\"mb-3\\\">\\n                        <strong class=\\\"text-primary\\\">Clerk (LDC / UDC):</strong>\\n                        <span class=\\\"text-muted d-block ms-3\\\">Handles files, office records, data entry, and routine\\n                            administrative work.</span>\\n                    </li>\\n                    <li class=\\\"mb-3\\\">\\n                        <strong class=\\\"text-primary\\\">Office Assistant:</strong>\\n                        <span class=\\\"text-muted d-block ms-3\\\">Supports daily office operations such as documentation,\\n                            correspondence, and coordination.</span>\\n                    </li>\\n                    <li class=\\\"mb-3\\\">\\n                        <strong class=\\\"text-primary\\\">Junior Assistant:</strong>\\n                        <span class=\\\"text-muted d-block ms-3\\\">Assists senior staff with clerical tasks, record\\n                            maintenance, and departmental activities.</span>\\n                    </li>\\n                    <li class=\\\"mb-3\\\">\\n                        <strong class=\\\"text-primary\\\">Data Entry Operator:</strong>\\n                        <span class=\\\"text-muted d-block ms-3\\\">Responsible for entering, updating, and maintaining data\\n                            in government computer systems.</span>\\n                    </li>\\n                    <li class=\\\"mb-3\\\">\\n                        <strong class=\\\"text-primary\\\">Assistant Section Officer:</strong>\\n                        <span class=\\\"text-muted d-block ms-3\\\">Manages official files, drafts notes, and assists in\\n                            decision-making at the section level.</span>\\n                    </li>\\n                </ul>\\n\\n                <!-- WORK NATURE -->\\n                <h5 class=\\\"fw-bold text-dark mt-4 mb-3\\\">Nature of Work</h5>\\n                <ul class=\\\"text-muted\\\">\\n                    <li class=\\\"mb-2\\\">File handling and record maintenance</li>\\n                    <li class=\\\"mb-2\\\">Data entry and office documentation</li>\\n                    <li class=\\\"mb-2\\\">Assisting senior officers</li>\\n                    <li class=\\\"mb-2\\\">Public dealing and basic administrative tasks</li>\\n                </ul>\\n\\n                <!-- ELIGIBILITY -->\\n                <h5 class=\\\"fw-bold text-dark mt-4 mb-3\\\">Eligibility</h5>\\n                <p class=\\\"text-muted bg-light p-3 rounded-3\\\">\\n                    Graduation in any stream from a recognized university.\\n                    Basic computer knowledge and typing skills are usually required.\\n                </p>\\n\\n                <!-- EXAMS -->\\n                <h5 class=\\\"fw-bold text-dark mt-4 mb-3\\\">Exams Required</h5>\\n                <ul class=\\\"text-muted\\\">\\n                    <li>SSC (Staff Selection Commission) examinations</li>\\n                    <li>State government clerical examinations</li>\\n                    <li>Department-specific recruitment exams</li>\\n                </ul>\\n\\n                <!-- SALARY -->\\n                <h5 class=\\\"fw-bold text-dark mt-4 mb-3\\\">Salary (Approximate)</h5>\\n                <p class=\\\"text-success fw-bold fs-5\\\">\\n                    \\u20b925,000 \\u2013 \\u20b940,000 per month <span class=\\\"fs-6 text-muted fw-normal\\\">(including allowances, as per\\n                        pay commission)</span>\\n                </p>\\n\\n                <!-- FACILITIES -->\\n                <h5 class=\\\"fw-bold text-dark mt-4 mb-3\\\">Facilities &amp; Benefits</h5>\\n                <ul class=\\\"text-muted\\\">\\n                    <li>Permanent job security</li>\\n                    <li>Fixed working hours</li>\\n                    <li>Paid leaves and government holidays</li>\\n                    <li>Medical benefits for employee and family</li>\\n                    <li>Pension after retirement</li>\\n                </ul>\\n\\n                <!-- PROMOTION -->\\n                <h5 class=\\\"fw-bold text-dark mt-4 mb-3\\\">Promotion &amp; Career Growth</h5>\\n                <p class=\\\"text-muted\\\">\\n                    Promotions are mostly time-based. Employees can grow from Clerk to Assistant\\n                    and later to Section Officer through experience and departmental exams.\\n                </p>\\n\\n                <!-- RETIREMENT -->\\n                <h5 class=\\\"fw-bold text-dark mt-4 mb-3\\\">Retirement</h5>\\n                <p class=\\\"text-muted\\\">\\n                    The retirement age is generally around 60 years, along with pension\\n                    and post-retirement benefits.\\n                </p>\\n\\n                <!-- REALITY CHECK -->\\n                <div class=\\\"alert alert-light border shadow-sm mt-5\\\">\\n                    <h6 class=\\\"fw-bold text-muted text-uppercase small\\\">Reality Check</h6>\\n                    <ul class=\\\"mb-0 text-muted small\\\">\\n                        <li>Very high competition for limited vacancies</li>\\n                        <li>Slow promotions compared to private sector</li>\\n                        <li>Stable but limited salary growth</li>\\n                        <li>Routine work with low pressure</li>\\n                    </ul>\\n                </div>\\n\\n                <div class=\\\"alert alert-primary text-center mt-3 fw-semibold border-0\\\">\\n                    Best suited for candidates who prefer stability, routine office work, and long-term security.\\n                </div>\\n\\n            \", \"header_class\": \"modal-header border-0 text-white p-4\", \"source_page\": \"Graduation.html\", \"icon_class\": \"bi bi-file-earmark-text\"}'),
(93, 2, 'trunal', '{\"career\": \"PCM\", \"title\": \"PCM \\u2013 Engineering & Technology Path\", \"description\": \"\\n\\n                        <h6>\\ud83d\\udcd8 What is PCM?</h6>\\n                        <p>\\n                            PCM includes <strong>Physics, Chemistry, and Mathematics</strong>.\\n                            It focuses on logic, problem-solving, machines, and technology.\\n                            PCM is mainly chosen by students who want engineering or technical careers.\\n                        </p>\\n\\n                        <h6>\\ud83d\\udcda Subjects Explained</h6>\\n                        <ul>\\n                            <li><strong>Physics:</strong> Motion, electricity, mechanics, electronics</li>\\n                            <li><strong>Chemistry:</strong> Materials, reactions, fuels, compounds</li>\\n                            <li><strong>Mathematics:</strong> Algebra, calculus, reasoning</li>\\n                        </ul>\\n                        <h6>\\ud83c\\udfeb Board Exam Importance (For PCM Students)</h6>\\n                        <p>\\n                            Your <strong>10th and 12th board marks</strong> play an important role in the PCM path.\\n                        </p>\\n\\n                        <ul>\\n                            <li>\\n                                <strong>After 10th:</strong> Schools use board marks to give admission\\n                                into Science (PCM). Higher marks = better school options.\\n                            </li>\\n                            <li>\\n                                <strong>After 12th:</strong> Board marks are required to be\\n                                <strong>eligible for engineering colleges</strong>.\\n                                Even if you clear JEE, minimum board percentage is compulsory.\\n                            </li>\\n                            <li>\\n                                <strong>College Admissions:</strong> Many private and state colleges\\n                                consider board marks along with entrance exams.\\n                            </li>\\n                        </ul>\\n\\n                        <p class=\\\"text-muted\\\">\\n                            <small>\\n                                Tip: Strong board basics help you perform better in JEE and engineering studies.\\n                            </small>\\n                        </p>\\n\\n                        <h6>\\ud83c\\udfaf Why choose PCM?</h6>\\n                        <ul>\\n                            <li>You like Maths and logic</li>\\n                            <li>You enjoy problem-solving</li>\\n                            <li>You want a technical career</li>\\n                        </ul>\\n\\n                        <h6>\\ud83c\\udfed Where is PCM used?</h6>\\n                        <p>\\n                            Engineering, IT companies, software industry, AI &amp; data science,\\n                            defence services, space research, government technical jobs.\\n                        </p>\\n\\n                        <h6>\\ud83d\\udcdd Important Exams</h6>\\n                        <p>\\n                            <strong>JEE (Joint Entrance Examination)</strong> is required for\\n                            engineering colleges like IITs, NITs, and other technical institutes.\\n                        </p>\\n\\n                        <h6>\\u23f1 Duration</h6>\\n                        <p>11\\u201312 PCM (2 years) \\u2192 Engineering (4 years)</p>\\n\\n                        <h6>\\ud83d\\udcb0 Salary</h6>\\n                        <p>\\u20b925,000/month (starter) \\u2192 \\u20b910\\u201320+ LPA (experienced)</p>\\n\\n                        <div class=\\\"alert alert-warning reality-check\\\">\\n                            <strong>Reality Check:</strong> PCM needs daily practice and patience.\\n                            Choose it only if you like Maths.\\n                        </div>\\n\\n                    \", \"header_class\": \"modal-header bg-success text-white\", \"source_page\": \"10th.html\", \"icon_class\": \"bi-calculator\"}'),
(97, 2, 'trunal', '{\"career\": \"Diploma Courses\", \"title\": \"Diploma\", \"description\": \"\\n          <div class=\\\"stream-header bg-diploma\\\">\\n            \\n            <h1 class=\\\"fw-bold\\\">Diploma</h1>\\n            <p class=\\\"fs-5 mt-2 opacity-75\\\">\\n              A practical education route designed for hands-on learning, early employment, and industry\\n              readiness.\\n            </p>\\n          </div>\\n          <section id=\\\"diploma-after-12th\\\" class=\\\"py-5\\\">\\n    <div class=\\\"container\\\">\\n\\n        <!-- Info Box -->\\n        <div class=\\\"alert alert-primary text-center mb-5 shadow-sm border-0\\\">\\n            <i class=\\\"bi bi-info-circle-fill me-2\\\"></i>\\n            A diploma is a practical entry route into engineering, while engineering is the advanced professional level.\\n        </div>\\n\\n        <!-- Content -->\\n        <div class=\\\"row g-4\\\">\\n\\n            <div class=\\\"col-md-6\\\">\\n                <div class=\\\"degree-card h-100\\\">\\n                    <h5 class=\\\"fw-bold text-info\\\">What is a Diploma?</h5>\\n                    <p class=\\\"text-muted\\\">\\n                        A skill-oriented and practical education pathway focused on industry needs.\\n                        It emphasizes hands-on training, workshops, and real-world applications to make students job-ready\\n                        in less time.\\n                    </p>\\n                </div>\\n            </div>\\n\\n            <div class=\\\"col-md-6\\\">\\n                <div class=\\\"degree-card h-100\\\">\\n                    <h5 class=\\\"fw-bold text-info\\\">Who Should Choose?</h5>\\n                    <ul>\\n                        <li>Students who prefer practical learning</li>\\n                        <li>Students aiming for early job opportunities</li>\\n                        <li>Students interested in technical or field work</li>\\n                        <li>Those planning to earn early and upgrade later</li>\\n                    </ul>\\n                </div>\\n            </div>\\n\\n            <div class=\\\"col-md-4\\\">\\n                <div class=\\\"degree-card h-100\\\">\\n                    <h5 class=\\\"fw-bold text-info\\\">Duration &amp; Learning</h5>\\n                    <ul>\\n                        <li>Duration: 1 \\u2013 3 years</li>\\n                        <li>Hands-on labs and workshops</li>\\n                        <li>Industrial and field exposure</li>\\n                        <li>Skill-based practical training</li>\\n                    </ul>\\n                </div>\\n            </div>\\n\\n            <div class=\\\"col-md-4\\\">\\n                <div class=\\\"degree-card h-100\\\">\\n                    <h5 class=\\\"fw-bold text-info\\\">Admission &amp; Skills</h5>\\n                    <ul>\\n                        <li>Based on 12th standard marks</li>\\n                        <li>Technical and operational skills</li>\\n                        <li>Tool &amp; equipment handling</li>\\n                        <li>Problem-solving ability</li>\\n                    </ul>\\n                </div>\\n            </div>\\n\\n            <div class=\\\"col-md-4\\\">\\n                <div class=\\\"degree-card h-100\\\">\\n                    <h5 class=\\\"fw-bold text-info\\\">Career &amp; Salary</h5>\\n                    <ul>\\n                        <li>Technician &amp; Junior Engineer</li>\\n                        <li>Freshers: \\u20b912k \\u2013 \\u20b925k / month</li>\\n                        <li>Experienced: \\u20b930k \\u2013 \\u20b950k+</li>\\n                        <li>Govt: PSUs, Railways, Electricity Boards</li>\\n                    </ul>\\n                </div>\\n            </div>\\n\\n            <div class=\\\"col-12\\\">\\n                <div class=\\\"degree-card bg-light border-success\\\">\\n                    <h5 class=\\\"fw-bold text-success\\\"><i class=\\\"bi bi-graph-up-arrow me-2\\\"></i>Higher Education Pathway</h5>\\n                    <p class=\\\"mb-0\\\">\\n                        Diploma holders can take direct admission into engineering degree programs through\\n                        <strong>Diploma to Degree (DtoD / Lateral Entry)</strong>, usually entering the 2nd year.\\n                        All relevant degree programs can be pursued through proper admission channels.\\n                    </p>\\n                </div>\\n            </div>\\n\\n            <div class=\\\"col-md-6\\\">\\n                <div class=\\\"degree-card h-100\\\">\\n                    <h5 class=\\\"fw-bold text-info\\\">Advantages</h5>\\n                    <ul>\\n                        <li>Early earning opportunity</li>\\n                        <li>Lower education cost</li>\\n                        <li>Strong practical foundation</li>\\n                        <li>Smooth path to engineering</li>\\n                    </ul>\\n                </div>\\n            </div>\\n\\n            <div class=\\\"col-md-6\\\">\\n                <div class=\\\"degree-card h-100\\\">\\n                    <h5 class=\\\"fw-bold text-danger\\\">Limitations</h5>\\n                    <ul>\\n                        <li>Limited growth without higher qualification</li>\\n                        <li>Senior roles may require a degree</li>\\n                        <li>Initial salary growth may be slower</li>\\n                    </ul>\\n                </div>\\n            </div>\\n\\n        </div>\\n\\n        <!-- Motivation Line -->\\n        <div class=\\\"text-center mt-5\\\">\\n            <p class=\\\"fw-semibold fs-5 text-primary fst-italic\\\">\\n                \\u201cA diploma is not a shortcut\\u2014it is a smart, skill-driven path to enter industry early and grow step by step.\\u201d\\n            </p>\\n        </div>\\n\\n    </div>\\n</section>\\n        \", \"header_class\": \"modal-header bg-diploma text-white\", \"source_page\": \"12th.html\", \"icon_class\": \"bi-mortarboard\"}'),
(99, 3, 'laksh', '{\"career\": \"AC Technician\", \"title\": \"AC Technician\", \"description\": \"\\n                <h6>What is AC Technician Work?</h6>\\n                <p>\\n                    AC technician work involves installing, servicing, repairing, and maintaining air conditioners and\\n                    cooling systems for homes, offices, and commercial buildings.</p>\\n\\n                <h6>Who can choose this career?</h6>\\n                <p>\\n                    10th / 12th pass or failed students, beginners, and anyone interested in cooling systems and\\n                    technical work. No graduation is required.</p>\\n\\n                <h6>Required Skills:</h6>\\n                <p>\\n                    Basic electrical knowledge, refrigeration understanding, problem-solving, and hands-on technical\\n                    skills.</p>\\n\\n                <h6>Tools &amp; Equipment Used:</h6>\\n                <p>\\n                    Gas charging kit, pressure gauges, vacuum pump, multimeter, servicing tools, safety gloves.</p>\\n\\n                <h6>Equipment Required:</h6>\\n                <p>\\n                    AC service toolkit, safety equipment, basic testing devices.</p>\\n\\n                <h6>Learning Time:</h6>\\n                <p>\\n                    Basic: 2\\u20133 months<br>\\n                    Intermediate: 6 months<br>\\n                    Professional: 1 year (with field experience)</p>\\n\\n                <h6>How to Start:</h6>\\n                <p>\\n                    Join a short training course \\u2192 work as helper \\u2192 assist in installations \\u2192 start independent service\\n                    work.</p>\\n\\n                <h6>Work Type:</h6>\\n                <p>\\n                    Offline (Homes, offices, commercial sites), Self-employed or job-based.</p>\\n\\n                <h6>Career Options:</h6>\\n                <p>\\n                    AC Technician, HVAC Technician, Maintenance Technician, Service Engineer.</p>\\n\\n                <h6>Income / Salary (India):</h6>\\n                <p>\\n                    Beginner: \\u20b98,000 \\u2013 \\u20b915,000 per month<br>\\n                    Intermediate: \\u20b920,000 \\u2013 \\u20b935,000 per month<br>\\n                    Skilled / Service Provider: \\u20b950,000+ per month (seasonal &amp; service based)</p>\\n\\n                <h6>Career Growth Path:</h6>\\n                <p>\\n                    Helper \\u2192 Skilled Technician \\u2192 Senior Technician \\u2192 HVAC Service Business Owner.</p>\\n\\n                <h6>Government Scope:</h6>\\n                <p>\\n                    Limited opportunities in maintenance departments with certification, but mostly private and\\n                    self-employment based.</p>\\n\\n                <h6>Where can you work?</h6>\\n                <p>\\n                    AC service centers, commercial buildings, hotels, factories, or self-employment.</p>\\n\\n                <p class=\\\"text-danger small\\\">\\n                    \\u26a0 Safety and proper training are important while handling electrical and gas systems.\\n                </p>\\n\\n                <p class=\\\"fw-semibold text-primary\\\">\\n                    \\u2744 Skilled AC technicians are always in high demand, especially in cities.\\n                </p>\\n            \", \"header_class\": \"modal-header\", \"source_page\": \"Unique_Career.html\", \"icon_class\": \"bi bi-fan career-icon\"}'),
(100, 3, 'laksh', '{\"career\": \"Graphic Designer\", \"title\": \"Graphic Designer\", \"description\": \"\\n                <h6>What is Graphic Designing?</h6>\\n                <p>\\n                    Graphic designing is the skill of creating visual content like posters, logos, banners, thumbnails,\\n                    social media posts, and advertisements using digital tools.</p>\\n\\n                <h6>Who can choose this career?</h6>\\n                <p>\\n                    10th / 12th pass or failed students, beginners, creative learners, and anyone interested in design.\\n                    No degree is required.</p>\\n\\n                <h6>Required Skills:</h6>\\n                <p>\\n                    Creativity, color sense, basic typography, visual thinking, and communication with clients.</p>\\n\\n                <h6>Tools &amp; Software:</h6>\\n                <p>\\n                    Canva (Beginner), Adobe Photoshop, Adobe Illustrator, Figma, mobile design apps.</p>\\n\\n                <h6>Equipment Required:</h6>\\n                <p>\\n                    Laptop or computer (recommended), or smartphone for beginners, internet connection.</p>\\n\\n                <h6>Learning Time:</h6>\\n                <p>\\n                    Basic: 1\\u20132 months<br>\\n                    Intermediate: 3\\u20134 months<br>\\n                    Professional: 6 months (with regular practice)</p>\\n\\n                <h6>How to Start:</h6>\\n                <p>\\n                    Learn basics online \\u2192 practice daily \\u2192 create a small portfolio \\u2192 share work on social media \\u2192 start\\n                    freelancing or internships.</p>\\n\\n                <h6>Work Type:</h6>\\n                <p>\\n                    Online (Freelancing), Offline (Printing shops, agencies), or Hybrid.</p>\\n\\n                <h6>Career Options:</h6>\\n                <p>\\n                    Graphic Designer, Social Media Designer, Logo Designer, Branding Designer, Freelancer, Design Agency\\n                    Owner.</p>\\n\\n                <h6>Income / Salary (India):</h6>\\n                <p>\\n                    Beginner: \\u20b98,000 \\u2013 \\u20b915,000 per month<br>\\n                    Intermediate: \\u20b920,000 \\u2013 \\u20b940,000 per month<br>\\n                    Skilled / Freelancer: \\u20b950,000+ per month (depends on skill &amp; clients)</p>\\n\\n                <h6>Career Growth Path:</h6>\\n                <p>\\n                    Beginner Designer \\u2192 Skilled Designer \\u2192 Senior Designer / Freelancer \\u2192 Own Design Agency.</p>\\n\\n                <h6>Government Scope:</h6>\\n                <p>\\n                    Limited direct government jobs. Mostly a private and freelance-based career.</p>\\n\\n                <h6>Where can you work?</h6>\\n                <p>\\n                    Digital marketing agencies, media &amp; advertising companies, startups, freelancing platforms, or\\n                    self-employment.</p>\\n\\n                <p class=\\\"text-danger small\\\">\\n                    \\u26a0 Income is not guaranteed at the beginning. Success depends on practice, consistency, and quality\\n                    of work.\\n                </p>\\n\\n                <p class=\\\"fw-semibold text-primary\\\">\\n                    \\ud83d\\udca1 Your creativity can become your career \\u2014 no degree required.\\n                </p>\\n            \", \"header_class\": \"modal-header\", \"source_page\": \"Unique_Career.html\", \"icon_class\": \"bi bi-palette career-icon\"}'),
(101, 1, 'bhavya', '{\"career\": \"Mathematics\", \"title\": \"Science & Research (PCM)\", \"description\": \"\\n\\n        <h5>\\ud83d\\udccc Basic Introduction</h5>\\n        <p>\\n          Science &amp; Research is an academic and research-focused career path for PCM students.\\n          It emphasizes deep understanding of Physics, Chemistry, and Mathematics through\\n          theory, experiments, and analysis.\\n        </p>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83d\\udccb Key Details</h5>\\n        <ul>\\n          <li><strong>Degree Type:</strong> B.Sc / Integrated M.Sc</li>\\n          <li><strong>Duration:</strong> 3 \\u2013 5 Years</li>\\n          <li><strong>Stream:</strong> Pure Science (PCM)</li>\\n          <li><strong>Mode:</strong> Full-Time</li>\\n          <li><strong>Focus:</strong> Concepts, research, experiments</li>\\n        </ul>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83c\\udfaf Specializations</h5>\\n        <ul>\\n          <li>Physics</li>\\n          <li>Chemistry</li>\\n          <li>Mathematics</li>\\n          <li>Statistics</li>\\n          <li>Data Science (Science route)</li>\\n        </ul>\\n\\n        <h5 class=\\\"mt-4\\\">\\u2705 Eligibility</h5>\\n        <ul>\\n          <li>Passed 12th with <strong>PCM</strong></li>\\n          <li>Strong interest in theory &amp; problem-solving</li>\\n        </ul>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83d\\udcdd Entrance Exams</h5>\\n        <ul>\\n          <li>CUET (UG)</li>\\n          <li>University-level science entrance exams</li>\\n          <li>IISER Aptitude Test (for top institutes)</li>\\n        </ul>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83d\\udcbc Career Options</h5>\\n        <ul>\\n          <li>Research Scientist</li>\\n          <li>Professor / Lecturer</li>\\n          <li>Scientific Officer</li>\\n          <li>Lab Analyst</li>\\n          <li>Data Scientist (Research-based)</li>\\n        </ul>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83d\\udcb0 Salary Info</h5>\\n        <ul>\\n          <li><strong>Freshers:</strong> \\u20b93 \\u2013 5 LPA</li>\\n          <li><strong>After PhD:</strong> \\u20b98 \\u2013 15+ LPA</li>\\n        </ul>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83c\\udfdb\\ufe0f Government Scope</h5>\\n        <p>\\n          Very strong government scope in ISRO, DRDO, CSIR, IISc,\\n          government universities, and national research laboratories.\\n        </p>\\n\\n        <h5 class=\\\"mt-4\\\">\\u2696\\ufe0f Private vs Government Comparison</h5>\\n        <table class=\\\"table table-bordered\\\">\\n          <tbody><tr>\\n            <th>Aspect</th>\\n            <th>Private</th>\\n            <th>Government</th>\\n          </tr>\\n          <tr>\\n            <td>Salary Growth</td>\\n            <td>Moderate</td>\\n            <td>Stable</td>\\n          </tr>\\n          <tr>\\n            <td>Job Security</td>\\n            <td>Medium</td>\\n            <td>High</td>\\n          </tr>\\n        </tbody></table>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83c\\udf93 Internship Importance</h5>\\n        <p>\\n          Research internships are crucial for PhD admissions, skill development,\\n          and scientific exposure.\\n        </p>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83e\\udded Career Path Flow</h5>\\n        <p>\\n          12th PCM \\u2192 B.Sc \\u2192 M.Sc \\u2192 PhD \\u2192 Research Scientist / Professor\\n        </p>\\n\\n        <p class=\\\"fw-semibold fst-italic mt-3\\\">\\n          \\u201cScience rewards patience, curiosity, and deep thinking.\\u201d\\n        </p>\\n\\n      \", \"header_class\": \"modal-header bg-success text-white\", \"source_page\": \"12th.html\", \"icon_class\": \"bi-eyedropper\"}'),
(102, 1, 'bhavya', '{\"career\": \"Statistics\", \"title\": \"Science & Research (PCM)\", \"description\": \"\\n\\n        <h5>\\ud83d\\udccc Basic Introduction</h5>\\n        <p>\\n          Science &amp; Research is an academic and research-focused career path for PCM students.\\n          It emphasizes deep understanding of Physics, Chemistry, and Mathematics through\\n          theory, experiments, and analysis.\\n        </p>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83d\\udccb Key Details</h5>\\n        <ul>\\n          <li><strong>Degree Type:</strong> B.Sc / Integrated M.Sc</li>\\n          <li><strong>Duration:</strong> 3 \\u2013 5 Years</li>\\n          <li><strong>Stream:</strong> Pure Science (PCM)</li>\\n          <li><strong>Mode:</strong> Full-Time</li>\\n          <li><strong>Focus:</strong> Concepts, research, experiments</li>\\n        </ul>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83c\\udfaf Specializations</h5>\\n        <ul>\\n          <li>Physics</li>\\n          <li>Chemistry</li>\\n          <li>Mathematics</li>\\n          <li>Statistics</li>\\n          <li>Data Science (Science route)</li>\\n        </ul>\\n\\n        <h5 class=\\\"mt-4\\\">\\u2705 Eligibility</h5>\\n        <ul>\\n          <li>Passed 12th with <strong>PCM</strong></li>\\n          <li>Strong interest in theory &amp; problem-solving</li>\\n        </ul>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83d\\udcdd Entrance Exams</h5>\\n        <ul>\\n          <li>CUET (UG)</li>\\n          <li>University-level science entrance exams</li>\\n          <li>IISER Aptitude Test (for top institutes)</li>\\n        </ul>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83d\\udcbc Career Options</h5>\\n        <ul>\\n          <li>Research Scientist</li>\\n          <li>Professor / Lecturer</li>\\n          <li>Scientific Officer</li>\\n          <li>Lab Analyst</li>\\n          <li>Data Scientist (Research-based)</li>\\n        </ul>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83d\\udcb0 Salary Info</h5>\\n        <ul>\\n          <li><strong>Freshers:</strong> \\u20b93 \\u2013 5 LPA</li>\\n          <li><strong>After PhD:</strong> \\u20b98 \\u2013 15+ LPA</li>\\n        </ul>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83c\\udfdb\\ufe0f Government Scope</h5>\\n        <p>\\n          Very strong government scope in ISRO, DRDO, CSIR, IISc,\\n          government universities, and national research laboratories.\\n        </p>\\n\\n        <h5 class=\\\"mt-4\\\">\\u2696\\ufe0f Private vs Government Comparison</h5>\\n        <table class=\\\"table table-bordered\\\">\\n          <tbody><tr>\\n            <th>Aspect</th>\\n            <th>Private</th>\\n            <th>Government</th>\\n          </tr>\\n          <tr>\\n            <td>Salary Growth</td>\\n            <td>Moderate</td>\\n            <td>Stable</td>\\n          </tr>\\n          <tr>\\n            <td>Job Security</td>\\n            <td>Medium</td>\\n            <td>High</td>\\n          </tr>\\n        </tbody></table>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83c\\udf93 Internship Importance</h5>\\n        <p>\\n          Research internships are crucial for PhD admissions, skill development,\\n          and scientific exposure.\\n        </p>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83e\\udded Career Path Flow</h5>\\n        <p>\\n          12th PCM \\u2192 B.Sc \\u2192 M.Sc \\u2192 PhD \\u2192 Research Scientist / Professor\\n        </p>\\n\\n        <p class=\\\"fw-semibold fst-italic mt-3\\\">\\n          \\u201cScience rewards patience, curiosity, and deep thinking.\\u201d\\n        </p>\\n\\n      \", \"header_class\": \"modal-header bg-success text-white\", \"source_page\": \"12th.html\", \"icon_class\": \"bi-eyedropper\"}'),
(103, 1, 'bhavya', '{\"career\": \"Data Science (Science Route)\", \"title\": \"Science & Research (PCM)\", \"description\": \"\\n\\n        <h5>\\ud83d\\udccc Basic Introduction</h5>\\n        <p>\\n          Science &amp; Research is an academic and research-focused career path for PCM students.\\n          It emphasizes deep understanding of Physics, Chemistry, and Mathematics through\\n          theory, experiments, and analysis.\\n        </p>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83d\\udccb Key Details</h5>\\n        <ul>\\n          <li><strong>Degree Type:</strong> B.Sc / Integrated M.Sc</li>\\n          <li><strong>Duration:</strong> 3 \\u2013 5 Years</li>\\n          <li><strong>Stream:</strong> Pure Science (PCM)</li>\\n          <li><strong>Mode:</strong> Full-Time</li>\\n          <li><strong>Focus:</strong> Concepts, research, experiments</li>\\n        </ul>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83c\\udfaf Specializations</h5>\\n        <ul>\\n          <li>Physics</li>\\n          <li>Chemistry</li>\\n          <li>Mathematics</li>\\n          <li>Statistics</li>\\n          <li>Data Science (Science route)</li>\\n        </ul>\\n\\n        <h5 class=\\\"mt-4\\\">\\u2705 Eligibility</h5>\\n        <ul>\\n          <li>Passed 12th with <strong>PCM</strong></li>\\n          <li>Strong interest in theory &amp; problem-solving</li>\\n        </ul>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83d\\udcdd Entrance Exams</h5>\\n        <ul>\\n          <li>CUET (UG)</li>\\n          <li>University-level science entrance exams</li>\\n          <li>IISER Aptitude Test (for top institutes)</li>\\n        </ul>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83d\\udcbc Career Options</h5>\\n        <ul>\\n          <li>Research Scientist</li>\\n          <li>Professor / Lecturer</li>\\n          <li>Scientific Officer</li>\\n          <li>Lab Analyst</li>\\n          <li>Data Scientist (Research-based)</li>\\n        </ul>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83d\\udcb0 Salary Info</h5>\\n        <ul>\\n          <li><strong>Freshers:</strong> \\u20b93 \\u2013 5 LPA</li>\\n          <li><strong>After PhD:</strong> \\u20b98 \\u2013 15+ LPA</li>\\n        </ul>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83c\\udfdb\\ufe0f Government Scope</h5>\\n        <p>\\n          Very strong government scope in ISRO, DRDO, CSIR, IISc,\\n          government universities, and national research laboratories.\\n        </p>\\n\\n        <h5 class=\\\"mt-4\\\">\\u2696\\ufe0f Private vs Government Comparison</h5>\\n        <table class=\\\"table table-bordered\\\">\\n          <tbody><tr>\\n            <th>Aspect</th>\\n            <th>Private</th>\\n            <th>Government</th>\\n          </tr>\\n          <tr>\\n            <td>Salary Growth</td>\\n            <td>Moderate</td>\\n            <td>Stable</td>\\n          </tr>\\n          <tr>\\n            <td>Job Security</td>\\n            <td>Medium</td>\\n            <td>High</td>\\n          </tr>\\n        </tbody></table>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83c\\udf93 Internship Importance</h5>\\n        <p>\\n          Research internships are crucial for PhD admissions, skill development,\\n          and scientific exposure.\\n        </p>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83e\\udded Career Path Flow</h5>\\n        <p>\\n          12th PCM \\u2192 B.Sc \\u2192 M.Sc \\u2192 PhD \\u2192 Research Scientist / Professor\\n        </p>\\n\\n        <p class=\\\"fw-semibold fst-italic mt-3\\\">\\n          \\u201cScience rewards patience, curiosity, and deep thinking.\\u201d\\n        </p>\\n\\n      \", \"header_class\": \"modal-header bg-success text-white\", \"source_page\": \"12th.html\", \"icon_class\": \"bi-eyedropper\"}'),
(104, 1, 'bhavya', '{\"career\": \"PCB\", \"title\": \"PCB \\u2013 Medical & Healthcare Path\", \"description\": \"\\n\\n                        <h6>\\ud83d\\udcd8 What is PCB?</h6>\\n                        <p>\\n                            PCB includes <strong>Physics, Chemistry, and Biology</strong>.\\n                            It focuses on the human body, health, and life sciences.\\n                            PCB is compulsory for medical careers.\\n                        </p>\\n\\n                        <h6>\\ud83d\\udcda Subjects Explained</h6>\\n                        <ul>\\n                            <li><strong>Biology:</strong> Human body, plants, animals, genetics</li>\\n                            <li><strong>Chemistry:</strong> Medicines, drugs, reactions</li>\\n                            <li><strong>Physics:</strong> Medical instruments &amp; principles</li>\\n                        </ul>\\n                        <h6>\\ud83c\\udfeb Board Exam Importance (For PCB Students)</h6>\\n                        <p>\\n                            Board exams are <strong>very important</strong> for students choosing PCB.\\n                        </p>\\n\\n                        <ul>\\n                            <li>\\n                                <strong>After 10th:</strong> Good board marks help you get admission\\n                                into Science (PCB) stream easily.\\n                            </li>\\n                            <li>\\n                                <strong>After 12th:</strong> You must <strong>pass board exams</strong>\\n                                to be eligible for <strong>NEET</strong>.\\n                                Without passing 12th board, medical admission is not possible.\\n                            </li>\\n                            <li>\\n                                <strong>Medical Colleges:</strong> Board marks are checked for\\n                                eligibility and document verification.\\n                            </li>\\n                        </ul>\\n\\n                        <p class=\\\"text-muted\\\">\\n                            <small>\\n                                Tip: Biology concepts studied for boards directly help\\n                            </small>\\n                        </p>\\n\\n                        <h6>\\ud83c\\udfaf Why choose PCB?</h6>\\n                        <ul>\\n                            <li>You want to become a doctor or work in healthcare</li>\\n                            <li>You enjoy Biology</li>\\n                            <li>You want a respected medical profession</li>\\n                        </ul>\\n\\n                        <h6>\\ud83c\\udfe5 Where is PCB used?</h6>\\n                        <p>\\n                            Hospitals, clinics, laboratories, pharmaceutical companies,\\n                            medical research centers.\\n                        </p>\\n\\n                        <h6>\\ud83d\\udcdd Important Exams</h6>\\n                        <p>\\n                            <strong>NEET (National Eligibility cum Entrance Test)</strong>\\n                            is mandatory for MBBS, BDS, and medical courses in India.\\n                        </p>\\n\\n                        <h6>\\u23f1 Duration</h6>\\n                        <p>11\\u201312 PCB (2 years) \\u2192 Medical studies (5\\u20136 years)</p>\\n\\n                        <h6>\\ud83d\\udcb0 Salary</h6>\\n                        <p>\\u20b930,000/month \\u2192 \\u20b915\\u201330+ LPA (specialists)</p>\\n\\n                        <div class=\\\"alert alert-warning reality-check\\\">\\n                            <strong>Reality Check:</strong> Medical careers need long study time\\n                            and strong dedication.\\n                        </div>\\n\\n                    \", \"header_class\": \"modal-header bg-primary text-white\", \"source_page\": \"10th.html\", \"icon_class\": \"bi-heart-pulse\"}'),
(105, 1, 'bhavya', '{\"career\": \"B.Sc Life Sciences\", \"title\": \"B.Sc Life Sciences\", \"description\": \"\\n\\n        <h5>\\ud83d\\udccc What is B.Sc Life Sciences?</h5>\\n        <p>\\n          B.Sc Life Sciences is an interdisciplinary undergraduate degree that studies\\n          living organisms and life processes. It combines subjects such as biology,\\n          chemistry, biochemistry, microbiology, and environmental science to build\\n          a strong foundation for research, laboratory work, healthcare support,\\n          and higher studies in life science fields.\\n        </p>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83d\\udd2c What does a Life Sciences student study?</h5>\\n        <ul>\\n          <li>Structure and function of living organisms</li>\\n          <li>Cell biology and molecular processes</li>\\n          <li>Biological chemistry and metabolism</li>\\n          <li>Microorganisms and their applications</li>\\n          <li>Environment, ecology, and biodiversity</li>\\n          <li>Basic research methods and laboratory techniques</li>\\n        </ul>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83c\\udf93 Eligibility &amp; Admission</h5>\\n        <ul>\\n          <li>12th passed with <strong>PCB (Physics, Chemistry, Biology)</strong></li>\\n          <li>Some universities allow students from related science streams</li>\\n          <li>Minimum age: 17 years</li>\\n          <li>Admission through entrance exam or merit-based selection</li>\\n        </ul>\\n\\n        <h5 class=\\\"mt-4\\\">\\u23f1\\ufe0f Course Duration</h5>\\n        <ul>\\n          <li><strong>3 years</strong> undergraduate degree</li>\\n          <li>Includes laboratory practicals, fieldwork, and projects</li>\\n        </ul>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83d\\udcda Subjects Studied in B.Sc Life Sciences</h5>\\n        <ul>\\n          <li>Cell Biology</li>\\n          <li>Genetics</li>\\n          <li>Biochemistry</li>\\n          <li>Microbiology</li>\\n          <li>Molecular Biology</li>\\n          <li>Ecology &amp; Environmental Science</li>\\n          <li>Plant &amp; Animal Physiology</li>\\n          <li>Research Methodology &amp; Biostatistics</li>\\n        </ul>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83e\\udde9 Major Areas &amp; Pathways</h5>\\n        <ul>\\n          <li>Biomedical &amp; Health Sciences</li>\\n          <li>Environmental &amp; Ecological Sciences</li>\\n          <li>Biotechnology &amp; Molecular Biology</li>\\n          <li>Microbiology &amp; Diagnostics</li>\\n          <li>Academic &amp; Research Pathways</li>\\n        </ul>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83d\\udcbc Career Options after B.Sc Life Sciences</h5>\\n        <ul>\\n          <li>Laboratory Assistant / Technician</li>\\n          <li>Research Assistant</li>\\n          <li>Clinical Research Coordinator (entry-level)</li>\\n          <li>Quality Control / Quality Assurance Executive</li>\\n          <li>Scientific Content Writer</li>\\n          <li>Teaching Assistant (with higher studies)</li>\\n        </ul>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83c\\udfe2 Scope in the Private Sector</h5>\\n        <p>\\n          Life Sciences graduates are employed in private research laboratories,\\n          biotechnology companies, pharmaceutical firms,\\n          diagnostic centers, healthcare startups,\\n          environmental consulting companies, and educational organizations.\\n        </p>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83c\\udfdb\\ufe0f Government Job Scope</h5>\\n        <ul>\\n          <li>Government Research Institutes</li>\\n          <li>Public Health &amp; Environmental Departments</li>\\n          <li>Universities &amp; Government Colleges</li>\\n          <li>CSIR / DBT / ICMR funded research projects</li>\\n        </ul>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83d\\udcb0 Salary after B.Sc Life Sciences (Approx.)</h5>\\n        <p>\\n          <strong>Freshers:</strong> \\u20b92.5 \\u2013 4 LPA<br>\\n          <strong>Experienced:</strong> \\u20b95 \\u2013 7+ LPA<br>\\n          <strong>Research / MNC roles:</strong> \\u20b98 \\u2013 10+ LPA\\n        </p>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83d\\udcc8 Career Growth Path</h5>\\n        <p>\\n          Life Sciences Graduate \\u2192\\n          Lab / Research Assistant \\u2192\\n          Senior Research Associate \\u2192\\n          Scientist / Specialist \\u2192\\n          Consultant / Academic Professional\\n        </p>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83d\\udcd8 Higher Study Options</h5>\\n        <ul>\\n          <li>M.Sc Life Sciences</li>\\n          <li>M.Sc Biotechnology / Microbiology / Genetics</li>\\n          <li>M.Sc Environmental Science</li>\\n          <li>PhD &amp; Research Careers</li>\\n          <li>MS (Abroad)</li>\\n        </ul>\\n\\n        <h5 class=\\\"mt-4\\\">\\u26a0\\ufe0f Challenges in Life Sciences</h5>\\n        <ul>\\n          <li>Limited career growth without higher studies</li>\\n          <li>Research-oriented field requires patience</li>\\n          <li>Moderate starting salaries</li>\\n          <li>Lab-intensive and detail-focused work</li>\\n        </ul>\\n\\n        <h5 class=\\\"mt-4\\\">\\ud83c\\udfaf Who should choose B.Sc Life Sciences?</h5>\\n        <p>\\n          This course is ideal for students who are interested in\\n          biology, research, laboratory work, environmental studies,\\n          and want a strong foundation for higher studies or\\n          careers in science, healthcare support, and research.\\n        </p>\\n\\n        <p class=\\\"fw-semibold fst-italic mt-4\\\">\\n          \\u201cLife Sciences explores life itself \\u2014 from cells to ecosystems.\\u201d\\n        </p>\\n\\n      \", \"header_class\": \"modal-header bg-secondary text-white\", \"source_page\": \"12th.html\", \"icon_class\": \"bi-eyedropper\"}');
INSERT INTO `favourite_careers` (`id`, `user_id`, `user_name`, `favourite_career`) VALUES
(106, 2, 'trunal', '{\"career\": \"Humanities & Social Sciences\", \"title\": \"Humanities & Social Science Degrees\", \"description\": \"\\n\\n                <h5 class=\\\"fw-bold\\\">What are Humanities &amp; Social Science Degrees?</h5>\\n                <p>\\n                    Humanities and Social Science degrees focus on understanding human behavior,\\n                    society, culture, politics, history, economy, and social relationships.\\n                    These degrees are ideal for students interested in people-oriented,\\n                    analytical, and research-based careers.\\n                </p>\\n\\n                <hr>\\n\\n                <h5 class=\\\"fw-bold\\\">Major Humanities &amp; Social Science Degrees</h5>\\n                <ul>\\n                    <li><strong>B.A. English</strong> \\u2013 Study of literature, language, and communication.</li>\\n                    <li><strong>B.A. Hindi / Regional Languages</strong> \\u2013 Focus on language, literature, and culture.\\n                    </li>\\n                    <li><strong>B.A. History</strong> \\u2013 Study of past civilizations, events, and heritage.</li>\\n                    <li><strong>B.A. Geography</strong> \\u2013 Study of physical and human geography.</li>\\n                    <li><strong>B.A. Political Science</strong> \\u2013 Study of politics, governance, and public policy.</li>\\n                    <li><strong>B.A. Sociology</strong> \\u2013 Study of society, social behavior, and communities.</li>\\n                    <li><strong>B.A. Psychology</strong> \\u2013 Study of human mind and behavior.</li>\\n                    <li><strong>B.A. Philosophy</strong> \\u2013 Study of logic, ethics, and human thought.</li>\\n                    <li><strong>B.A. Economics</strong> \\u2013 Study of economy, finance, and development.</li>\\n                    <li><strong>B.A. Anthropology</strong> \\u2013 Study of human evolution and cultures.</li>\\n                    <li><strong>B.A. Public Administration</strong> \\u2013 Study of government systems and administration.\\n                    </li>\\n                    <li><strong>B.A. International Relations</strong> \\u2013 Study of global politics and diplomacy.</li>\\n                    <li><strong>B.A. Social Work (BSW)</strong> \\u2013 Professional study of social welfare and development.\\n                    </li>\\n                </ul>\\n\\n                <hr>\\n\\n                <h5 class=\\\"fw-bold\\\">Course Duration</h5>\\n                <p>3 years (6 semesters); 4-year programs available under NEP in some universities.</p>\\n\\n                <hr>\\n\\n                <h5 class=\\\"fw-bold\\\">Eligibility &amp; Admission</h5>\\n                <ul>\\n                    <li>12th pass from any recognized board</li>\\n                    <li>Students from any stream are eligible</li>\\n                    <li>Admission through merit or entrance exams (CUET in some universities)</li>\\n                </ul>\\n\\n                <hr>\\n\\n                <h5 class=\\\"fw-bold\\\">Key Skills Developed</h5>\\n                <ul>\\n                    <li>Analytical and critical thinking</li>\\n                    <li>Communication and writing skills</li>\\n                    <li>Research and data interpretation</li>\\n                    <li>Understanding of society and governance</li>\\n                    <li>Problem-solving and decision-making</li>\\n                </ul>\\n\\n                <hr>\\n\\n                <h5 class=\\\"fw-bold\\\">Job Roles (Private Sector)</h5>\\n                <ul>\\n                    <li>Content Writer / Editor</li>\\n                    <li>Journalist / Media Professional</li>\\n                    <li>Human Resource Executive</li>\\n                    <li>Policy Analyst / Research Assistant</li>\\n                    <li>NGO / Social Sector Professional</li>\\n                    <li>Market Research Executive</li>\\n                    <li>Corporate Communication Officer</li>\\n                </ul>\\n\\n                <hr>\\n\\n                <h5 class=\\\"fw-bold\\\">Salary Range (India)</h5>\\n                <ul>\\n                    <li>Entry Level: \\u20b92 \\u2013 4 LPA</li>\\n                    <li>Mid-Level (3\\u20136 years): \\u20b94 \\u2013 8 LPA</li>\\n                    <li>Senior / Specialized Roles: \\u20b98+ LPA</li>\\n                </ul>\\n\\n                <hr>\\n\\n                <h5 class=\\\"fw-bold\\\">Government Job Scope</h5>\\n                <ul>\\n                    <li>UPSC Civil Services</li>\\n                    <li>State Public Service Commission Exams</li>\\n                    <li>SSC &amp; Banking Exams</li>\\n                    <li>Teaching &amp; Academic Roles (after B.Ed / M.A.)</li>\\n                    <li>Policy, Planning &amp; Administrative Departments</li>\\n                </ul>\\n\\n                <hr>\\n\\n                <h5 class=\\\"fw-bold\\\">Importance of Internships</h5>\\n                <ul>\\n                    <li>Highly important for research, NGOs, media, and policy roles</li>\\n                    <li>Improves practical understanding of society and institutions</li>\\n                    <li>Strengthens resume for higher studies and jobs</li>\\n                </ul>\\n\\n                <hr>\\n\\n                <h5 class=\\\"fw-bold\\\">Higher Study Options</h5>\\n                <ul>\\n                    <li>M.A. in respective subject</li>\\n                    <li>MBA (HR / Management)</li>\\n                    <li>LLB (Law)</li>\\n                    <li>B.Ed / M.Ed (Teaching)</li>\\n                    <li>Ph.D (Research &amp; Academia)</li>\\n                </ul>\\n\\n                <hr>\\n\\n                <h5 class=\\\"fw-bold\\\">Reality Check (Must Know)</h5>\\n                <ul>\\n                    <li>Career growth depends on specialization and skill-building</li>\\n                    <li>Government exams and higher studies increase stability</li>\\n                    <li>Humanities graduates are valued for thinking and leadership skills</li>\\n                </ul>\\n\\n                <hr>\\n\\n                <h5 class=\\\"fw-bold\\\">Who Should Choose Humanities &amp; Social Sciences?</h5>\\n                <ul>\\n                    <li>Students interested in society, people, and governance</li>\\n                    <li>Aspirants of civil services and public sector jobs</li>\\n                    <li>Students with strong reading, writing, and thinking ability</li>\\n                    <li>Those aiming for research, teaching, or policy roles</li>\\n                </ul>\\n\\n                <hr>\\n\\n                <p class=\\\"fw-semibold text-center text-primary\\\">\\n                    \\u201cHumanities and social sciences shape society, governance, and leadership.\\u201d\\n                </p>\\n\\n            \", \"header_class\": \"modal-header\", \"source_page\": \"12th.html\", \"icon_class\": \"bi-easel\"}'),
(107, 1, 'bhavya', '{\"career\": \"PCM\", \"title\": \"PCM \\u2013 Engineering & Technology Path\", \"description\": \"\\n\\n                        <h6>\\ud83d\\udcd8 What is PCM?</h6>\\n                        <p>\\n                            PCM includes <strong>Physics, Chemistry, and Mathematics</strong>.\\n                            It focuses on logic, problem-solving, machines, and technology.\\n                            PCM is mainly chosen by students who want engineering or technical careers.\\n                        </p>\\n\\n                        <h6>\\ud83d\\udcda Subjects</h6>\\n                        <ul>\\n                            <li><strong>Physics:</strong> Motion, electricity, mechanics, electronics</li>\\n                            <li><strong>Chemistry:</strong> Materials, reactions, fuels, compounds</li>\\n                            <li><strong>Mathematics:</strong> Algebra, calculus, reasoning</li>\\n                        </ul>\\n                        <h6>\\ud83c\\udfeb Board Exam Importance (For PCM Students)</h6>\\n                        <p>\\n                            Your <strong>10th and 12th board marks</strong> play an important role in the PCM path.\\n                        </p>\\n\\n                        <ul>\\n                            <li>\\n                                <strong>After 10th:</strong> Schools use board marks to give admission\\n                                into Science (PCM). Higher marks = better school options.\\n                            </li>\\n                            <li>\\n                                <strong>After 12th:</strong> Board marks are required to be\\n                                <strong>eligible for engineering colleges</strong>.\\n                                Even if you clear JEE, minimum board percentage is compulsory.\\n                            </li>\\n                            <li>\\n                                <strong>College Admissions:</strong> Many private and state colleges\\n                                consider board marks along with entrance exams.\\n                            </li>\\n                        </ul>\\n\\n                        <p class=\\\"text-muted\\\">\\n                            <small>\\n                                Tip: Strong board basics help you perform better in JEE and engineering studies.\\n                            </small>\\n                        </p>\\n\\n                        <h6>\\ud83c\\udfaf Why choose PCM?</h6>\\n                        <ul>\\n                            <li>You like Maths and logic</li>\\n                            <li>You enjoy problem-solving</li>\\n                            <li>You want a technical career</li>\\n                        </ul>\\n\\n                        <h6>\\ud83c\\udfed Job Opportunities</h6>\\n                        <p>\\n                            Engineering, IT companies, software industry, AI &amp; data science,\\n                            defence services, space research, government technical jobs.\\n                        </p>\\n\\n                        <h6>\\ud83d\\udcdd Important Exams</h6>\\n                        <p>\\n                            <strong>JEE (Joint Entrance Examination)</strong> is required for\\n                            engineering colleges like IITs, NITs, and other technical institutes.\\n                        </p>\\n\\n                        <h6>\\u23f1 Duration</h6>\\n                        <p>11\\u201312 PCM (2 years) \\u2192 Engineering (4 years)</p>\\n\\n                        <h6>\\ud83d\\udcb0 Salary</h6>\\n                        <p>\\u20b925,000/month (starter) \\u2192 \\u20b910\\u201320+ LPA (experienced)</p>\\n\\n                        <div class=\\\"alert alert-warning reality-check\\\">\\n                            <strong>Reality Check:</strong> PCM needs daily practice and patience.\\n                            Choose it only if you like Maths.\\n                        </div>\\n\\n                    \", \"header_class\": \"modal-header bg-success text-white\", \"source_page\": \"10th.html\", \"icon_class\": \"bi-calculator\", \"Eligibility\": \"10th Pass (Science & Maths)\", \"Duration\": \"2 Years\", \"Job Opportunities\": \"Very High\", \"Starting Salary\": \"\\u20b925,000\\u201350,000\", \"Growth Potential\": \"High\", \"Job Stability\": \"High\"}'),
(108, 1, 'bhavya', '{\"career\": \"Mobile Repair Technician\", \"title\": \"Mobile Repair Technician\", \"description\": \"\\n                <h6>What is Mobile Repairing?</h6>\\n                <p>\\n                    Mobile repairing is the skill of diagnosing and fixing smartphones and gadgets such as screen\\n                    issues, battery problems, charging faults, and software errors.</p>\\n\\n                <h6>Who can choose this career?</h6>\\n                <p>\\n                    10th / 12th pass or failed students, beginners, and anyone interested in electronics and mobile\\n                    technology. No degree is required.</p>\\n\\n                <h6>Required Skills:</h6>\\n                <p>\\n                    Basic electronics knowledge, problem-solving, hand skills, patience, and customer handling.</p>\\n\\n                <h6>Tools &amp; Equipment Used:</h6>\\n                <p>\\n                    Screwdrivers, multimeter, soldering tools, mobile repairing kits, software flashing tools.</p>\\n\\n                <h6>Equipment Required:</h6>\\n                <p>\\n                    Mobile repair toolkit, spare parts, working table, internet connection.</p>\\n\\n                <h6>Learning Time:</h6>\\n                <p>\\n                    Basic: 1\\u20132 months<br>\\n                    Intermediate: 3\\u20134 months<br>\\n                    Professional: 6 months (with hands-on practice)</p>\\n\\n                <h6>How to Start:</h6>\\n                <p>\\n                    Join a short training course \\u2192 practice repairing phones \\u2192 work under a technician \\u2192 start your own\\n                    repair shop or service.</p>\\n\\n                <h6>Work Type:</h6>\\n                <p>\\n                    Offline (Repair shops), Hybrid (Shop + home service).</p>\\n\\n                <h6>Career Options:</h6>\\n                <p>\\n                    Mobile Repair Technician, Service Center Executive, Gadget Repair Specialist, Own Repair Shop Owner.\\n                </p>\\n\\n                <h6>Income / Salary (India):</h6>\\n                <p>\\n                    Beginner: \\u20b98,000 \\u2013 \\u20b915,000 per month<br>\\n                    Intermediate: \\u20b920,000 \\u2013 \\u20b935,000 per month<br>\\n                    Skilled / Shop Owner: \\u20b950,000+ per month (depends on workload &amp; location)</p>\\n\\n                <h6>Career Growth Path:</h6>\\n                <p>\\n                    Trainee \\u2192 Skilled Technician \\u2192 Senior Technician \\u2192 Own Repair Business.</p>\\n\\n                <h6>Government Scope:</h6>\\n                <p>\\n                    Limited direct government jobs. Mostly private and self-employment based career.</p>\\n\\n                <h6>Where can you work?</h6>\\n                <p>\\n                    Mobile repair shops, service centers, electronics markets, or self-employment.</p>\\n\\n                <p class=\\\"text-danger small\\\">\\n                    \\u26a0 Income depends on repair skills, trust, and customer satisfaction.\\n                </p>\\n\\n                <p class=\\\"fw-semibold text-primary\\\">\\n                    \\ud83d\\udd27 Skilled hands can turn mobile problems into a steady career.\\n                </p>\\n            \", \"header_class\": \"modal-header\", \"source_page\": \"Unique_Career.html\", \"icon_class\": \"bi bi-phone career-icon\", \"Eligibility\": \"8th Pass / 10th Pass\", \"Learning Duration\": \"2\\u20134 Months\", \"Job Opportunities\": \"High\", \"Starting Salary\": \"\\u20b912,000\\u201325,000\", \"Growth Potential\": \"Medium\", \"Job Stability\": \"High\"}'),
(109, 1, 'bhavya', '{\"career\": \"Dance / Choreography\", \"title\": \"Dance / Choreography\", \"description\": \"\\n                <h6>What is Dance / Choreography?</h6>\\n                <p>\\n                    Dance and choreography involve performing dance styles and creating dance routines for stage shows,\\n                    videos, events, and teaching purposes.</p>\\n\\n                <h6>Who can choose this career?</h6>\\n                <p>\\n                    10th / 12th pass or failed students, beginners, and anyone passionate about dance and movement. No\\n                    degree is required.</p>\\n\\n                <h6>Required Skills:</h6>\\n                <p>\\n                    Rhythm sense, flexibility, body coordination, creativity, discipline, and stage confidence.</p>\\n\\n                <h6>Dance Styles &amp; Platforms:</h6>\\n                <p>\\n                    Hip-Hop, Bollywood, Classical, Contemporary, Freestyle; Instagram, YouTube, dance studios.</p>\\n\\n                <h6>Equipment Required:</h6>\\n                <p>\\n                    Practice space, music system, comfortable clothing, smartphone for recording.</p>\\n\\n                <h6>Learning Time:</h6>\\n                <p>\\n                    Basic: 2\\u20133 months<br>\\n                    Intermediate: 6 months<br>\\n                    Professional: 1 year (with regular practice)</p>\\n\\n                <h6>How to Start:</h6>\\n                <p>\\n                    Learn dance basics \\u2192 practice daily \\u2192 perform in videos/events \\u2192 teach or choreograph \\u2192 grow\\n                    personal brand.</p>\\n\\n                <h6>Work Type:</h6>\\n                <p>\\n                    Offline (Studios, events), Online (Classes, content), or Hybrid.</p>\\n\\n                <h6>Career Options:</h6>\\n                <p>\\n                    Dancer, Choreographer, Dance Instructor, Stage Performer, Content Creator.</p>\\n\\n                <h6>Income / Earnings (India):</h6>\\n                <p>\\n                    Beginner: \\u20b95,000 \\u2013 \\u20b912,000 per month<br>\\n                    Intermediate: \\u20b920,000 \\u2013 \\u20b940,000 per month<br>\\n                    Professional: \\u20b960,000+ per month (classes, shows, collaborations)</p>\\n\\n                <h6>Career Growth Path:</h6>\\n                <p>\\n                    Beginner Dancer \\u2192 Skilled Performer \\u2192 Choreographer \\u2192 Own Dance Academy / Brand.</p>\\n\\n                <h6>Government Scope:</h6>\\n                <p>\\n                    Limited direct government jobs. Mostly private, event-based, and self-employment career.</p>\\n\\n                <h6>Where can you work?</h6>\\n                <p>\\n                    Dance studios, schools, events, film projects, online platforms, or self-employment.</p>\\n\\n                <p class=\\\"text-danger small\\\">\\n                    \\u26a0 Income depends on skill level, performance quality, and audience reach.\\n                </p>\\n\\n                <p class=\\\"fw-semibold text-primary\\\">\\n                    \\ud83d\\udc83 If dance is your passion, you can turn movement into a meaningful career.\\n                </p>\\n            \", \"header_class\": \"modal-header\", \"source_page\": \"Unique_Career.html\", \"icon_class\": \"bi bi-music-note-list career-icon\", \"Eligibility\": \"No degree required\", \"Learning Duration\": \"6\\u201312 Months\", \"Job Opportunities\": \"Medium\", \"Starting Salary\": \"\\u20b915,000\\u201335,000\", \"Growth Potential\": \"Medium\", \"Job Stability\": \"Medium\"}'),
(110, 1, 'bhavya', '{\"career\": \"Clerical & Assistant\", \"title\": \"Clerical & Assistant Government Jobs\", \"description\": \"\\n\\n                <!-- INTRO -->\\n                <p class=\\\"text-secondary fs-5 mb-4\\\">\\n                    Clerical &amp; Assistant Government Jobs are entry-level positions in government departments.\\n                    These roles focus on office administration, record keeping, and supporting senior officers\\n                    in daily government work.\\n                </p>\\n\\n                <!-- JOB ROLES -->\\n                <h5 class=\\\"fw-bold text-dark mt-4 mb-3\\\">Common Job Roles</h5>\\n                <ul class=\\\"list-unstyled\\\">\\n                    <li class=\\\"mb-3\\\">\\n                        <strong class=\\\"text-primary\\\">Clerk (LDC / UDC):</strong>\\n                        <span class=\\\"text-muted d-block ms-3\\\">Handles files, office records, data entry, and routine\\n                            administrative work.</span>\\n                    </li>\\n                    <li class=\\\"mb-3\\\">\\n                        <strong class=\\\"text-primary\\\">Office Assistant:</strong>\\n                        <span class=\\\"text-muted d-block ms-3\\\">Supports daily office operations such as documentation,\\n                            correspondence, and coordination.</span>\\n                    </li>\\n                    <li class=\\\"mb-3\\\">\\n                        <strong class=\\\"text-primary\\\">Junior Assistant:</strong>\\n                        <span class=\\\"text-muted d-block ms-3\\\">Assists senior staff with clerical tasks, record\\n                            maintenance, and departmental activities.</span>\\n                    </li>\\n                    <li class=\\\"mb-3\\\">\\n                        <strong class=\\\"text-primary\\\">Data Entry Operator:</strong>\\n                        <span class=\\\"text-muted d-block ms-3\\\">Responsible for entering, updating, and maintaining data\\n                            in government computer systems.</span>\\n                    </li>\\n                    <li class=\\\"mb-3\\\">\\n                        <strong class=\\\"text-primary\\\">Assistant Section Officer:</strong>\\n                        <span class=\\\"text-muted d-block ms-3\\\">Manages official files, drafts notes, and assists in\\n                            decision-making at the section level.</span>\\n                    </li>\\n                </ul>\\n\\n                <!-- WORK NATURE -->\\n                <h5 class=\\\"fw-bold text-dark mt-4 mb-3\\\">Nature of Work</h5>\\n                <ul class=\\\"text-muted\\\">\\n                    <li class=\\\"mb-2\\\">File handling and record maintenance</li>\\n                    <li class=\\\"mb-2\\\">Data entry and office documentation</li>\\n                    <li class=\\\"mb-2\\\">Assisting senior officers</li>\\n                    <li class=\\\"mb-2\\\">Public dealing and basic administrative tasks</li>\\n                </ul>\\n\\n                <!-- ELIGIBILITY -->\\n                <h5 class=\\\"fw-bold text-dark mt-4 mb-3\\\">Eligibility</h5>\\n                <p class=\\\"text-muted bg-light p-3 rounded-3\\\">\\n                    Graduation in any stream from a recognized university.\\n                    Basic computer knowledge and typing skills are usually required.\\n                </p>\\n\\n                <!-- EXAMS -->\\n                <h5 class=\\\"fw-bold text-dark mt-4 mb-3\\\">Exams Required</h5>\\n                <ul class=\\\"text-muted\\\">\\n                    <li>SSC (Staff Selection Commission) examinations</li>\\n                    <li>State government clerical examinations</li>\\n                    <li>Department-specific recruitment exams</li>\\n                </ul>\\n\\n                <!-- SALARY -->\\n                <h5 class=\\\"fw-bold text-dark mt-4 mb-3\\\">Salary (Approximate)</h5>\\n                <p class=\\\"text-success fw-bold fs-5\\\">\\n                    \\u20b925,000 \\u2013 \\u20b940,000 per month <span class=\\\"fs-6 text-muted fw-normal\\\">(including allowances, as per\\n                        pay commission)</span>\\n                </p>\\n\\n                <!-- FACILITIES -->\\n                <h5 class=\\\"fw-bold text-dark mt-4 mb-3\\\">Facilities &amp; Benefits</h5>\\n                <ul class=\\\"text-muted\\\">\\n                    <li>Permanent job security</li>\\n                    <li>Fixed working hours</li>\\n                    <li>Paid leaves and government holidays</li>\\n                    <li>Medical benefits for employee and family</li>\\n                    <li>Pension after retirement</li>\\n                </ul>\\n\\n                <!-- PROMOTION -->\\n                <h5 class=\\\"fw-bold text-dark mt-4 mb-3\\\">Promotion &amp; Career Growth</h5>\\n                <p class=\\\"text-muted\\\">\\n                    Promotions are mostly time-based. Employees can grow from Clerk to Assistant\\n                    and later to Section Officer through experience and departmental exams.\\n                </p>\\n\\n                <!-- RETIREMENT -->\\n                <h5 class=\\\"fw-bold text-dark mt-4 mb-3\\\">Retirement</h5>\\n                <p class=\\\"text-muted\\\">\\n                    The retirement age is generally around 60 years, along with pension\\n                    and post-retirement benefits.\\n                </p>\\n\\n                <!-- REALITY CHECK -->\\n                <div class=\\\"alert alert-light border shadow-sm mt-5\\\">\\n                    <h6 class=\\\"fw-bold text-muted text-uppercase small\\\">Reality Check</h6>\\n                    <ul class=\\\"mb-0 text-muted small\\\">\\n                        <li>Very high competition for limited vacancies</li>\\n                        <li>Slow promotions compared to private sector</li>\\n                        <li>Stable but limited salary growth</li>\\n                        <li>Routine work with low pressure</li>\\n                    </ul>\\n                </div>\\n\\n                <div class=\\\"alert alert-primary text-center mt-3 fw-semibold border-0\\\">\\n                    Best suited for candidates who prefer stability, routine office work, and long-term security.\\n                </div>\\n\\n            \", \"header_class\": \"modal-header border-0 text-white p-4\", \"source_page\": \"Graduation.html\", \"icon_class\": \"bi bi-file-earmark-text\", \"Eligibility\": \"Graduation (Any Stream)\", \"Job Opportunities\": \"High\", \"Starting Salary\": \"\\u20b925,000\\u201340,000/month\", \"Growth Potential\": \"Medium\", \"Job Stability\": \"High\"}'),
(111, 1, 'bhavya', '{\"career\": \"Civil Services\", \"title\": \"Civil Services\", \"description\": \"\\n\\n                <!-- INTRO -->\\n                <p class=\\\"text-muted\\\">\\n                    Civil Services are the highest administrative services in the country.\\n                    Officers in these services play a key role in policy-making, administration,\\n                    governance, law &amp; order, and international relations. These posts carry\\n                    high responsibility, authority, and national importance.\\n                </p>\\n\\n                <!-- JOB ROLES -->\\n                <h6 class=\\\"fw-bold mt-3\\\">Major Civil Services</h6>\\n                <ul class=\\\"text-muted\\\">\\n                    <li>\\n                        <strong>Indian Administrative Service (IAS):</strong>\\n                        Handles administration, development programs, policy implementation,\\n                        and overall governance at district, state, and central levels.\\n                    </li>\\n                    <li>\\n                        <strong>Indian Police Service (IPS):</strong>\\n                        Responsible for maintaining law and order, internal security,\\n                        crime prevention, and police administration.\\n                    </li>\\n                    <li>\\n                        <strong>Indian Foreign Service (IFS):</strong>\\n                        Manages India\\u2019s foreign relations, diplomacy, international negotiations,\\n                        and represents India in foreign countries.\\n                    </li>\\n                    <li>\\n                        <strong>Indian Revenue Service (IRS):</strong>\\n                        Deals with tax administration, revenue collection,\\n                        and enforcement of financial laws.\\n                    </li>\\n                </ul>\\n\\n                <!-- WORK NATURE -->\\n                <h6 class=\\\"fw-bold mt-3\\\">Nature of Work</h6>\\n                <ul class=\\\"text-muted\\\">\\n                    <li>Policy formulation and implementation</li>\\n                    <li>Administration of districts, states, or departments</li>\\n                    <li>Law &amp; order and crisis management</li>\\n                    <li>Decision-making at national and international levels</li>\\n                    <li>High public interaction and leadership roles</li>\\n                </ul>\\n\\n                <!-- ELIGIBILITY -->\\n                <h6 class=\\\"fw-bold mt-3\\\">Eligibility</h6>\\n                <p class=\\\"text-muted\\\">\\n                    Graduation in any stream from a recognized university.\\n                    There is no restriction on degree type (Arts, Commerce, Science, Engineering, etc.).\\n                </p>\\n\\n                <!-- AGE LIMIT -->\\n                <h6 class=\\\"fw-bold mt-3\\\">Age Requirement</h6>\\n                <p class=\\\"text-muted\\\">\\n                    Minimum age is <strong>21 years</strong>. Upper age limit varies by category\\n                    and government rules.\\n                </p>\\n\\n                <!-- EXAMS -->\\n                <h6 class=\\\"fw-bold mt-3\\\">Exam Required</h6>\\n                <ul class=\\\"text-muted\\\">\\n                    <li>UPSC Civil Services Examination (Prelims, Mains, Interview)</li>\\n                </ul>\\n\\n                <!-- SALARY -->\\n                <h6 class=\\\"fw-bold mt-3\\\">Salary (Approximate)</h6>\\n                <p class=\\\"text-muted\\\">\\n                    Starting basic pay is around \\u20b956,100 per month.\\n                    At senior levels, salary can go up to \\u20b92,50,000 per month,\\n                    excluding allowances.\\n                </p>\\n\\n                <!-- FACILITIES -->\\n                <h6 class=\\\"fw-bold mt-3\\\">Facilities &amp; Benefits</h6>\\n                <ul class=\\\"text-muted\\\">\\n                    <li>Official residence and vehicle</li>\\n                    <li>High job security</li>\\n                    <li>Medical facilities for self and family</li>\\n                    <li>Staff support and allowances</li>\\n                    <li>Pension and post-retirement benefits</li>\\n                </ul>\\n\\n                <!-- PROMOTION -->\\n                <h6 class=\\\"fw-bold mt-3\\\">Promotion &amp; Career Growth</h6>\\n                <p class=\\\"text-muted\\\">\\n                    Career growth is structured and time-based.\\n                    Officers progress to senior administrative, director-level,\\n                    and secretary-level positions over time.\\n                </p>\\n\\n                <!-- RETIREMENT -->\\n                <h6 class=\\\"fw-bold mt-3\\\">Retirement</h6>\\n                <p class=\\\"text-muted\\\">\\n                    The retirement age is generally <strong>60 years</strong>,\\n                    along with pension and lifelong post-retirement benefits.\\n                </p>\\n\\n                <!-- REALITY CHECK -->\\n                <h6 class=\\\"fw-bold mt-3\\\">Reality Check</h6>\\n                <ul class=\\\"text-muted\\\">\\n                    <li>Extremely competitive examination</li>\\n                    <li>Long and demanding preparation period</li>\\n                    <li>Very high responsibility and public accountability</li>\\n                    <li>Transfers and political pressure may exist</li>\\n                    <li>High respect, authority, and national impact</li>\\n                </ul>\\n\\n                <div class=\\\"alert alert-info text-center mt-3 fw-semibold\\\">\\n                    Best suited for highly dedicated candidates with leadership qualities,\\n                    patience, and a strong desire to serve the nation.\\n                </div>\\n\\n            \", \"header_class\": \"modal-header border-0 text-white p-4\", \"source_page\": \"Graduation.html\", \"icon_class\": \"bi bi-award\", \"Eligibility\": \"Graduation (Any Stream)\", \"Job Opportunities\": \"Low\", \"Starting Salary\": \"\\u20b956,100\\u20132,50,000+/month\", \"Growth Potential\": \"Very High\", \"Job Stability\": \"Very High\"}');
